{"command":"cd /workspace && cat > jsonenc/jsonenc.go <<'EOF'
// Package jsonenc writes ordered values as JSON text.
package jsonenc

import (
	"errors"
	"math"
	"strconv"
	"time"
	"unicode/utf8"

	"yj/order"
)

// Options control the JSON output.
type Options struct {
	EscapeHTML bool
	Indent     bool
}

const hexDigits = "0123456789abcdef"

type encoder struct {
	buf  []byte
	opts Options
}

// Marshal encodes v as compact (or indented) JSON without a trailing newline.
func Marshal(v interface{}, opts Options) ([]byte, error) {
	e := &encoder{opts: opts}
	if err := e.value(v, 0); err != nil {
		return nil, err
	}
	return e.buf, nil
}

func (e *encoder) newline(depth int) {
	if !e.opts.Indent {
		return
	}
	e.buf = append(e.buf, '\n')
	for i := 0; i < depth; i++ {
		e.buf = append(e.buf, ' ', ' ')
	}
}

func (e *encoder) value(v interface{}, depth int) error {
	switch v := v.(type) {
	case nil:
		e.buf = append(e.buf, "null"...)
	case bool:
		e.buf = strconv.AppendBool(e.buf, v)
	case string:
		e.buf = AppendString(e.buf, v, e.opts.EscapeHTML)
	case int:
		e.buf = strconv.AppendInt(e.buf, int64(v), 10)
	case int64:
		e.buf = strconv.AppendInt(e.buf, v, 10)
	case uint64:
		e.buf = strconv.AppendUint(e.buf, v, 10)
	case float64:
		e.buf = AppendFloat(e.buf, v)
	case time.Time:
		if y := v.Year(); y < 0 || y >= 10000 {
			return errors.New("json: error calling MarshalJSON for type time.Time: Time.MarshalJSON: year outside of range [0,9999]")
		}
		e.buf = append(e.buf, '"')
		e.buf = v.AppendFormat(e.buf, time.RFC3339Nano)
		e.buf = append(e.buf, '"')
	case []interface{}:
		if len(v) == 0 {
			e.buf = append(e.buf, '[', ']')
			return nil
		}
		e.buf = append(e.buf, '[')
		for i, x := range v {
			if i > 0 {
				e.buf = append(e.buf, ',')
			}
			e.newline(depth + 1)
			if err := e.value(x, depth+1); err != nil {
				return err
			}
		}
		e.newline(depth)
		e.buf = append(e.buf, ']')
	case order.MapSlice:
		if len(v) == 0 {
			e.buf = append(e.buf, '{', '}')
			return nil
		}
		e.buf = append(e.buf, '{')
		for i, item := range v {
			if i > 0 {
				e.buf = append(e.buf, ',')
			}
			e.newline(depth + 1)
			k, _ := item.Key.(string)
			e.buf = AppendString(e.buf, k, e.opts.EscapeHTML)
			e.buf = append(e.buf, ':')
			if e.opts.Indent {
				e.buf = append(e.buf, ' ')
			}
			if err := e.value(item.Val, depth+1); err != nil {
				return err
			}
		}
		e.newline(depth)
		e.buf = append(e.buf, '}')
	default:
		return errors.New("json: unsupported type")
	}
	return nil
}

// AppendFloat formats f the way encoding/json does. Infinities are clamped
// to the largest finite value and NaN is written as null.
func AppendFloat(b []byte, f float64) []byte {
	if math.IsNaN(f) {
		return append(b, "null"...)
	}
	if math.IsInf(f, 1) {
		f = math.MaxFloat64
	} else if math.IsInf(f, -1) {
		f = -math.MaxFloat64
	}
	abs := math.Abs(f)
	fmtc := byte('f')
	if abs != 0 && (abs < 1e-6 || abs >= 1e21) {
		fmtc = 'e'
	}
	b = strconv.AppendFloat(b, f, fmtc, -1, 64)
	if fmtc == 'e' {
		n := len(b)
		if n >= 4 && b[n-4] == 'e' && b[n-3] == '-' && b[n-2] == '0' {
			b[n-2] = b[n-1]
			b = b[:n-1]
		}
	}
	return b
}

// AppendString appends the JSON quoted form of s.
func AppendString(dst []byte, s string, escapeHTML bool) []byte {
	dst = append(dst, '"')
	start := 0
	for i := 0; i < len(s); {
		if b := s[i]; b < utf8.RuneSelf {
			if b >= 0x20 && b != '"' && b != '\\' && (!escapeHTML || (b != '<' && b != '>' && b != '&')) {
				i++
				continue
			}
			dst = append(dst, s[start:i]...)
			switch b {
			case '\\', '"':
				dst = append(dst, '\\', b)
			case '\n':
				dst = append(dst, '\\', 'n')
			case '\r':
				dst = append(dst, '\\', 'r')
			case '\t':
				dst = append(dst, '\\', 't')
			default:
				dst = append(dst, '\\', 'u', '0', '0', hexDigits[b>>4], hexDigits[b&0xF])
			}
			i++
			start = i
			continue
		}
		c, size := utf8.DecodeRuneInString(s[i:])
		if c == utf8.RuneError && size == 1 {
			dst = append(dst, s[start:i]...)
			dst = append(dst, `\ufffd`...)
			i += size
			start = i
			continue
		}
		if c == '\u2028' || c == '\u2029' {
			dst = append(dst, s[start:i]...)
			dst = append(dst, '\\', 'u', '2', '0', '2', hexDigits[c&0xF])
			i += size
			start = i
			continue
		}
		i += size
	}
	dst = append(dst, s[start:]...)
	dst = append(dst, '"')
	return dst
}
EOF
echo ok"}

