{"command":"cd /workspace && cat > yaml/reader.go <<'EOF'
package yaml

const rawChunkSize = 512

type encodingKind int

const (
	encAny encodingKind = iota
	encUTF8
	encUTF16LE
	encUTF16BE
)

// parser holds the reader, scanner and parser state.
type parser struct {
	// Error state.
	err         errorKind
	problem     string
	problemMark mark
	context     string
	contextMark mark

	// Reader state.
	input    []byte
	inputPos int
	raw      []byte
	rawPos   int
	eof      bool
	encoding encodingKind
	offset   int
	buf      []byte
	pos      int
	unread   int

	mark mark

	// Scanner state.
	streamStartProduced bool
	streamEndProduced   bool
	flowLevel           int
	tokens              []token
	tokensHead          int
	tokensParsed        int
	tokenAvailable      bool
	indent              int
	indents             []int
	simpleKeyAllowed    bool
	simpleKeys          []simpleKey
	simpleKeysByTok     map[int]int
	newlines            int

	// Parser state.
	state         parserState
	states        []parserState
	marks         []mark
	tagDirectives []tagDirective
}

func newParser(input []byte) *parser {
	return &parser{
		input:           input,
		raw:             make([]byte, 0, rawChunkSize),
		simpleKeysByTok: map[int]int{},
		indent:          -1,
	}
}

func (p *parser) setReaderError(problem string) bool {
	p.err = readerError
	p.problem = problem
	return false
}

func (p *parser) updateRawBuffer() bool {
	if p.rawPos == 0 && len(p.raw) == cap(p.raw) {
		return true
	}
	if p.eof {
		return true
	}
	if p.rawPos > 0 && p.rawPos < len(p.raw) {
		copy(p.raw, p.raw[p.rawPos:])
	}
	p.raw = p.raw[:len(p.raw)-p.rawPos]
	p.rawPos = 0
	if p.inputPos == len(p.input) {
		p.eof = true
		return true
	}
	n := copy(p.raw[len(p.raw):cap(p.raw)], p.input[p.inputPos:])
	p.inputPos += n
	p.raw = p.raw[:len(p.raw)+n]
	return true
}

func (p *parser) determineEncoding() bool {
	for !p.eof && len(p.raw)-p.rawPos < 3 {
		if !p.updateRawBuffer() {
			return false
		}
	}
	b := p.raw
	pos := p.rawPos
	avail := len(b) - pos
	switch {
	case avail >= 2 && b[pos] == 0xFF && b[pos+1] == 0xFE:
		p.encoding = encUTF16LE
		p.rawPos += 2
		p.offset += 2
	case avail >= 2 && b[pos] == 0xFE && b[pos+1] == 0xFF:
		p.encoding = encUTF16BE
		p.rawPos += 2
		p.offset += 2
	case avail >= 3 && b[pos] == 0xEF && b[pos+1] == 0xBB && b[pos+2] == 0xBF:
		p.encoding = encUTF8
		p.rawPos += 3
		p.offset += 3
	default:
		p.encoding = encUTF8
	}
	return true
}

// cache ensures that at least n characters are available in the buffer.
func (p *parser) cache(n int) bool {
	if p.unread >= n {
		return true
	}
	return p.updateBuffer(n)
}

func (p *parser) updateBuffer(length int) bool {
	if p.unread >= length {
		return true
	}
	if p.encoding == encAny {
		if !p.determineEncoding() {
			return false
		}
	}
	// Drop consumed bytes occasionally to keep memory bounded.
	if p.pos > 1<<16 {
		p.buf = append(p.buf[:0], p.buf[p.pos:]...)
		p.pos = 0
	}
	first := true
	for p.unread < length {
		if !first || p.rawPos == len(p.raw) {
			if !p.updateRawBuffer() {
				return false
			}
		}
		first = false
	inner:
		for p.rawPos != len(p.raw) {
			var value rune
			var width int
			rawUnread := len(p.raw) - p.rawPos
			switch p.encoding {
			case encUTF8:
				octet := p.raw[p.rawPos]
				switch {
				case octet&0x80 == 0x00:
					width = 1
				case octet&0xE0 == 0xC0:
					width = 2
				case octet&0xF0 == 0xE0:
					width = 3
				case octet&0xF8 == 0xF0:
					width = 4
				default:
					return p.setReaderError("invalid leading UTF-8 octet")
				}
				if width > rawUnread {
					if p.eof {
						return p.setReaderError("incomplete UTF-8 octet sequence")
					}
					break inner
				}
