package yaml

import "bytes"

func (p *parser) skip() {
	if !p.isBlank(p.pos) {
		p.newlines = 0
	}
	p.mark.index++
	p.mark.column++
	p.unread--
	p.pos += width(p.buf[p.pos])
}

func (p *parser) skipLine() {
	if p.isCRLF(p.pos) {
		p.mark.index += 2
		p.mark.column = 0
		p.mark.line++
		p.unread -= 2
		p.pos += 2
		p.newlines++
	} else if p.isBreak(p.pos) {
		p.mark.index++
		p.mark.column = 0
		p.mark.line++
		p.unread--
		p.pos += width(p.buf[p.pos])
		p.newlines++
	}
}

func (p *parser) read(s []byte) []byte {
	if !p.isBlank(p.pos) {
		p.newlines = 0
	}
	w := width(p.buf[p.pos])
	if w == 0 {
		panic("invalid character sequence")
	}
	s = append(s, p.buf[p.pos:p.pos+w]...)
	p.pos += w
	p.mark.index++
	p.mark.column++
	p.unread--
	return s
}

func (p *parser) readLine(s []byte) []byte {
	b0, b1, b2 := p.at(p.pos), p.at(p.pos+1), p.at(p.pos+2)
	switch {
	case b0 == '\r' && b1 == '\n':
		s = append(s, '\n')
		p.pos += 2
		p.mark.index++
		p.unread--
	case b0 == '\r' || b0 == '\n':
		s = append(s, '\n')
		p.pos++
	case b0 == 0xC2 && b1 == 0x85:
		s = append(s, '\n')
		p.pos += 2
	case b0 == 0xE2 && b1 == 0x80 && (b2 == 0xA8 || b2 == 0xA9):
		s = append(s, p.buf[p.pos:p.pos+3]...)
		p.pos += 3
	default:
		return s
	}
	p.mark.index++
	p.mark.column = 0
	p.mark.line++
	p.unread--
	p.newlines++
	return s
}

// peekToken returns the next token without consuming it.
func (p *parser) peekToken() *token {
	if p.tokenAvailable || p.fetchMoreTokens() {
		return &p.tokens[p.tokensHead]
	}
	return nil
}

func (p *parser) skipToken() {
	p.tokenAvailable = false
	p.tokensParsed++
	p.streamEndProduced = p.tokens[p.tokensHead].typ == tStreamEnd
	p.tokensHead++
}

func (p *parser) setScannerError(context string, contextMark mark, problem string) bool {
	p.err = scannerError
	p.context = context
	p.contextMark = contextMark
	p.problem = problem
	p.problemMark = p.mark
	return false
}

func (p *parser) setScannerTagError(directive bool, contextMark mark, problem string) bool {
	context := "while parsing a tag"
	if directive {
		context = "while parsing a %TAG directive"
	}
	return p.setScannerError(context, contextMark, problem)
}

func (p *parser) insertToken(pos int, tok *token) {
	if p.tokensHead > 0 && len(p.tokens) == cap(p.tokens) {
		if p.tokensHead != len(p.tokens) {
			copy(p.tokens, p.tokens[p.tokensHead:])
		}
		p.tokens = p.tokens[:len(p.tokens)-p.tokensHead]
		p.tokensHead = 0
	}
	p.tokens = append(p.tokens, *tok)
	if pos < 0 {
		return
	}
	copy(p.tokens[p.tokensHead+pos+1:], p.tokens[p.tokensHead+pos:])
	p.tokens[p.tokensHead+pos] = *tok
}

func (p *parser) fetchMoreTokens() bool {
	for {
		if p.tokensHead < len(p.tokens)-2 {
			headTokIdx, ok := p.simpleKeysByTok[p.tokensParsed]
			if !ok {
				break
			} else if valid, ok := p.simpleKeyIsValid(&p.simpleKeys[headTokIdx]); !ok {
				return false
			} else if !valid {
				break
			}
		}
		if !p.fetchNextToken() {
			return false
		}
	}
	p.tokenAvailable = true
	return true
}

func (p *parser) fetchNextToken() (ok bool) {
	if !p.cache(1) {
		return false
	}
	if !p.streamStartProduced {
		return p.fetchStreamStart()
	}
	scanMark := p.mark
	if !p.scanToNextToken() {
		return false
	}
	if !p.unrollIndent(p.mark.column, scanMark) {
		return false
	}
	if !p.cache(4) {
		return false
	}
	if p.isZ(p.pos) {
		return p.fetchStreamEnd()
	}
	c := p.ch()
	if p.mark.column == 0 && c == '%' {
		return p.fetchDirective()
	}
	if p.mark.column == 0 && c == '-' && p.at(p.pos+1) == '-' && p.at(p.pos+2) == '-' && p.isBlankZ(p.pos+3) {
		return p.fetchDocumentIndicator(tDocumentStart)
	}
	if p.mark.column == 0 && c == '.' && p.at(p.pos+1) == '.' && p.at(p.pos+2) == '.' && p.isBlankZ(p.pos+3) {
		return p.fetchDocumentIndicator(tDocumentEnd)
	}

	defer func() {
		if !ok {
			return
		}
		if len(p.tokens) > 0 && p.tokens[len(p.tokens)-1].typ == tBlockEntry {
			return
		}
		if !p.scanLineComment() {
			ok = false
		}
	}()

	switch c {
	case '[':
		return p.fetchFlowCollectionStart(tFlowSequenceStart)
	case '{':
		return p.fetchFlowCollectionStart(tFlowMappingStart)
	case ']':
		return p.fetchFlowCollectionEnd(tFlowSequenceEnd)
	case '}':
		return p.fetchFlowCollectionEnd(tFlowMappingEnd)
	case ',':
		return p.fetchFlowEntry()
	}
	if c == '-' && p.isBlankZ(p.pos+1) {
		return p.fetchBlockEntry()
	}
	if c == '?' && (p.flowLevel > 0 || p.isBlankZ(p.pos+1)) {
		return p.fetchKey()
	}
	if c == ':' && (p.flowLevel > 0 || p.isBlankZ(p.pos+1)) {
		return p.fetchValue()
	}
	if c == '*' {
		return p.fetchAnchor(tAlias)
	}
	if c == '&' {
		return p.fetchAnchor(tAnchor)
	}
	if c == '!' {
		return p.fetchTag()
	}
	if c == '|' && p.flowLevel == 0 {
		return p.fetchBlockScalar(true)
	}
	if c == '>' && p.flowLevel == 0 {
		return p.fetchBlockScalar(false)
	}
	if c == '\'' {
		return p.fetchFlowScalar(true)
	}
	if c == '"' {
		return p.fetchFlowScalar(false)
	}
	if !(p.isBlankZ(p.pos) || c == '-' || c == '?' || c == ':' || c == ',' || c == '[' || c == ']' ||
		c == '{' || c == '}' || c == '#' || c == '&' || c == '*' || c == '!' || c == '|' || c == '>' ||
		c == '\'' || c == '"' || c == '%' || c == '@' || c == '`') ||
		(c == '-' && !p.isBlank(p.pos+1)) ||
		(p.flowLevel == 0 && (c == '?' || c == ':') && !p.isBlankZ(p.pos+1)) {
		return p.fetchPlainScalar()
	}
	return p.setScannerError("while scanning for the next token", p.mark,
		"found character that cannot start any token")
}

func (p *parser) simpleKeyIsValid(sk *simpleKey) (valid, ok bool) {
	if !sk.possible {
		return false, true
	}
	if sk.mark.line < p.mark.line || sk.mark.index+1024 < p.mark.index {
		if sk.required {
			return false, p.setScannerError("while scanning a simple key", sk.mark,
				"could not find expected ':'")
		}
		sk.possible = false
		return false, true
	}
	return true, true
}

func (p *parser) saveSimpleKey() bool {
	required := p.flowLevel == 0 && p.indent == p.mark.column
	if p.simpleKeyAllowed {
		sk := simpleKey{
			possible:    true,
			required:    required,
			tokenNumber: p.tokensParsed + (len(p.tokens) - p.tokensHead),
			mark:        p.mark,
		}
		if !p.removeSimpleKey() {
			return false
		}
		p.simpleKeys[len(p.simpleKeys)-1] = sk
		p.simpleKeysByTok[sk.tokenNumber] = len(p.simpleKeys) - 1
	}
	return true
}

func (p *parser) removeSimpleKey() bool {
	i := len(p.simpleKeys) - 1
	if p.simpleKeys[i].possible {
		if p.simpleKeys[i].required {
			return p.setScannerError("while scanning a simple key", p.simpleKeys[i].mark,
				"could not find expected ':'")
		}
		p.simpleKeys[i].possible = false
		delete(p.simpleKeysByTok, p.simpleKeys[i].tokenNumber)
	}
	return true
}

const maxFlowLevel = 10000

func (p *parser) increaseFlowLevel() bool {
	p.simpleKeys = append(p.simpleKeys, simpleKey{
		possible:    false,
		required:    false,
		tokenNumber: 0,
		mark:        p.mark,
	})
	p.flowLevel++
	if p.flowLevel > maxFlowLevel {
		return p.setScannerError("while increasing flow level", p.simpleKeys[len(p.simpleKeys)-1].mark,
			"exceeded max depth of 10000")
	}
	return true
}

func (p *parser) decreaseFlowLevel() bool {
	if p.flowLevel > 0 {
		p.flowLevel--
		last := len(p.simpleKeys) - 1
		delete(p.simpleKeysByTok, p.simpleKeys[last].tokenNumber)
		p.simpleKeys = p.simpleKeys[:last]
	}
	return true
}

const maxIndents = 10000

func (p *parser) rollIndent(column, number int, typ tokenType, m mark) bool {
	if p.flowLevel > 0 {
		return true
	}
	if p.indent < column {
		p.indents = append(p.indents, p.indent)
		p.indent = column
		if len(p.indents) > maxIndents {
			return p.setScannerError("while increasing indent level", p.simpleKeys[len(p.simpleKeys)-1].mark,
				"exceeded max depth of 10000")
		}
		tok := token{typ: typ, startMark: m, endMark: m}
		if number > -1 {
			number -= p.tokensParsed
		}
		p.insertToken(number, &tok)
	}
	return true
}

func (p *parser) unrollIndent(column int, scanMark mark) bool {
	if p.flowLevel > 0 {
		return true
	}
	for p.indent > column {
		tok := token{typ: tBlockEnd, startMark: p.mark, endMark: p.mark}
		p.insertToken(-1, &tok)
		p.indent = p.indents[len(p.indents)-1]
		p.indents = p.indents[:len(p.indents)-1]
	}
	return true
}

func (p *parser) fetchStreamStart() bool {
	p.indent = -1
	p.simpleKeys = append(p.simpleKeys, simpleKey{})
	p.simpleKeysByTok = map[int]int{}
	p.simpleKeyAllowed = true
	p.streamStartProduced = true
	tok := token{typ: tStreamStart, startMark: p.mark, endMark: p.mark}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchStreamEnd() bool {
	if p.mark.column != 0 {
		p.mark.column = 0
		p.mark.line++
	}
	if !p.unrollIndent(-1, p.mark) {
		return false
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	tok := token{typ: tStreamEnd, startMark: p.mark, endMark: p.mark}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchDirective() bool {
	if !p.unrollIndent(-1, p.mark) {
		return false
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	tok := token{}
	if !p.scanDirective(&tok) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchDocumentIndicator(typ tokenType) bool {
	if !p.unrollIndent(-1, p.mark) {
		return false
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	start := p.mark
	p.skip()
	p.skip()
	p.skip()
	end := p.mark
	tok := token{typ: typ, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowCollectionStart(typ tokenType) bool {
	if !p.saveSimpleKey() {
		return false
	}
	if !p.increaseFlowLevel() {
		return false
	}
	p.simpleKeyAllowed = true
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: typ, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowCollectionEnd(typ tokenType) bool {
	if !p.removeSimpleKey() {
		return false
	}
	if !p.decreaseFlowLevel() {
		return false
	}
	p.simpleKeyAllowed = false
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: typ, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowEntry() bool {
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = true
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tFlowEntry, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchBlockEntry() bool {
	if p.flowLevel == 0 {
		if !p.simpleKeyAllowed {
			return p.setScannerError("", p.mark, "block sequence entries are not allowed in this context")
		}
		if !p.rollIndent(p.mark.column, -1, tBlockSequenceStart, p.mark) {
			return false
		}
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = true
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tBlockEntry, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchKey() bool {
	if p.flowLevel == 0 {
		if !p.simpleKeyAllowed {
			return p.setScannerError("", p.mark, "mapping keys are not allowed in this context")
		}
		if !p.rollIndent(p.mark.column, -1, tBlockMappingStart, p.mark) {
			return false
		}
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = p.flowLevel == 0
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tKey, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchValue() bool {
	sk := &p.simpleKeys[len(p.simpleKeys)-1]
	if valid, ok := p.simpleKeyIsValid(sk); !ok {
		return false
	} else if valid {
		tok := token{typ: tKey, startMark: sk.mark, endMark: sk.mark}
		p.insertToken(sk.tokenNumber-p.tokensParsed, &tok)
		if !p.rollIndent(sk.mark.column, sk.tokenNumber, tBlockMappingStart, sk.mark) {
			return false
		}
		sk.possible = false
		delete(p.simpleKeysByTok, sk.tokenNumber)
		p.simpleKeyAllowed = false
	} else {
		if p.flowLevel == 0 {
			if !p.simpleKeyAllowed {
				return p.setScannerError("", p.mark, "mapping values are not allowed in this context")
			}
			if !p.rollIndent(p.mark.column, -1, tBlockMappingStart, p.mark) {
				return false
			}
		}
		p.simpleKeyAllowed = p.flowLevel == 0
	}
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tValue, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchAnchor(typ tokenType) bool {
	if !p.saveSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	var tok token
	if !p.scanAnchor(&tok, typ) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchTag() bool {
	if !p.saveSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	var tok token
	if !p.scanTag(&tok) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchBlockScalar(literal bool) bool {
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = true
	var tok token
	if !p.scanBlockScalar(&tok, literal) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowScalar(single bool) bool {
	if !p.saveSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	var tok token
	if !p.scanFlowScalar(&tok, single) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchPlainScalar() bool {
	if !p.saveSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	var tok token
	if !p.scanPlainScalar(&tok) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) scanToNextToken() bool {
	scanMark := p.mark
	for {
		if !p.cache(1) {
			return false
		}
		if p.mark.column == 0 && p.isBOM(p.pos) {
			p.skip()
		}
		if !p.cache(1) {
			return false
		}
		for p.ch() == ' ' || ((p.flowLevel > 0 || !p.simpleKeyAllowed) && p.ch() == '\t') {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
		if p.ch() == '#' {
			if !p.scanComments(scanMark) {
				return false
			}
		}
		if p.isBreak(p.pos) {
			if !p.cache(2) {
				return false
			}
			p.skipLine()
			if p.flowLevel == 0 {
				p.simpleKeyAllowed = true
			}
		} else {
			break
		}
	}
	return true
}

// scanComments consumes a run of comment lines.
func (p *parser) scanComments(scanMark mark) bool {
	peek := 0
	for ; peek < 512; peek++ {
		if p.unread < peek+1 && !p.updateBuffer(peek+1) {
			break
		}
		if p.isBlank(p.pos + peek) {
			continue
		}
		c := p.at(p.pos + peek)
		closeFlow := p.flowLevel > 0 && (c == ']' || c == '}')
		if closeFlow || p.isBreakZ(p.pos+peek) {
			if !p.isBreak(p.pos + peek) {
				break
			}
			continue
		}
		if c != '#' {
			break
		}
		seen := p.mark.index + peek
		for {
			if !p.cache(1) {
				return false
			}
			if p.isBreakZ(p.pos) {
				if p.mark.index >= seen {
					break
				}
				if !p.cache(2) {
					return false
				}
				p.skipLine()
			} else if p.mark.index >= seen {
				p.read(nil)
			} else {
				p.skip()
			}
		}
		peek = 0
	}
	return true
}

func (p *parser) scanLineComment() bool {
	if p.newlines > 0 {
		return true
	}
	for peek := 0; peek < 512; peek++ {
		if p.unread < peek+1 && !p.updateBuffer(peek+1) {
			break
		}
		if p.isBlank(p.pos + peek) {
			continue
		}
		if p.at(p.pos+peek) == '#' {
			seen := p.mark.index + peek
			for {
				if !p.cache(1) {
					return false
				}
				if p.isBreakZ(p.pos) {
					if p.mark.index >= seen {
						break
					}
					if !p.cache(2) {
						return false
					}
					p.skipLine()
				} else if p.mark.index >= seen {
					p.read(nil)
				} else {
					p.skip()
				}
			}
		}
		break
	}
	return true
}

func (p *parser) scanDirective(tok *token) bool {
	start := p.mark
	p.skip()
	var name []byte
	if !p.scanDirectiveName(start, &name) {
		return false
	}
	if bytes.Equal(name, []byte("YAML")) {
		var major, minor int
		if !p.scanVersionDirectiveValue(start, &major, &minor) {
			return false
		}
		end := p.mark
		*tok = token{typ: tVersionDirective, startMark: start, endMark: end, major: major, minor: minor}
	} else if bytes.Equal(name, []byte("TAG")) {
		var handle, prefix []byte
		if !p.scanTagDirectiveValue(start, &handle, &prefix) {
			return false
		}
		end := p.mark
		*tok = token{typ: tTagDirective, startMark: start, endMark: end, value: handle, prefix: prefix}
	} else {
		p.setScannerError("while scanning a directive", start, "found unknown directive name")
		return false
	}
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if p.ch() == '#' {
		for !p.isBreakZ(p.pos) {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
	}
	if !p.isBreakZ(p.pos) {
		p.setScannerError("while scanning a directive", start, "did not find expected comment or line break")
		return false
	}
	if p.isBreak(p.pos) {
		if !p.cache(2) {
			return false
		}
		p.skipLine()
	}
	return true
}

func (p *parser) scanDirectiveName(start mark, name *[]byte) bool {
	if !p.cache(1) {
		return false
	}
	var s []byte
	for p.isAlpha(p.pos) {
		s = p.read(s)
		if !p.cache(1) {
			return false
		}
	}
	if len(s) == 0 {
		p.setScannerError("while scanning a directive", start, "could not find expected directive name")
		return false
	}
	if !p.isBlankZ(p.pos) {
		p.setScannerError("while scanning a directive", start, "found unexpected non-alphabetical character")
		return false
	}
	*name = s
	return true
}

func (p *parser) scanVersionDirectiveValue(start mark, major, minor *int) bool {
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if !p.scanVersionDirectiveNumber(start, major) {
		return false
	}
	if p.ch() != '.' {
		return p.setScannerError("while scanning a %YAML directive", start, "did not find expected digit or '.' character")
	}
	p.skip()
	if !p.scanVersionDirectiveNumber(start, minor) {
		return false
	}
	return true
}

func (p *parser) scanVersionDirectiveNumber(start mark, number *int) bool {
	if !p.cache(1) {
		return false
	}
	value := 0
	length := 0
	for p.isDigit(p.pos) {
		length++
		if length > 9 {
			return p.setScannerError("while scanning a %YAML directive", start, "found extremely long version number")
		}
		value = value*10 + p.asDigit(p.pos)
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if length == 0 {
		return p.setScannerError("while scanning a %YAML directive", start, "did not find expected version number")
	}
	*number = value
	return true
}

func (p *parser) scanTagDirectiveValue(start mark, handle, prefix *[]byte) bool {
	var h, pr []byte
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if !p.scanTagHandle(true, start, &h) {
		return false
	}
	if !p.cache(1) {
		return false
	}
	if !p.isBlank(p.pos) {
		p.setScannerError("while scanning a %TAG directive", start, "did not find expected whitespace")
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if !p.scanTagURI(true, true, nil, start, &pr) {
		return false
	}
	if !p.cache(1) {
		return false
	}
	if !p.isBlankZ(p.pos) {
		p.setScannerError("while scanning a %TAG directive", start, "did not find expected whitespace or line break")
		return false
	}
	*handle = h
	*prefix = pr
	return true
}

func (p *parser) scanAnchor(tok *token, typ tokenType) bool {
	var s []byte
	start := p.mark
	p.skip()
	if !p.cache(1) {
		return false
	}
	for p.isAnchorChar(p.pos) {
		s = p.read(s)
		if !p.cache(1) {
			return false
		}
	}
	end := p.mark
	if len(s) == 0 || !(p.isBlankZ(p.pos) || p.ch() == '?' || p.ch() == ':' || p.ch() == ',' || p.ch() == ']' ||
		p.ch() == '}' || p.ch() == '%' || p.ch() == '@' || p.ch() == '`') {
		context := "while scanning an alias"
		if typ == tAnchor {
			context = "while scanning an anchor"
		}
		p.setScannerError(context, start, "did not find expected alphabetic or numeric character")
		return false
	}
	*tok = token{typ: typ, startMark: start, endMark: end, value: s}
	return true
}

func (p *parser) isAnchorChar(i int) bool {
	c := p.at(i)
	if c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
		return false
	}
	if p.isBlankZ(i) {
		return false
	}
	return p.isPrintable(i) && !p.isBOM(i)
}

func (p *parser) isPrintable(i int) bool {
	b := p.at(i)
	b1 := p.at(i + 1)
	b2 := p.at(i + 2)
	return b == 0x0A || (b >= 0x20 && b <= 0x7E) ||
		(b == 0xC2 && b1 >= 0xA0) ||
		(b > 0xC2 && b < 0xED) ||
		(b == 0xED && b1 < 0xA0) ||
		(b == 0xEE) ||
		(b == 0xEF && !(b1 == 0xBB && b2 == 0xBF) && !(b1 == 0xBF && (b2 == 0xBE || b2 == 0xBF)))
}

func (p *parser) scanTag(tok *token) bool {
	var handle, suffix []byte
	start := p.mark
	if !p.cache(2) {
		return false
	}
	if p.at(p.pos+1) == '<' {
		handle = []byte{}
		p.skip()
		p.skip()
		if !p.scanTagURI(true, false, nil, start, &suffix) {
			return false
		}
		if p.ch() != '>' {
			p.setScannerError("while scanning a tag", start, "did not find the expected '>'")
			return false
		}
		p.skip()
	} else {
		if !p.scanTagHandle(false, start, &handle) {
			return false
		}
		if handle[0] == '!' && len(handle) > 1 && handle[len(handle)-1] == '!' {
			if !p.scanTagURI(false, false, nil, start, &suffix) {
				return false
			}
		} else {
			if !p.scanTagURI(false, false, handle, start, &suffix) {
				return false
			}
			handle = []byte{'!'}
			if len(suffix) == 0 {
				handle, suffix = suffix, handle
			}
		}
	}
	if !p.cache(1) {
		return false
	}
	if !p.isBlankZ(p.pos) {
		if p.flowLevel == 0 || p.ch() != ',' {
			p.setScannerError("while scanning a tag", start, "did not find expected whitespace or line break")
			return false
		}
	}
	end := p.mark
	*tok = token{typ: tTag, startMark: start, endMark: end, value: handle, suffix: suffix}
	return true
}

func (p *parser) scanTagHandle(directive bool, start mark, handle *[]byte) bool {
	if !p.cache(1) {
		return false
	}
	if p.ch() != '!' {
		p.setScannerTagError(directive, start, "did not find expected '!'")
		return false
	}
	var s []byte
	s = p.read(s)
	if !p.cache(1) {
		return false
	}
	for p.isAlpha(p.pos) {
		s = p.read(s)
		if !p.cache(1) {
			return false
		}
	}
	if p.ch() == '!' {
		s = p.read(s)
	} else {
		if directive && string(s) != "!" {
			p.setScannerTagError(directive, start, "did not find expected '!'")
			return false
		}
	}
	*handle = s
	return true
}

func (p *parser) scanTagURI(uriChar, directive bool, head []byte, start mark, uri *[]byte) bool {
	var s []byte
	hasTag := len(head) > 0
	if len(head) > 1 {
		s = append(s, head[1:]...)
	}
	if !p.cache(1) {
		return false
	}
	for {
		c := p.ch()
		if !(p.isAlpha(p.pos) || c == ';' || c == '/' || c == '?' || c == ':' || c == '@' || c == '&' || c == '=' ||
			c == '+' || c == '$' || c == '.' || c == '%' || c == '!' || c == '~' || c == '*' || c == '\'' ||
			c == '(' || c == ')' || (uriChar && (c == ',' || c == '[' || c == ']'))) {
			break
		}
		if c == '%' {
			if !p.scanURIEscapes(directive, start, &s) {
				return false
			}
		} else {
			s = p.read(s)
		}
		if !p.cache(1) {
			return false
		}
		hasTag = true
	}
	if !hasTag {
		p.setScannerTagError(directive, start, "did not find expected tag URI")
		return false
	}
	*uri = s
	return true
}

func (p *parser) scanURIEscapes(directive bool, start mark, s *[]byte) bool {
	w := 1024
	for w > 0 {
		if !p.cache(3) {
			return false
		}
		if !(p.ch() == '%' && p.isHex(p.pos+1) && p.isHex(p.pos+2)) {
			return p.setScannerTagError(directive, start, "did not find URI escaped octet")
		}
		octet := byte((p.asHex(p.pos+1) << 4) + p.asHex(p.pos+2))
		if w == 1024 {
			w = width(octet)
			if w == 0 {
				return p.setScannerTagError(directive, start, "found an incorrect leading UTF-8 octet")
			}
		} else {
			if octet&0xC0 != 0x80 {
				return p.setScannerTagError(directive, start, "found an incorrect trailing UTF-8 octet")
			}
		}
		*s = append(*s, octet)
		p.skip()
		p.skip()
		p.skip()
		w--
	}
	return true
}

func (p *parser) scanBlockScalar(tok *token, literal bool) bool {
	start := p.mark
	p.skip()
	if !p.cache(1) {
		return false
	}
	var chomping, increment int
	if p.ch() == '+' || p.ch() == '-' {
		if p.ch() == '+' {
			chomping = 1
		} else {
			chomping = -1
		}
		p.skip()
		if !p.cache(1) {
			return false
		}
		if p.isDigit(p.pos) {
			if p.ch() == '0' {
				p.setScannerError("while scanning a block scalar", start, "found an indentation indicator equal to 0")
				return false
			}
			increment = p.asDigit(p.pos)
			p.skip()
		}
	} else if p.isDigit(p.pos) {
		if p.ch() == '0' {
			p.setScannerError("while scanning a block scalar", start, "found an indentation indicator equal to 0")
			return false
		}
		increment = p.asDigit(p.pos)
		p.skip()
		if !p.cache(1) {
			return false
		}
		if p.ch() == '+' || p.ch() == '-' {
			if p.ch() == '+' {
				chomping = 1
			} else {
				chomping = -1
			}
			p.skip()
		}
	}
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if p.ch() == '#' {
		for !p.isBreakZ(p.pos) {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
	}
	if !p.isBreakZ(p.pos) {
		p.setScannerError("while scanning a block scalar", start, "did not find expected comment or line break")
		return false
	}
	if p.isBreak(p.pos) {
		if !p.cache(2) {
			return false
		}
		p.skipLine()
	}
	end := p.mark
	indent := 0
	if increment > 0 {
		if p.indent >= 0 {
			indent = p.indent + increment
		} else {
			indent = increment
		}
	}
	var s, leadingBreak, trailingBreaks []byte
	if !p.scanBlockScalarBreaks(&indent, &trailingBreaks, start, &end) {
		return false
	}
	if !p.cache(1) {
		return false
	}
	var leadingBlank, trailingBlank bool
	for p.mark.column == indent && !p.isZ(p.pos) {
		trailingBlank = p.isBlank(p.pos)
		if !literal && len(leadingBreak) > 0 && leadingBreak[0] == '\n' && !leadingBlank && !trailingBlank {
			if len(trailingBreaks) == 0 {
				s = append(s, ' ')
			}
		} else {
			s = append(s, leadingBreak...)
		}
		leadingBreak = leadingBreak[:0]
		s = append(s, trailingBreaks...)
		trailingBreaks = trailingBreaks[:0]
		leadingBlank = p.isBlank(p.pos)
		for !p.isBreakZ(p.pos) {
			s = p.read(s)
			if !p.cache(1) {
				return false
			}
		}
		if !p.cache(2) {
			return false
		}
		leadingBreak = p.readLine(leadingBreak)
		if !p.scanBlockScalarBreaks(&indent, &trailingBreaks, start, &end) {
			return false
		}
	}
	if chomping != -1 {
		s = append(s, leadingBreak...)
	}
	if chomping == 1 {
		s = append(s, trailingBreaks...)
	}
	style := literalScalarStyle
	if !literal {
		style = foldedScalarStyle
	}
	*tok = token{typ: tScalar, startMark: start, endMark: end, value: s, style: style}
	return true
}

func (p *parser) scanBlockScalarBreaks(indent *int, breaks *[]byte, start mark, end *mark) bool {
	*end = p.mark
	maxIndent := 0
	for {
		if !p.cache(1) {
			return false
		}
		for (*indent == 0 || p.mark.column < *indent) && p.isSpace(p.pos) {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
		if p.mark.column > maxIndent {
			maxIndent = p.mark.column
		}
		if (*indent == 0 || p.mark.column < *indent) && p.isTab(p.pos) {
			return p.setScannerError("while scanning a block scalar", start,
				"found a tab character where an indentation space is expected")
		}
		if !p.isBreak(p.pos) {
			break
		}
		if !p.cache(2) {
			return false
		}
		*breaks = p.readLine(*breaks)
		*end = p.mark
	}
	if *indent == 0 {
		*indent = maxIndent
		if *indent < p.indent+1 {
			*indent = p.indent + 1
		}
		if *indent < 1 {
			*indent = 1
		}
	}
	return true
}

func (p *parser) scanFlowScalar(tok *token, single bool) bool {
	start := p.mark
	p.skip()
	var s, leadingBreak, trailingBreaks, whitespaces []byte
	for {
		if !p.cache(4) {
			return false
		}
		if p.mark.column == 0 &&
			((p.at(p.pos) == '-' && p.at(p.pos+1) == '-' && p.at(p.pos+2) == '-') ||
				(p.at(p.pos) == '.' && p.at(p.pos+1) == '.' && p.at(p.pos+2) == '.')) &&
			p.isBlankZ(p.pos+3) {
			p.setScannerError("while scanning a quoted scalar", start, "found unexpected document indicator")
			return false
		}
		if p.isZ(p.pos) {
			p.setScannerError("while scanning a quoted scalar", start, "found unexpected end of stream")
			return false
		}
		leadingBlanks := false
		for !p.isBlankZ(p.pos) {
			if single && p.at(p.pos) == '\'' && p.at(p.pos+1) == '\'' {
				s = append(s, '\'')
				p.skip()
				p.skip()
			} else if single && p.ch() == '\'' {
				break
			} else if !single && p.ch() == '"' {
				break
			} else if !single && p.ch() == '\\' && p.isBreak(p.pos+1) {
				if !p.cache(3) {
					return false
				}
				p.skip()
				p.skipLine()
				leadingBlanks = true
				break
			} else if !single && p.ch() == '\\' {
				codeLength := 0
				switch p.at(p.pos + 1) {
				case '0':
					s = append(s, 0)
				case 'a':
					s = append(s, '\x07')
				case 'b':
					s = append(s, '\x08')
				case 't', '\t':
					s = append(s, '\x09')
				case 'n':
					s = append(s, '\x0A')
				case 'v':
					s = append(s, '\x0B')
				case 'f':
					s = append(s, '\x0C')
				case 'r':
					s = append(s, '\x0D')
				case 'e':
					s = append(s, '\x1B')
				case ' ':
					s = append(s, '\x20')
				case '"':
					s = append(s, '"')
				case '\'':
					s = append(s, '\'')
				case '\\':
					s = append(s, '\\')
				case 'N':
					s = append(s, '\xC2', '\x85')
				case '_':
					s = append(s, '\xC2', '\xA0')
				case 'L':
					s = append(s, '\xE2', '\x80', '\xA8')
				case 'P':
					s = append(s, '\xE2', '\x80', '\xA9')
				case 'x':
					codeLength = 2
				case 'u':
					codeLength = 4
				case 'U':
					codeLength = 8
				default:
					p.setScannerError("while parsing a quoted scalar", start, "found unknown escape character")
					return false
				}
				p.skip()
				p.skip()
				if codeLength > 0 {
					var value int
					if !p.cache(codeLength) {
						return false
					}
					for k := 0; k < codeLength; k++ {
						if !p.isHex(p.pos + k) {
							p.setScannerError("while parsing a quoted scalar", start, "did not find expected hexdecimal number")
							return false
						}
						value = (value << 4) + p.asHex(p.pos+k)
					}
					if (value >= 0xD800 && value <= 0xDFFF) || value > 0x10FFFF {
						p.setScannerError("while parsing a quoted scalar", start, "found invalid Unicode character escape code")
						return false
					}
					if value <= 0x7F {
						s = append(s, byte(value))
					} else if value <= 0x7FF {
						s = append(s, byte(0xC0+(value>>6)), byte(0x80+(value&0x3F)))
					} else if value <= 0xFFFF {
						s = append(s, byte(0xE0+(value>>12)), byte(0x80+((value>>6)&0x3F)), byte(0x80+(value&0x3F)))
					} else {
						s = append(s, byte(0xF0+(value>>18)), byte(0x80+((value>>12)&0x3F)), byte(0x80+((value>>6)&0x3F)), byte(0x80+(value&0x3F)))
					}
					for k := 0; k < codeLength; k++ {
						p.skip()
					}
				}
			} else {
				s = p.read(s)
			}
			if !p.cache(2) {
				return false
			}
		}
		if !p.cache(1) {
			return false
		}
		if single {
			if p.ch() == '\'' {
				break
			}
		} else {
			if p.ch() == '"' {
				break
			}
		}
		for p.isBlank(p.pos) || p.isBreak(p.pos) {
			if p.isBlank(p.pos) {
				if !leadingBlanks {
					whitespaces = p.read(whitespaces)
				} else {
					p.skip()
				}
			} else {
				if !p.cache(2) {
					return false
				}
				if !leadingBlanks {
					whitespaces = whitespaces[:0]
					leadingBreak = p.readLine(leadingBreak)
					leadingBlanks = true
				} else {
					trailingBreaks = p.readLine(trailingBreaks)
				}
			}
			if !p.cache(1) {
				return false
			}
		}
		if leadingBlanks {
			if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
				if len(trailingBreaks) == 0 {
					s = append(s, ' ')
				} else {
					s = append(s, trailingBreaks...)
				}
			} else {
				s = append(s, leadingBreak...)
				s = append(s, trailingBreaks...)
			}
			trailingBreaks = trailingBreaks[:0]
			leadingBreak = leadingBreak[:0]
		} else {
			s = append(s, whitespaces...)
			whitespaces = whitespaces[:0]
		}
	}
	p.skip()
	end := p.mark
	style := singleQuotedScalarStyle
	if !single {
		style = doubleQuotedScalarStyle
	}
	*tok = token{typ: tScalar, startMark: start, endMark: end, value: s, style: style}
	return true
}

func (p *parser) scanPlainScalar(tok *token) bool {
	var s, leadingBreak, trailingBreaks, whitespaces []byte
	var leadingBlanks bool
	indent := p.indent + 1
	start := p.mark
	end := p.mark
	for {
		if !p.cache(4) {
			return false
		}
		if p.mark.column == 0 &&
			((p.at(p.pos) == '-' && p.at(p.pos+1) == '-' && p.at(p.pos+2) == '-') ||
				(p.at(p.pos) == '.' && p.at(p.pos+1) == '.' && p.at(p.pos+2) == '.')) &&
			p.isBlankZ(p.pos+3) {
			break
		}
		if p.ch() == '#' {
			break
		}
		for !p.isBlankZ(p.pos) {
			if p.flowLevel > 0 && p.ch() == ':' && (p.at(p.pos+1) == ',' || p.at(p.pos+1) == '?' ||
				p.at(p.pos+1) == '[' || p.at(p.pos+1) == ']' || p.at(p.pos+1) == '{' || p.at(p.pos+1) == '}') {
				p.setScannerError("while scanning a plain scalar", start, "found unexpected ':'")
				return false
			}
			if (p.ch() == ':' && p.isBlankZ(p.pos+1)) ||
				(p.flowLevel > 0 && (p.ch() == ',' || p.ch() == '[' || p.ch() == ']' || p.ch() == '{' || p.ch() == '}')) {
				break
			}
			if leadingBlanks || len(whitespaces) > 0 {
				if leadingBlanks {
					if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
						if len(trailingBreaks) == 0 {
							s = append(s, ' ')
						} else {
							s = append(s, trailingBreaks...)
						}
					} else {
						s = append(s, leadingBreak...)
						s = append(s, trailingBreaks...)
					}
					trailingBreaks = trailingBreaks[:0]
					leadingBreak = leadingBreak[:0]
					leadingBlanks = false
				} else {
					s = append(s, whitespaces...)
					whitespaces = whitespaces[:0]
				}
			}
			s = p.read(s)
			end = p.mark
			if !p.cache(2) {
				return false
			}
		}
		if !(p.isBlank(p.pos) || p.isBreak(p.pos)) {
			break
		}
		if !p.cache(1) {
			return false
		}
		for p.isBlank(p.pos) || p.isBreak(p.pos) {
			if p.isBlank(p.pos) {
				if leadingBlanks && p.mark.column < indent && p.isTab(p.pos) {
					p.setScannerError("while scanning a plain scalar", start, "found a tab character that violates indentation")
					return false
				}
				if !leadingBlanks {
					whitespaces = p.read(whitespaces)
				} else {
					p.skip()
				}
			} else {
				if !p.cache(2) {
					return false
				}
				if !leadingBlanks {
					whitespaces = whitespaces[:0]
					leadingBreak = p.readLine(leadingBreak)
					leadingBlanks = true
				} else {
					trailingBreaks = p.readLine(trailingBreaks)
				}
			}
			if !p.cache(1) {
				return false
			}
		}
		if p.flowLevel == 0 && p.mark.column < indent {
			break
		}
	}
	*tok = token{typ: tScalar, startMark: start, endMark: end, value: s, style: plainScalarStyle}
	if leadingBlanks {
		p.simpleKeyAllowed = true
	}
	return true
}
