package yaml

import "bytes"

func (p *parser) skip() {
	if !p.isBlank(p.pos) {
		p.newlines = 0
	}
	p.mark.index++
	p.mark.column++
	p.unread--
	p.pos += width(p.buf[p.pos])
}

func (p *parser) skipLine() {
	if p.isCRLF(p.pos) {
		p.mark.index += 2
		p.mark.column = 0
		p.mark.line++
		p.unread -= 2
		p.pos += 2
		p.newlines++
	} else if p.isBreak(p.pos) {
		p.mark.index++
		p.mark.column = 0
		p.mark.line++
		p.unread--
		p.pos += width(p.buf[p.pos])
		p.newlines++
	}
}

func (p *parser) read(s []byte) []byte {
	if !p.isBlank(p.pos) {
		p.newlines = 0
	}
	w := width(p.buf[p.pos])
	if w == 0 {
		panic("invalid character sequence")
	}
	s = append(s, p.buf[p.pos:p.pos+w]...)
	p.pos += w
	p.mark.index++
	p.mark.column++
	p.unread--
	return s
}

func (p *parser) readLine(s []byte) []byte {
	b0, b1, b2 := p.at(p.pos), p.at(p.pos+1), p.at(p.pos+2)
	switch {
	case b0 == '\r' && b1 == '\n':
		s = append(s, '\n')
		p.pos += 2
		p.mark.index++
		p.unread--
	case b0 == '\r' || b0 == '\n':
		s = append(s, '\n')
		p.pos++
	case b0 == 0xC2 && b1 == 0x85:
		s = append(s, '\n')
		p.pos += 2
	case b0 == 0xE2 && b1 == 0x80 && (b2 == 0xA8 || b2 == 0xA9):
		s = append(s, p.buf[p.pos:p.pos+3]...)
		p.pos += 3
	default:
		return s
	}
	p.mark.index++
	p.mark.column = 0
	p.mark.line++
	p.unread--
	p.newlines++
	return s
}

// peekToken returns the next token without consuming it.
func (p *parser) peekToken() *token {
	if p.tokenAvailable || p.fetchMoreTokens() {
		return &p.tokens[p.tokensHead]
	}
	return nil
}

func (p *parser) skipToken() {
	p.tokenAvailable = false
	p.tokensParsed++
	p.streamEndProduced = p.tokens[p.tokensHead].typ == tStreamEnd
	p.tokensHead++
}

func (p *parser) setScannerError(context string, contextMark mark, problem string) bool {
	p.err = scannerError
	p.context = context
	p.contextMark = contextMark
	p.problem = problem
	p.problemMark = p.mark
	return false
}

func (p *parser) setScannerTagError(directive bool, contextMark mark, problem string) bool {
	context := "while parsing a tag"
	if directive {
		context = "while parsing a %TAG directive"
	}
	return p.setScannerError(context, contextMark, problem)
}

func (p *parser) insertToken(pos int, tok *token) {
	if p.tokensHead > 0 && len(p.tokens) == cap(p.tokens) {
		if p.tokensHead != len(p.tokens) {
			copy(p.tokens, p.tokens[p.tokensHead:])
		}
		p.tokens = p.tokens[:len(p.tokens)-p.tokensHead]
		p.tokensHead = 0
	}
	p.tokens = append(p.tokens, *tok)
	if pos < 0 {
		return
	}
	copy(p.tokens[p.tokensHead+pos+1:], p.tokens[p.tokensHead+pos:])
	p.tokens[p.tokensHead+pos] = *tok
}

func (p *parser) fetchMoreTokens() bool {
	for {
		if p.tokensHead < len(p.tokens)-2 {
			headTokIdx, ok := p.simpleKeysByTok[p.tokensParsed]
			if !ok {
				break
			} else if valid, ok := p.simpleKeyIsValid(&p.simpleKeys[headTokIdx]); !ok {
				return false
			} else if !valid {
				break
			}
		}
		if !p.fetchNextToken() {
			return false
		}
	}
	p.tokenAvailable = true
	return true
}

func (p *parser) fetchNextToken() (ok bool) {
	if !p.cache(1) {
		return false
	}
	if !p.streamStartProduced {
		return p.fetchStreamStart()
	}
	scanMark := p.mark
	if !p.scanToNextToken() {
		return false
	}
	if !p.unrollIndent(p.mark.column, scanMark) {
		return false
	}
	if !p.cache(4) {
		return false
	}
	if p.isZ(p.pos) {
		return p.fetchStreamEnd()
	}
	c := p.ch()
	if p.mark.column == 0 && c == '%' {
		return p.fetchDirective()
	}
	if p.mark.column == 0 && c == '-' && p.at(p.pos+1) == '-' && p.at(p.pos+2) == '-' && p.isBlankZ(p.pos+3) {
		return p.fetchDocumentIndicator(tDocumentStart)
	}
	if p.mark.column == 0 && c == '.' && p.at(p.pos+1) == '.' && p.at(p.pos+2) == '.' && p.isBlankZ(p.pos+3) {
		return p.fetchDocumentIndicator(tDocumentEnd)
	}

	defer func() {
		if !ok {
			return
		}
		if len(p.tokens) > 0 && p.tokens[len(p.tokens)-1].typ == tBlockEntry {
			return
		}
		if !p.scanLineComment() {
			ok = false
		}
	}()

	switch c {
	case '[':
		return p.fetchFlowCollectionStart(tFlowSequenceStart)
	case '{':
		return p.fetchFlowCollectionStart(tFlowMappingStart)
	case ']':
		return p.fetchFlowCollectionEnd(tFlowSequenceEnd)
	case '}':
		return p.fetchFlowCollectionEnd(tFlowMappingEnd)
	case ',':
		return p.fetchFlowEntry()
	}
	if c == '-' && p.isBlankZ(p.pos+1) {
		return p.fetchBlockEntry()
	}
	if c == '?' && (p.flowLevel > 0 || p.isBlankZ(p.pos+1)) {
		return p.fetchKey()
	}
	if c == ':' && (p.flowLevel > 0 || p.isBlankZ(p.pos+1)) {
		return p.fetchValue()
	}
	if c == '*' {
		return p.fetchAnchor(tAlias)
	}
	if c == '&' {
		return p.fetchAnchor(tAnchor)
	}
	if c == '!' {
		return p.fetchTag()
	}
	if c == '|' && p.flowLevel == 0 {
		return p.fetchBlockScalar(true)
	}
	if c == '>' && p.flowLevel == 0 {
		return p.fetchBlockScalar(false)
	}
	if c == '\'' {
		return p.fetchFlowScalar(true)
	}
	if c == '"' {
		return p.fetchFlowScalar(false)
	}
	if !(p.isBlankZ(p.pos) || c == '-' || c == '?' || c == ':' || c == ',' || c == '[' || c == ']' ||
		c == '{' || c == '}' || c == '#' || c == '&' || c == '*' || c == '!' || c == '|' || c == '>' ||
		c == '\'' || c == '"' || c == '%' || c == '@' || c == '`') ||
		(c == '-' && !p.isBlank(p.pos+1)) ||
		(p.flowLevel == 0 && (c == '?' || c == ':') && !p.isBlankZ(p.pos+1)) {
		return p.fetchPlainScalar()
	}
	return p.setScannerError("while scanning for the next token", p.mark,
		"found character that cannot start any token")
}

func (p *parser) simpleKeyIsValid(sk *simpleKey) (valid, ok bool) {
	if !sk.possible {
		return false, true
	}
	if sk.mark.line < p.mark.line || sk.mark.index+1024 < p.mark.index {
		if sk.required {
			return false, p.setScannerError("while scanning a simple key", sk.mark,
				"could not find expected ':'")
		}
		sk.possible = false
		return false, true
	}
	return true, true
}

func (p *parser) saveSimpleKey() bool {
	required := p.flowLevel == 0 && p.indent == p.mark.column
	if p.simpleKeyAllowed {
		sk := simpleKey{
			possible:    true,
			required:    required,
			tokenNumber: p.tokensParsed + (len(p.tokens) - p.tokensHead),
			mark:        p.mark,
		}
		if !p.removeSimpleKey() {
			return false
		}
		p.simpleKeys[len(p.simpleKeys)-1] = sk
		p.simpleKeysByTok[sk.tokenNumber] = len(p.simpleKeys) - 1
	}
	return true
}

func (p *parser) removeSimpleKey() bool {
	i := len(p.simpleKeys) - 1
	if p.simpleKeys[i].possible {
		if p.simpleKeys[i].required {
			return p.setScannerError("while scanning a simple key", p.simpleKeys[i].mark,
				"could not find expected ':'")
		}
		p.simpleKeys[i].possible = false
		delete(p.simpleKeysByTok, p.simpleKeys[i].tokenNumber)
	}
	return true
}

const maxFlowLevel = 10000

func (p *parser) increaseFlowLevel() bool {
	p.simpleKeys = append(p.simpleKeys, simpleKey{
		possible:    false,
		required:    false,
		tokenNumber: 0,
		mark:        p.mark,
	})
	p.flowLevel++
	if p.flowLevel > maxFlowLevel {
		return p.setScannerError("while increasing flow level", p.simpleKeys[len(p.simpleKeys)-1].mark,
			"exceeded max depth of 10000")
	}
	return true
}

func (p *parser) decreaseFlowLevel() bool {
	if p.flowLevel > 0 {
		p.flowLevel--
		last := len(p.simpleKeys) - 1
		delete(p.simpleKeysByTok, p.simpleKeys[last].tokenNumber)
		p.simpleKeys = p.simpleKeys[:last]
	}
	return true
}

const maxIndents = 10000

func (p *parser) rollIndent(column, number int, typ tokenType, m mark) bool {
	if p.flowLevel > 0 {
		return true
	}
	if p.indent < column {
		p.indents = append(p.indents, p.indent)
		p.indent = column
		if len(p.indents) > maxIndents {
			return p.setScannerError("while increasing indent level", p.simpleKeys[len(p.simpleKeys)-1].mark,
				"exceeded max depth of 10000")
		}
		tok := token{typ: typ, startMark: m, endMark: m}
		if number > -1 {
			number -= p.tokensParsed
		}
		p.insertToken(number, &tok)
	}
	return true
}

func (p *parser) unrollIndent(column int, scanMark mark) bool {
	if p.flowLevel > 0 {
		return true
	}
	for p.indent > column {
		tok := token{typ: tBlockEnd, startMark: p.mark, endMark: p.mark}
		p.insertToken(-1, &tok)
		p.indent = p.indents[len(p.indents)-1]
		p.indents = p.indents[:len(p.indents)-1]
	}
	return true
}

func (p *parser) fetchStreamStart() bool {
	p.indent = -1
	p.simpleKeys = append(p.simpleKeys, simpleKey{})
	p.simpleKeysByTok = map[int]int{}
	p.simpleKeyAllowed = true
	p.streamStartProduced = true
	tok := token{typ: tStreamStart, startMark: p.mark, endMark: p.mark}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchStreamEnd() bool {
	if p.mark.column != 0 {
		p.mark.column = 0
		p.mark.line++
	}
	if !p.unrollIndent(-1, p.mark) {
		return false
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	tok := token{typ: tStreamEnd, startMark: p.mark, endMark: p.mark}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchDirective() bool {
	if !p.unrollIndent(-1, p.mark) {
		return false
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	tok := token{}
	if !p.scanDirective(&tok) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchDocumentIndicator(typ tokenType) bool {
	if !p.unrollIndent(-1, p.mark) {
		return false
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	start := p.mark
	p.skip()
	p.skip()
	p.skip()
	end := p.mark
	tok := token{typ: typ, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowCollectionStart(typ tokenType) bool {
	if !p.saveSimpleKey() {
		return false
	}
	if !p.increaseFlowLevel() {
		return false
	}
	p.simpleKeyAllowed = true
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: typ, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowCollectionEnd(typ tokenType) bool {
	if !p.removeSimpleKey() {
		return false
	}
	if !p.decreaseFlowLevel() {
		return false
	}
	p.simpleKeyAllowed = false
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: typ, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchFlowEntry() bool {
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = true
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tFlowEntry, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchBlockEntry() bool {
	if p.flowLevel == 0 {
		if !p.simpleKeyAllowed {
			return p.setScannerError("", p.mark, "block sequence entries are not allowed in this context")
		}
		if !p.rollIndent(p.mark.column, -1, tBlockSequenceStart, p.mark) {
			return false
		}
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = true
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tBlockEntry, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchKey() bool {
	if p.flowLevel == 0 {
		if !p.simpleKeyAllowed {
			return p.setScannerError("", p.mark, "mapping keys are not allowed in this context")
		}
		if !p.rollIndent(p.mark.column, -1, tBlockMappingStart, p.mark) {
			return false
		}
	}
	if !p.removeSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = p.flowLevel == 0
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tKey, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchValue() bool {
	sk := &p.simpleKeys[len(p.simpleKeys)-1]
	if valid, ok := p.simpleKeyIsValid(sk); !ok {
		return false
	} else if valid {
		tok := token{typ: tKey, startMark: sk.mark, endMark: sk.mark}
		p.insertToken(sk.tokenNumber-p.tokensParsed, &tok)
		if !p.rollIndent(sk.mark.column, sk.tokenNumber, tBlockMappingStart, sk.mark) {
			return false
		}
		sk.possible = false
		delete(p.simpleKeysByTok, sk.tokenNumber)
		p.simpleKeyAllowed = false
	} else {
		if p.flowLevel == 0 {
			if !p.simpleKeyAllowed {
				return p.setScannerError("", p.mark, "mapping values are not allowed in this context")
			}
			if !p.rollIndent(p.mark.column, -1, tBlockMappingStart, p.mark) {
				return false
			}
		}
		p.simpleKeyAllowed = p.flowLevel == 0
	}
	start := p.mark
	p.skip()
	end := p.mark
	tok := token{typ: tValue, startMark: start, endMark: end}
	p.insertToken(-1, &tok)
	return true
}

func (p *parser) fetchAnchor(typ tokenType) bool {
	if !p.saveSimpleKey() {
		return false
	}
	p.simpleKeyAllowed = false
	var tok token
	if !p.scanAnchor(&tok, typ) {
		return false
	}
	p.insertToken(-1, &tok)
	return true
}

