func (p *parser) scanToNextToken() bool {
	scanMark := p.mark
	for {
		if !p.cache(1) {
			return false
		}
		if p.mark.column == 0 && p.isBOM(p.pos) {
			p.skip()
		}
		if !p.cache(1) {
			return false
		}
		for p.ch() == ' ' || ((p.flowLevel > 0 || !p.simpleKeyAllowed) && p.ch() == '\t') {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
		if p.ch() == '#' {
			if !p.scanComments(scanMark) {
				return false
			}
		}
		if p.isBreak(p.pos) {
			if !p.cache(2) {
				return false
			}
			p.skipLine()
			if p.flowLevel == 0 {
				p.simpleKeyAllowed = true
			}
		} else {
			break
		}
	}
	return true
}

// scanComments consumes a run of comment lines.
func (p *parser) scanComments(scanMark mark) bool {
	peek := 0
	for ; peek < 512; peek++ {
		if p.unread < peek+1 && !p.updateBuffer(peek+1) {
			break
		}
		if p.isBlank(p.pos + peek) {
			continue
		}
		c := p.at(p.pos + peek)
		closeFlow := p.flowLevel > 0 && (c == ']' || c == '}')
		if closeFlow || p.isBreakZ(p.pos+peek) {
			if !p.isBreak(p.pos + peek) {
				break
			}
			continue
		}
		if c != '#' {
			break
		}
		seen := p.mark.index + peek
		for {
			if !p.cache(1) {
				return false
			}
			if p.isBreakZ(p.pos) {
				if p.mark.index >= seen {
					break
				}
				if !p.cache(2) {
					return false
				}
				p.skipLine()
			} else if p.mark.index >= seen {
				p.read(nil)
			} else {
				p.skip()
			}
		}
		peek = 0
	}
	return true
}

func (p *parser) scanLineComment() bool {
	if p.newlines > 0 {
		return true
	}
	for peek := 0; peek < 512; peek++ {
		if p.unread < peek+1 && !p.updateBuffer(peek+1) {
			break
		}
		if p.isBlank(p.pos + peek) {
			continue
		}
		if p.at(p.pos+peek) == '#' {
			seen := p.mark.index + peek
			for {
				if !p.cache(1) {
					return false
				}
				if p.isBreakZ(p.pos) {
					if p.mark.index >= seen {
						break
					}
					if !p.cache(2) {
						return false
					}
					p.skipLine()
				} else if p.mark.index >= seen {
					p.read(nil)
				} else {
					p.skip()
				}
			}
		}
		break
	}
	return true
}

func (p *parser) scanDirective(tok *token) bool {
	start := p.mark
	p.skip()
	var name []byte
	if !p.scanDirectiveName(start, &name) {
		return false
	}
	if bytes.Equal(name, []byte("YAML")) {
		var major, minor int
		if !p.scanVersionDirectiveValue(start, &major, &minor) {
			return false
		}
		end := p.mark
		*tok = token{typ: tVersionDirective, startMark: start, endMark: end, major: major, minor: minor}
	} else if bytes.Equal(name, []byte("TAG")) {
		var handle, prefix []byte
		if !p.scanTagDirectiveValue(start, &handle, &prefix) {
			return false
		}
		end := p.mark
		*tok = token{typ: tTagDirective, startMark: start, endMark: end, value: handle, prefix: prefix}
	} else {
		p.setScannerError("while scanning a directive", start, "found unknown directive name")
		return false
	}
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if p.ch() == '#' {
		for !p.isBreakZ(p.pos) {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
	}
	if !p.isBreakZ(p.pos) {
		p.setScannerError("while scanning a directive", start, "did not find expected comment or line break")
		return false
	}
	if p.isBreak(p.pos) {
		if !p.cache(2) {
			return false
		}
		p.skipLine()
	}
	return true
}

func (p *parser) scanDirectiveName(start mark, name *[]byte) bool {
	if !p.cache(1) {
		return false
	}
	var s []byte
	for p.isAlpha(p.pos) {
		s = p.read(s)
		if !p.cache(1) {
			return false
		}
	}
	if len(s) == 0 {
		p.setScannerError("while scanning a directive", start, "could not find expected directive name")
		return false
	}
	if !p.isBlankZ(p.pos) {
		p.setScannerError("while scanning a directive", start, "found unexpected non-alphabetical character")
		return false
	}
	*name = s
	return true
}

func (p *parser) scanVersionDirectiveValue(start mark, major, minor *int) bool {
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if !p.scanVersionDirectiveNumber(start, major) {
		return false
	}
	if p.ch() != '.' {
		return p.setScannerError("while scanning a %YAML directive", start, "did not find expected digit or '.' character")
	}
	p.skip()
	if !p.scanVersionDirectiveNumber(start, minor) {
		return false
	}
	return true
}

func (p *parser) scanVersionDirectiveNumber(start mark, number *int) bool {
	if !p.cache(1) {
		return false
	}
	value := 0
	length := 0
	for p.isDigit(p.pos) {
		length++
		if length > 9 {
			return p.setScannerError("while scanning a %YAML directive", start, "found extremely long version number")
		}
		value = value*10 + p.asDigit(p.pos)
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if length == 0 {
		return p.setScannerError("while scanning a %YAML directive", start, "did not find expected version number")
	}
	*number = value
	return true
}

func (p *parser) scanTagDirectiveValue(start mark, handle, prefix *[]byte) bool {
	var h, pr []byte
	if !p.cache(1) {
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if !p.scanTagHandle(true, start, &h) {
		return false
	}
	if !p.cache(1) {
		return false
	}
	if !p.isBlank(p.pos) {
		p.setScannerError("while scanning a %TAG directive", start, "did not find expected whitespace")
		return false
	}
	for p.isBlank(p.pos) {
		p.skip()
		if !p.cache(1) {
			return false
		}
	}
	if !p.scanTagURI(true, true, nil, start, &pr) {
		return false
	}
	if !p.cache(1) {
		return false
	}
	if !p.isBlankZ(p.pos) {
		p.setScannerError("while scanning a %TAG directive", start, "did not find expected whitespace or line break")
		return false
	}
	*handle = h
	*prefix = pr
	return true
}

func (p *parser) scanAnchor(tok *token, typ tokenType) bool {
	var s []byte
	start := p.mark
	p.skip()
	if !p.cache(1) {
		return false
	}
	for p.isAnchorChar(p.pos) {
		s = p.read(s)
		if !p.cache(1) {
			return false
		}
	}
	end := p.mark
	if len(s) == 0 || !(p.isBlankZ(p.pos) || p.ch() == '?' || p.ch() == ':' || p.ch() == ',' || p.ch() == ']' ||
		p.ch() == '}' || p.ch() == '%' || p.ch() == '@' || p.ch() == '`') {
		context := "while scanning an alias"
		if typ == tAnchor {
			context = "while scanning an anchor"
		}
		p.setScannerError(context, start, "did not find expected alphabetic or numeric character")
		return false
	}
	*tok = token{typ: typ, startMark: start, endMark: end, value: s}
	return true
}

func (p *parser) isAnchorChar(i int) bool {
	c := p.at(i)
	if c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
		return false
	}
	if p.isBlankZ(i) {
		return false
	}
	return p.isPrintable(i) && !p.isBOM(i)
}

func (p *parser) isPrintable(i int) bool {
	b := p.at(i)
	b1 := p.at(i + 1)
	b2 := p.at(i + 2)
	return b == 0x0A || (b >= 0x20 && b <= 0x7E) ||
		(b == 0xC2 && b1 >= 0xA0) ||
		(b > 0xC2 && b < 0xED) ||
		(b == 0xED && b1 < 0xA0) ||
		(b == 0xEE) ||
		(b == 0xEF && !(b1 == 0xBB && b2 == 0xBF) && !(b1 == 0xBF && (b2 == 0xBE || b2 == 0xBF)))
}

func (p *parser) scanTag(tok *token) bool {
	var handle, suffix []byte
	start := p.mark
	if !p.cache(2) {
		return false
	}
	if p.at(p.pos+1) == '<' {
		handle = []byte{}
		p.skip()
		p.skip()
		if !p.scanTagURI(true, false, nil, start, &suffix) {
			return false
		}
		if p.ch() != '>' {
			p.setScannerError("while scanning a tag", start, "did not find the expected '>'")
			return false
		}
		p.skip()
	} else {
		if !p.scanTagHandle(false, start, &handle) {
			return false
		}
		if handle[0] == '!' && len(handle) > 1 && handle[len(handle)-1] == '!' {
			if !p.scanTagURI(false, false, nil, start, &suffix) {
				return false
			}
		} else {
			if !p.scanTagURI(false, false, handle, start, &suffix) {
				return false
			}
			handle = []byte{'!'}
			if len(suffix) == 0 {
				handle, suffix = suffix, handle
			}
		}
	}
	if !p.cache(1) {
		return false
	}
	if !p.isBlankZ(p.pos) {
		if p.flowLevel == 0 || p.ch() != ',' {
			p.setScannerError("while scanning a tag", start, "did not find expected whitespace or line break")
			return false
		}
	}
	end := p.mark
	*tok = token{typ: tTag, startMark: start, endMark: end, value: handle, suffix: suffix}
	return true
}

func (p *parser) scanTagHandle(directive bool, start mark, handle *[]byte) bool {
	if !p.cache(1) {
		return false
	}
	if p.ch() != '!' {
		p.setScannerTagError(directive, start, "did not find expected '!'")
		return false
	}
	var s []byte
	s = p.read(s)
	if !p.cache(1) {
		return false
	}
	for p.isAlpha(p.pos) {
		s = p.read(s)
		if !p.cache(1) {
			return false
		}
	}
	if p.ch() == '!' {
		s = p.read(s)
	} else {
		if directive && string(s) != "!" {
			p.setScannerTagError(directive, start, "did not find expected '!'")
			return false
		}
	}
	*handle = s
	return true
}

func (p *parser) scanTagURI(uriChar, directive bool, head []byte, start mark, uri *[]byte) bool {
	var s []byte
	hasTag := len(head) > 0
	if len(head) > 1 {
		s = append(s, head[1:]...)
	}
	if !p.cache(1) {
		return false
	}
	for {
		c := p.ch()
		if !(p.isAlpha(p.pos) || c == ';' || c == '/' || c == '?' || c == ':' || c == '@' || c == '&' || c == '=' ||
