			if !p.scanURIEscapes(directive, start, &s) {
				return false
			}
		} else {
			s = p.read(s)
		}
		if !p.cache(1) {
			return false
		}
		hasTag = true
	}
	if !hasTag {
		p.setScannerTagError(directive, start, "did not find expected tag URI")
		return false
	}
