	for {
		if !p.cache(1) {
			return false
		}
		for (*indent == 0 || p.mark.column < *indent) && p.isSpace(p.pos) {
			p.skip()
			if !p.cache(1) {
				return false
			}
		}
		if p.mark.column > maxIndent {
			maxIndent = p.mark.column
		}
		if (*indent == 0 || p.mark.column < *indent) && p.isTab(p.pos) {
			return p.setScannerError("while scanning a block scalar", start,
				"found a tab character where an indentation space is expected")
		}
		if !p.isBreak(p.pos) {
			break
		}
		if !p.cache(2) {
			return false
		}
		*breaks = p.readLine(*breaks)
		*end = p.mark
	}
	if *indent == 0 {
		*indent = maxIndent
		if *indent < p.indent+1 {
			*indent = p.indent + 1
		}
		if *indent < 1 {
			*indent = 1
		}
