package yaml

import "bytes"

type parserState int

const (
	psStreamStart parserState = iota
	psImplicitDocumentStart
	psDocumentStart
	psDocumentContent
	psDocumentEnd
	psBlockNode
	psBlockNodeOrIndentlessSequence
	psFlowNode
	psBlockSequenceFirstEntry
	psBlockSequenceEntry
	psIndentlessSequenceEntry
	psBlockMappingFirstKey
	psBlockMappingKey
	psBlockMappingValue
	psFlowSequenceFirstEntry
	psFlowSequenceEntry
	psFlowSequenceEntryMappingKey
	psFlowSequenceEntryMappingValue
	psFlowSequenceEntryMappingEnd
	psFlowMappingFirstKey
	psFlowMappingKey
	psFlowMappingValue
	psFlowMappingEmptyValue
	psEnd
)

var defaultTagDirectives = []tagDirective{
	{[]byte("!"), []byte("!")},
	{[]byte("!!"), []byte("tag:yaml.org,2002:")},
}

func (p *parser) parse(ev *event) bool {
	*ev = event{}
	if p.streamEndProduced || p.err != noError || p.state == psEnd {
		return true
	}
	return p.stateMachine(ev)
}

func (p *parser) setParserError(problem string, problemMark mark) bool {
	p.err = parserError
	p.problem = problem
	p.problemMark = problemMark
	return false
}

func (p *parser) setParserErrorContext(context string, contextMark mark, problem string, problemMark mark) bool {
	p.err = parserError
	p.context = context
	p.contextMark = contextMark
	p.problem = problem
	p.problemMark = problemMark
	return false
}

func (p *parser) popState() {
	p.state = p.states[len(p.states)-1]
	p.states = p.states[:len(p.states)-1]
}

func (p *parser) stateMachine(ev *event) bool {
	switch p.state {
	case psStreamStart:
		return p.parseStreamStart(ev)
	case psImplicitDocumentStart:
		return p.parseDocumentStart(ev, true)
	case psDocumentStart:
		return p.parseDocumentStart(ev, false)
	case psDocumentContent:
		return p.parseDocumentContent(ev)
	case psDocumentEnd:
		return p.parseDocumentEnd(ev)
	case psBlockNode:
		return p.parseNode(ev, true, false)
	case psBlockNodeOrIndentlessSequence:
		return p.parseNode(ev, true, true)
	case psFlowNode:
		return p.parseNode(ev, false, false)
	case psBlockSequenceFirstEntry:
		return p.parseBlockSequenceEntry(ev, true)
	case psBlockSequenceEntry:
		return p.parseBlockSequenceEntry(ev, false)
	case psIndentlessSequenceEntry:
		return p.parseIndentlessSequenceEntry(ev)
	case psBlockMappingFirstKey:
		return p.parseBlockMappingKey(ev, true)
	case psBlockMappingKey:
		return p.parseBlockMappingKey(ev, false)
	case psBlockMappingValue:
		return p.parseBlockMappingValue(ev)
	case psFlowSequenceFirstEntry:
		return p.parseFlowSequenceEntry(ev, true)
	case psFlowSequenceEntry:
		return p.parseFlowSequenceEntry(ev, false)
	case psFlowSequenceEntryMappingKey:
		return p.parseFlowSequenceEntryMappingKey(ev)
	case psFlowSequenceEntryMappingValue:
		return p.parseFlowSequenceEntryMappingValue(ev)
	case psFlowSequenceEntryMappingEnd:
		return p.parseFlowSequenceEntryMappingEnd(ev)
	case psFlowMappingFirstKey:
		return p.parseFlowMappingKey(ev, true)
	case psFlowMappingKey:
		return p.parseFlowMappingKey(ev, false)
	case psFlowMappingValue:
		return p.parseFlowMappingValue(ev, false)
	case psFlowMappingEmptyValue:
		return p.parseFlowMappingValue(ev, true)
	}
	panic("invalid parser state")
}

func (p *parser) parseStreamStart(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ != tStreamStart {
		return p.setParserError("did not find expected <stream-start>", tok.startMark)
	}
	p.state = psImplicitDocumentStart
	*ev = event{typ: eStreamStart, startMark: tok.startMark, endMark: tok.endMark}
	p.skipToken()
	return true
}

func (p *parser) parseDocumentStart(ev *event, implicit bool) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if !implicit {
		for tok.typ == tDocumentEnd {
			p.skipToken()
			tok = p.peekToken()
			if tok == nil {
				return false
			}
		}
	}
	if implicit && tok.typ != tVersionDirective && tok.typ != tTagDirective &&
		tok.typ != tDocumentStart && tok.typ != tStreamEnd {
		if !p.processDirectives(nil, nil) {
			return false
		}
		p.states = append(p.states, psDocumentEnd)
		p.state = psBlockNode
		*ev = event{typ: eDocumentStart, startMark: tok.startMark, endMark: tok.endMark, implicit: true}
	} else if tok.typ != tStreamEnd {
		var vd *[2]int
		var tds []tagDirective
		start := tok.startMark
		if !p.processDirectives(&vd, &tds) {
			return false
		}
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ != tDocumentStart {
			p.setParserError("did not find expected <document start>", tok.startMark)
			return false
		}
		p.states = append(p.states, psDocumentEnd)
		p.state = psDocumentContent
		end := tok.endMark
		*ev = event{typ: eDocumentStart, startMark: start, endMark: end, versionDirective: vd, tagDirectives: tds, implicit: false}
		p.skipToken()
	} else {
		p.state = psEnd
		*ev = event{typ: eStreamEnd, startMark: tok.startMark, endMark: tok.endMark}
		p.skipToken()
	}
	return true
}

func (p *parser) parseDocumentContent(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tVersionDirective || tok.typ == tTagDirective || tok.typ == tDocumentStart ||
		tok.typ == tDocumentEnd || tok.typ == tStreamEnd {
		p.popState()
		return p.processEmptyScalar(ev, tok.startMark)
	}
	return p.parseNode(ev, true, false)
}

func (p *parser) parseDocumentEnd(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	start := tok.startMark
	end := tok.startMark
	implicit := true
	if tok.typ == tDocumentEnd {
		end = tok.endMark
		p.skipToken()
		implicit = false
	}
	p.tagDirectives = p.tagDirectives[:0]
	p.state = psDocumentStart
	*ev = event{typ: eDocumentEnd, startMark: start, endMark: end, implicit: implicit}
	return true
}

func (p *parser) parseNode(ev *event, block, indentlessSequence bool) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tAlias {
		p.popState()
		*ev = event{typ: eAlias, startMark: tok.startMark, endMark: tok.endMark, anchor: tok.value}
		p.skipToken()
		return true
	}
	start := tok.startMark
	end := tok.startMark
	var tagToken bool
	var tagHandle, tagSuffix, anchor []byte
	var tagMark mark
	if tok.typ == tAnchor {
		anchor = tok.value
		start = tok.startMark
		end = tok.endMark
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ == tTag {
			tagToken = true
			tagHandle = tok.value
			tagSuffix = tok.suffix
			tagMark = tok.startMark
			end = tok.endMark
			p.skipToken()
			tok = p.peekToken()
			if tok == nil {
				return false
			}
		}
	} else if tok.typ == tTag {
		tagToken = true
		tagHandle = tok.value
		tagSuffix = tok.suffix
		start = tok.startMark
		tagMark = tok.startMark
		end = tok.endMark
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ == tAnchor {
			anchor = tok.value
			end = tok.endMark
			p.skipToken()
			tok = p.peekToken()
			if tok == nil {
				return false
			}
		}
	}
	var tag []byte
	if tagToken {
		if len(tagHandle) == 0 {
			tag = tagSuffix
		} else {
			for i := range p.tagDirectives {
				if bytes.Equal(p.tagDirectives[i].handle, tagHandle) {
					tag = append([]byte(nil), p.tagDirectives[i].prefix...)
					tag = append(tag, tagSuffix...)
					break
				}
			}
			if len(tag) == 0 {
				p.setParserErrorContext("while parsing a node", start, "found undefined tag handle", tagMark)
				return false
			}
		}
	}
	implicit := len(tag) == 0
	if indentlessSequence && tok.typ == tBlockEntry {
		end = tok.endMark
		p.state = psIndentlessSequenceEntry
		*ev = event{typ: eSequenceStart, startMark: start, endMark: end, anchor: anchor, tag: tag, implicit: implicit, style: int(blockStyle)}
		return true
	}
	if tok.typ == tScalar {
		var plainImplicit, quotedImplicit bool
		end = tok.endMark
		if (len(tag) == 0 && tok.style == plainScalarStyle) || (len(tag) == 1 && tag[0] == '!') {
			plainImplicit = true
		} else if len(tag) == 0 {
			quotedImplicit = true
		}
		p.popState()
		*ev = event{typ: eScalar, startMark: start, endMark: end, anchor: anchor, tag: tag, value: tok.value,
			implicit: plainImplicit, quotedImplicit: quotedImplicit, style: int(tok.style)}
		p.skipToken()
		return true
	}
	if tok.typ == tFlowSequenceStart {
		end = tok.endMark
		p.state = psFlowSequenceFirstEntry
		*ev = event{typ: eSequenceStart, startMark: start, endMark: end, anchor: anchor, tag: tag, implicit: implicit, style: int(flowStyle)}
		return true
	}
	if tok.typ == tFlowMappingStart {
		end = tok.endMark
		p.state = psFlowMappingFirstKey
		*ev = event{typ: eMappingStart, startMark: start, endMark: end, anchor: anchor, tag: tag, implicit: implicit, style: int(flowStyle)}
		return true
	}
	if block && tok.typ == tBlockSequenceStart {
		end = tok.endMark
		p.state = psBlockSequenceFirstEntry
		*ev = event{typ: eSequenceStart, startMark: start, endMark: end, anchor: anchor, tag: tag, implicit: implicit, style: int(blockStyle)}
		return true
	}
	if block && tok.typ == tBlockMappingStart {
		end = tok.endMark
		p.state = psBlockMappingFirstKey
		*ev = event{typ: eMappingStart, startMark: start, endMark: end, anchor: anchor, tag: tag, implicit: implicit, style: int(blockStyle)}
		return true
	}
	if len(anchor) > 0 || len(tag) > 0 {
		p.popState()
		*ev = event{typ: eScalar, startMark: start, endMark: end, anchor: anchor, tag: tag, implicit: implicit, style: int(plainScalarStyle)}
		return true
	}
	context := "while parsing a flow node"
	if block {
		context = "while parsing a block node"
	}
	p.setParserErrorContext(context, start, "did not find expected node content", tok.startMark)
	return false
}

func (p *parser) parseBlockSequenceEntry(ev *event, first bool) bool {
	if first {
		tok := p.peekToken()
		if tok == nil {
			return false
		}
		p.marks = append(p.marks, tok.startMark)
		p.skipToken()
	}
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tBlockEntry {
		m := tok.endMark
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ != tBlockEntry && tok.typ != tBlockEnd {
			p.states = append(p.states, psBlockSequenceEntry)
			return p.parseNode(ev, true, false)
		}
		p.state = psBlockSequenceEntry
		return p.processEmptyScalar(ev, m)
	}
	if tok.typ == tBlockEnd {
		p.popState()
		p.marks = p.marks[:len(p.marks)-1]
		*ev = event{typ: eSequenceEnd, startMark: tok.startMark, endMark: tok.endMark}
		p.skipToken()
		return true
	}
	cm := p.marks[len(p.marks)-1]
	p.marks = p.marks[:len(p.marks)-1]
	return p.setParserErrorContext("while parsing a block collection", cm, "did not find expected '-' indicator", tok.startMark)
}

func (p *parser) parseIndentlessSequenceEntry(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tBlockEntry {
		m := tok.endMark
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ != tBlockEntry && tok.typ != tKey && tok.typ != tValue && tok.typ != tBlockEnd {
			p.states = append(p.states, psIndentlessSequenceEntry)
			return p.parseNode(ev, true, false)
		}
		p.state = psIndentlessSequenceEntry
		return p.processEmptyScalar(ev, m)
	}
	p.popState()
	*ev = event{typ: eSequenceEnd, startMark: tok.startMark, endMark: tok.startMark}
	return true
}

func (p *parser) parseBlockMappingKey(ev *event, first bool) bool {
	if first {
		tok := p.peekToken()
		if tok == nil {
			return false
		}
		p.marks = append(p.marks, tok.startMark)
		p.skipToken()
	}
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tKey {
		m := tok.endMark
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ != tKey && tok.typ != tValue && tok.typ != tBlockEnd {
			p.states = append(p.states, psBlockMappingValue)
			return p.parseNode(ev, true, true)
		}
		p.state = psBlockMappingValue
		return p.processEmptyScalar(ev, m)
	} else if tok.typ == tBlockEnd {
		p.popState()
		p.marks = p.marks[:len(p.marks)-1]
		*ev = event{typ: eMappingEnd, startMark: tok.startMark, endMark: tok.endMark}
		p.skipToken()
		return true
	}
	cm := p.marks[len(p.marks)-1]
	p.marks = p.marks[:len(p.marks)-1]
	return p.setParserErrorContext("while parsing a block mapping", cm, "did not find expected key", tok.startMark)
}

func (p *parser) parseBlockMappingValue(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tValue {
		m := tok.endMark
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ != tKey && tok.typ != tValue && tok.typ != tBlockEnd {
			p.states = append(p.states, psBlockMappingKey)
			return p.parseNode(ev, true, true)
		}
		p.state = psBlockMappingKey
		return p.processEmptyScalar(ev, m)
	}
	p.state = psBlockMappingKey
	return p.processEmptyScalar(ev, tok.startMark)
}

func (p *parser) parseFlowSequenceEntry(ev *event, first bool) bool {
	if first {
		tok := p.peekToken()
		if tok == nil {
			return false
		}
		p.marks = append(p.marks, tok.startMark)
		p.skipToken()
	}
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ != tFlowSequenceEnd {
		if !first {
			if tok.typ == tFlowEntry {
				p.skipToken()
				tok = p.peekToken()
				if tok == nil {
					return false
				}
			} else {
				cm := p.marks[len(p.marks)-1]
				p.marks = p.marks[:len(p.marks)-1]
				return p.setParserErrorContext("while parsing a flow sequence", cm, "did not find expected ',' or ']'", tok.startMark)
			}
		}
		if tok.typ == tKey {
			p.state = psFlowSequenceEntryMappingKey
			*ev = event{typ: eMappingStart, startMark: tok.startMark, endMark: tok.endMark, implicit: true, style: int(flowStyle)}
			p.skipToken()
			return true
		} else if tok.typ != tFlowSequenceEnd {
			p.states = append(p.states, psFlowSequenceEntry)
			return p.parseNode(ev, false, false)
		}
	}
	p.popState()
	p.marks = p.marks[:len(p.marks)-1]
	*ev = event{typ: eSequenceEnd, startMark: tok.startMark, endMark: tok.endMark}
	p.skipToken()
	return true
}

func (p *parser) parseFlowSequenceEntryMappingKey(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ != tValue && tok.typ != tFlowEntry && tok.typ != tFlowSequenceEnd {
		p.states = append(p.states, psFlowSequenceEntryMappingValue)
		return p.parseNode(ev, false, false)
	}
	m := tok.endMark
	p.skipToken()
	p.state = psFlowSequenceEntryMappingValue
	return p.processEmptyScalar(ev, m)
}

func (p *parser) parseFlowSequenceEntryMappingValue(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ == tValue {
		p.skipToken()
		tok2 := p.peekToken()
		if tok2 == nil {
			return false
		}
		if tok2.typ != tFlowEntry && tok2.typ != tFlowSequenceEnd {
			p.states = append(p.states, psFlowSequenceEntryMappingEnd)
			return p.parseNode(ev, false, false)
		}
		tok = tok2
	}
	p.state = psFlowSequenceEntryMappingEnd
	return p.processEmptyScalar(ev, tok.startMark)
}

func (p *parser) parseFlowSequenceEntryMappingEnd(ev *event) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	p.state = psFlowSequenceEntry
	*ev = event{typ: eMappingEnd, startMark: tok.startMark, endMark: tok.startMark}
	return true
}

func (p *parser) parseFlowMappingKey(ev *event, first bool) bool {
	if first {
		tok := p.peekToken()
		if tok == nil {
			return false
		}
		p.marks = append(p.marks, tok.startMark)
		p.skipToken()
	}
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if tok.typ != tFlowMappingEnd {
		if !first {
			if tok.typ == tFlowEntry {
				p.skipToken()
				tok = p.peekToken()
				if tok == nil {
					return false
				}
			} else {
				cm := p.marks[len(p.marks)-1]
				p.marks = p.marks[:len(p.marks)-1]
				return p.setParserErrorContext("while parsing a flow mapping", cm, "did not find expected ',' or '}'", tok.startMark)
			}
		}
		if tok.typ == tKey {
			p.skipToken()
			tok = p.peekToken()
			if tok == nil {
				return false
			}
			if tok.typ != tValue && tok.typ != tFlowEntry && tok.typ != tFlowMappingEnd {
				p.states = append(p.states, psFlowMappingValue)
				return p.parseNode(ev, false, false)
			}
			p.state = psFlowMappingValue
			return p.processEmptyScalar(ev, tok.startMark)
		} else if tok.typ != tFlowMappingEnd {
			p.states = append(p.states, psFlowMappingEmptyValue)
			return p.parseNode(ev, false, false)
		}
	}
	p.popState()
	p.marks = p.marks[:len(p.marks)-1]
	*ev = event{typ: eMappingEnd, startMark: tok.startMark, endMark: tok.endMark}
	p.skipToken()
	return true
}

func (p *parser) parseFlowMappingValue(ev *event, empty bool) bool {
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	if empty {
		p.state = psFlowMappingKey
		return p.processEmptyScalar(ev, tok.startMark)
	}
	if tok.typ == tValue {
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
		if tok.typ != tFlowEntry && tok.typ != tFlowMappingEnd {
			p.states = append(p.states, psFlowMappingKey)
			return p.parseNode(ev, false, false)
		}
	}
	p.state = psFlowMappingKey
	return p.processEmptyScalar(ev, tok.startMark)
}

func (p *parser) processEmptyScalar(ev *event, m mark) bool {
	*ev = event{typ: eScalar, startMark: m, endMark: m, implicit: true, style: int(plainScalarStyle)}
	return true
}

func (p *parser) processDirectives(vdRef **[2]int, tdRef *[]tagDirective) bool {
	var vd *[2]int
	var tds []tagDirective
	tok := p.peekToken()
	if tok == nil {
		return false
	}
	for tok.typ == tVersionDirective || tok.typ == tTagDirective {
		if tok.typ == tVersionDirective {
			if vd != nil {
				p.setParserError("found duplicate %YAML directive", tok.startMark)
				return false
			}
			if tok.major != 1 || tok.minor != 1 {
				p.setParserError("found incompatible YAML document", tok.startMark)
				return false
			}
			vd = &[2]int{tok.major, tok.minor}
		} else {
			v := tagDirective{handle: tok.value, prefix: tok.prefix}
			if !p.appendTagDirective(v, false, tok.startMark) {
				return false
			}
			tds = append(tds, v)
		}
		p.skipToken()
		tok = p.peekToken()
		if tok == nil {
			return false
		}
	}
	for i := range defaultTagDirectives {
		if !p.appendTagDirective(defaultTagDirectives[i], true, tok.startMark) {
			return false
		}
	}
	if vdRef != nil {
		*vdRef = vd
	}
	if tdRef != nil {
		*tdRef = tds
	}
	return true
}

func (p *parser) appendTagDirective(v tagDirective, allowDuplicates bool, m mark) bool {
	for i := range p.tagDirectives {
		if bytes.Equal(v.handle, p.tagDirectives[i].handle) {
			if allowDuplicates {
				return true
			}
			return p.setParserError("found duplicate %TAG directive", m)
		}
	}
	p.tagDirectives = append(p.tagDirectives, tagDirective{
		handle: append([]byte(nil), v.handle...),
		prefix: append([]byte(nil), v.prefix...),
	})
	return true
}
