package yaml

import (
	"errors"
	"fmt"
	"strconv"
)

// Kind identifies the kind of a node.
type Kind uint32

const (
	DocumentNode Kind = 1 << iota
	SequenceNode
	MappingNode
	ScalarNode
	AliasNode
)

// Style holds node presentation flags.
type Style uint32

const (
	TaggedStyle Style = 1 << iota
	DoubleQuotedStyle
	SingleQuotedStyle
	LiteralStyle
	FoldedStyle
	FlowStyle
)

// Node is a YAML representation node.
type Node struct {
	Kind    Kind
	Style   Style
	Tag     string
	Value   string
	Anchor  string
	Alias   *Node
	Content []*Node
}

// ShortTag returns the short form of the node tag.
func (n *Node) ShortTag() string {
	if n.indicatedString() {
		return strTag
	}
	if n.Tag == "" || n.Tag == "!" {
		switch n.Kind {
		case MappingNode:
			return mapTag
		case SequenceNode:
			return seqTag
		case AliasNode:
			if n.Alias != nil {
				return n.Alias.ShortTag()
			}
		case ScalarNode:
			tag, _ := resolve("", n.Value)
			return tag
		case 0:
			if n.isZero() {
				return nullTag
			}
		}
		return ""
	}
	return shortTag(n.Tag)
}

func (n *Node) isZero() bool {
	return n.Kind == 0 && n.Style == 0 && n.Tag == "" && n.Value == "" && n.Anchor == "" && n.Alias == nil && n.Content == nil
}

func (n *Node) indicatedString() bool {
	return n.Kind == ScalarNode &&
		(shortTag(n.Tag) == strTag ||
			(n.Tag == "" || n.Tag == "!") && n.Style&(SingleQuotedStyle|DoubleQuotedStyle|LiteralStyle|FoldedStyle) != 0)
}

type yamlError struct{ err error }

func failf(format string, args ...interface{}) {
	panic(yamlError{fmt.Errorf("yaml: "+format, args...)})
}

func handleErr(err *error) {
	if v := recover(); v != nil {
		if e, ok := v.(yamlError); ok {
			*err = e.err
			return
		}
		panic(v)
	}
}

// composer builds nodes from parser events.
type composer struct {
	p        *parser
	ev       event
	anchors  map[string]*Node
	doneInit bool
}

func (c *composer) fail() {
	var where string
	var line int
	p := c.p
	if p.contextMark.line != 0 {
		line = p.contextMark.line
		if p.err == scannerError {
			line++
		}
	} else if p.problemMark.line != 0 {
		line = p.problemMark.line
		if p.err == scannerError {
			line++
		}
	}
	if line != 0 {
		where = "line " + strconv.Itoa(line) + ": "
	}
	msg := p.problem
	if msg == "" {
		msg = "unknown problem parsing YAML content"
	}
	failf("%s%s", where, msg)
}

var eventNames = map[eventType]string{
	eNone:          "none",
	eStreamStart:   "stream start",
	eStreamEnd:     "stream end",
	eDocumentStart: "document start",
	eDocumentEnd:   "document end",
	eAlias:         "alias",
	eScalar:        "scalar",
	eSequenceStart: "sequence start",
	eSequenceEnd:   "sequence end",
	eMappingStart:  "mapping start",
	eMappingEnd:    "mapping end",
}

func (c *composer) expect(e eventType) {
	if c.ev.typ == eNone {
		if !c.p.parse(&c.ev) {
			c.fail()
		}
	}
	if c.ev.typ == eStreamEnd {
		failf("attempted to go past the end of stream; corrupted value?")
	}
	if c.ev.typ != e {
		c.p.problem = fmt.Sprintf("expected %s event but got %s", eventNames[e], eventNames[c.ev.typ])
		c.fail()
	}
	c.ev = event{}
}

func (c *composer) peek() eventType {
	if c.ev.typ != eNone {
		return c.ev.typ
	}
	if !c.p.parse(&c.ev) || c.p.err != noError {
		c.fail()
	}
	return c.ev.typ
}

func (c *composer) init() {
	if c.doneInit {
		return
	}
	c.anchors = map[string]*Node{}
	c.expect(eStreamStart)
	c.doneInit = true
}

func (c *composer) parse() *Node {
	c.init()
	switch c.peek() {
	case eScalar:
		return c.scalar()
	case eAlias:
		return c.alias()
	case eMappingStart:
		return c.mapping()
	case eSequenceStart:
		return c.sequence()
	case eDocumentStart:
		return c.document()
	case eStreamEnd:
		return nil
	}
	panic("internal error: attempted to parse unknown event")
}

func (c *composer) node(kind Kind, defaultTag, tag, value string) *Node {
	var style Style
	if tag != "" && tag != "!" {
		tag = shortTag(tag)
		style = TaggedStyle
	} else if defaultTag != "" {
		tag = defaultTag
	} else if kind == ScalarNode {
		tag, _ = resolve("", value)
	}
	return &Node{Kind: kind, Tag: tag, Value: value, Style: style}
}

func (c *composer) parseChild(parent *Node) *Node {
	child := c.parse()
	parent.Content = append(parent.Content, child)
	return child
}

func (c *composer) document() *Node {
	n := c.node(DocumentNode, "", "", "")
	c.expect(eDocumentStart)
	c.parseChild(n)
	c.expect(eDocumentEnd)
	return n
}

func (c *composer) alias() *Node {
	n := c.node(AliasNode, "", "", string(c.ev.anchor))
	n.Alias = c.anchors[n.Value]
	if n.Alias == nil {
		failf("unknown anchor '%s' referenced", n.Value)
	}
	c.expect(eAlias)
	return n
}

func (c *composer) anchor(n *Node, anchor []byte) {
	if anchor != nil {
		n.Anchor = string(anchor)
		c.anchors[n.Anchor] = n
	}
}

func (c *composer) scalar() *Node {
	var nodeStyle Style
	switch c.ev.scalarStyle() {
	case doubleQuotedScalarStyle:
		nodeStyle = DoubleQuotedStyle
	case singleQuotedScalarStyle:
		nodeStyle = SingleQuotedStyle
	case literalScalarStyle:
		nodeStyle = LiteralStyle
	case foldedScalarStyle:
		nodeStyle = FoldedStyle
	}
	value := string(c.ev.value)
	tag := string(c.ev.tag)
	var defaultTag string
	if nodeStyle == 0 {
		if value == "<<" {
			defaultTag = mergeTag
		}
	} else {
		defaultTag = strTag
	}
	n := c.node(ScalarNode, defaultTag, tag, value)
	n.Style |= nodeStyle
	c.anchor(n, c.ev.anchor)
	c.expect(eScalar)
	return n
}

func (c *composer) sequence() *Node {
	n := c.node(SequenceNode, seqTag, string(c.ev.tag), "")
	if c.ev.collectionStyle() == flowStyle {
		n.Style |= FlowStyle
	}
	c.anchor(n, c.ev.anchor)
	c.expect(eSequenceStart)
	for c.peek() != eSequenceEnd {
		c.parseChild(n)
	}
	c.expect(eSequenceEnd)
	return n
}

func (c *composer) mapping() *Node {
	n := c.node(MappingNode, mapTag, string(c.ev.tag), "")
	if c.ev.collectionStyle() == flowStyle {
		n.Style |= FlowStyle
	}
	c.anchor(n, c.ev.anchor)
	c.expect(eMappingStart)
	for c.peek() != eMappingEnd {
		c.parseChild(n)
		c.parseChild(n)
	}
	c.expect(eMappingEnd)
	return n
}

// ErrEOF is returned by DecodeFirst when the stream holds no documents.
var ErrEOF = errors.New("EOF")

// ParseFirst parses the first document of the input and returns its
// document node. ErrEOF is returned when there are no documents.
func ParseFirst(input []byte) (n *Node, err error) {
	defer handleErr(&err)
	c := &composer{p: newParser(input)}
	n = c.parse()
	if n == nil {
		return nil, ErrEOF
	}
	return n, nil
}

// parseText parses a single document, used for the Node.Encode round trip.
func parseText(input []byte) (n *Node, err error) {
	defer handleErr(&err)
	c := &composer{p: newParser(input)}
	n = c.parse()
	return n, nil
}
EOF
