		"n", "N", "no", "No", "NO", "off", "Off", "OFF":
		return true
	}
	return false
}

// ScalarValue decodes a scalar node into a Go value the way the decoder does
// when the target is an interface, except timestamps which become time.Time.
func ScalarValue(n *Node) (v interface{}, err error) {
	defer handleErr(&err)
	var tag string
	var resolved interface{}
	if n.indicatedString() {
		tag = strTag
		resolved = n.Value
	} else {
		tag, resolved = resolve(n.Tag, n.Value)
		if tag == binaryTag {
			data, err := base64.StdEncoding.DecodeString(resolved.(string))
			if err != nil {
				failf("!!binary value contains invalid base64 data")
			}
			resolved = string(data)
		}
	}
	return resolved, nil
}
