cd /workspace && cat > yaml/emitter.go <<'EOF'
package yaml

import (
	"bytes"
	"errors"
)

type emitterState int

const (
	esStreamStart emitterState = iota
	esFirstDocumentStart
	esDocumentStart
	esDocumentContent
	esDocumentEnd
	esFlowSequenceFirstItem
	esFlowSequenceItem
	esFlowMappingFirstKey
	esFlowMappingKey
	esFlowMappingSimpleValue
	esFlowMappingValue
	esBlockSequenceFirstItem
	esBlockSequenceItem
	esBlockMappingFirstKey
	esBlockMappingKey
	esBlockMappingSimpleValue
	esBlockMappingValue
	esEnd
)

type emitter struct {
	out bytes.Buffer
	err error

	bestIndent int
	bestWidth  int
	unicode    bool

	state  emitterState
	states []emitterState

	events     []event
	eventsHead int

	indents []int
	indent  int

	tagDirectives []tagDirective

	flowLevel int

	rootContext, sequenceContext, mappingContext, simpleKeyContext bool

	line, column int
	whitespace   bool
	indention    bool
	openEnded    bool
	spaceAbove   bool

	anchorAlias bool
	anchor      []byte
	tagHandle   []byte
	tagSuffix   []byte

	scalarValue            []byte
	scalarMultiline        bool
	scalarFlowPlainAllowed bool
	scalarBlockPlain       bool
	scalarSingleAllowed    bool
	scalarBlockAllowed     bool
	scalarStyle            scalarStyle
}

func newEmitter(indent int) *emitter {
	return &emitter{bestIndent: indent, bestWidth: -1, unicode: true}
}

func (em *emitter) setError(problem string) bool {
	em.err = errors.New(problem)
	return false
}

func (em *emitter) put(b byte) bool {
	em.out.WriteByte(b)
	em.column++
	return true
}

func (em *emitter) putBreak() bool {
	em.out.WriteByte('\n')
	em.column = 0
	em.line++
	em.indention = true
	return true
}

func (em *emitter) write(s []byte, i *int) bool {
	w := width(s[*i])
	if w == 0 {
		w = 1
	}
	em.out.Write(s[*i : *i+w])
	*i += w
	em.column++
	return true
}

func (em *emitter) writeAll(s []byte) bool {
	for i := 0; i < len(s); {
		em.write(s, &i)
	}
	return true
}

func (em *emitter) writeBreak(s []byte, i *int) bool {
	if s[*i] == '\n' {
		em.putBreak()
		*i++
	} else {
		em.write(s, i)
		if em.column == 0 {
			em.spaceAbove = true
		}
		em.column = 0
		em.line++
		em.indention = true
	}
	return true
}

// emit queues an event and processes the queue.
func (em *emitter) emit(ev *event) bool {
	em.events = append(em.events, *ev)
	for !em.needMoreEvents() {
		ev := &em.events[em.eventsHead]
		if !em.analyzeEvent(ev) {
			return false
		}
		if !em.stateMachine(ev) {
			return false
		}
		em.eventsHead++
	}
	return true
}

func (em *emitter) needMoreEvents() bool {
	if em.eventsHead == len(em.events) {
		return true
	}
	var accumulate int
	switch em.events[em.eventsHead].typ {
	case eDocumentStart:
		accumulate = 1
	case eSequenceStart:
		accumulate = 2
	case eMappingStart:
		accumulate = 3
	default:
		return false
	}
	if len(em.events)-em.eventsHead > accumulate {
		return false
	}
	level := 0
	for i := em.eventsHead; i < len(em.events); i++ {
		switch em.events[i].typ {
		case eStreamStart, eDocumentStart, eSequenceStart, eMappingStart:
			level++
		case eStreamEnd, eDocumentEnd, eSequenceEnd, eMappingEnd:
			level--
		}
		if level == 0 {
			return false
		}
	}
	return true
}

func (em *emitter) appendTagDirective(handle, prefix []byte, allowDuplicates bool) bool {
	for i := range em.tagDirectives {
		if bytes.Equal(handle, em.tagDirectives[i].handle) {
			if allowDuplicates {
				return true
			}
			return em.setError("duplicate %TAG directive")
		}
	}
	em.tagDirectives = append(em.tagDirectives, tagDirective{
		handle: append([]byte(nil), handle...),
		prefix: append([]byte(nil), prefix...),
	})
	return true
}

func (em *emitter) increaseIndent(flow, indentless bool) bool {
	em.indents = append(em.indents, em.indent)
	if em.indent < 0 {
		if flow {
			em.indent = em.bestIndent
		} else {
			em.indent = 0
		}
	} else if !indentless {
		if em.states[len(em.states)-1] == esBlockSequenceItem {
			em.indent += 2
		} else {
			em.indent = em.bestIndent * ((em.indent + em.bestIndent) / em.bestIndent)
		}
	}
	return true
}

func (em *emitter) popIndent() {
	em.indent = em.indents[len(em.indents)-1]
	em.indents = em.indents[:len(em.indents)-1]
}

func (em *emitter) popState() {
	em.state = em.states[len(em.states)-1]
	em.states = em.states[:len(em.states)-1]
}

func (em *emitter) stateMachine(ev *event) bool {
	switch em.state {
	case esStreamStart:
		return em.emitStreamStart(ev)
	case esFirstDocumentStart:
		return em.emitDocumentStart(ev, true)
	case esDocumentStart:
		return em.emitDocumentStart(ev, false)
	case esDocumentContent:
		return em.emitDocumentContent(ev)
	case esDocumentEnd:
		return em.emitDocumentEnd(ev)
	case esFlowSequenceFirstItem:
		return em.emitFlowSequenceItem(ev, true)
	case esFlowSequenceItem:
		return em.emitFlowSequenceItem(ev, false)
	case esFlowMappingFirstKey:
		return em.emitFlowMappingKey(ev, true)
	case esFlowMappingKey:
		return em.emitFlowMappingKey(ev, false)
	case esFlowMappingSimpleValue:
		return em.emitFlowMappingValue(ev, true)
	case esFlowMappingValue:
		return em.emitFlowMappingValue(ev, false)
	case esBlockSequenceFirstItem:
		return em.emitBlockSequenceItem(ev, true)
	case esBlockSequenceItem:
		return em.emitBlockSequenceItem(ev, false)
	case esBlockMappingFirstKey:
		return em.emitBlockMappingKey(ev, true)
	case esBlockMappingKey:
		return em.emitBlockMappingKey(ev, false)
	case esBlockMappingSimpleValue:
		return em.emitBlockMappingValue(ev, true)
	case esBlockMappingValue:
		return em.emitBlockMappingValue(ev, false)
	case esEnd:
		return em.setError("expected nothing after STREAM-END")
	}
	panic("invalid emitter state")
}

func (em *emitter) emitStreamStart(ev *event) bool {
	if ev.typ != eStreamStart {
		return em.setError("expected STREAM-START")
	}
	if em.bestIndent < 2 || em.bestIndent > 9 {
		em.bestIndent = 2
	}
	if em.bestWidth >= 0 && em.bestWidth <= em.bestIndent*2 {
		em.bestWidth = 80
	}
	if em.bestWidth < 0 {
		em.bestWidth = 1<<31 - 1
	}
	em.indent = -1
	em.line = 0
	em.column = 0
	em.whitespace = true
	em.indention = true
	em.spaceAbove = true
	em.state = esFirstDocumentStart
	return true
}

func (em *emitter) emitDocumentStart(ev *event, first bool) bool {
	if ev.typ == eDocumentStart {
		for i := range defaultTagDirectives {
			if !em.appendTagDirective(defaultTagDirectives[i].handle, defaultTagDirectives[i].prefix, true) {
				return false
			}
		}
		implicit := ev.implicit
		if !first {
			implicit = false
		}
		if !implicit {
			if !em.writeIndent() {
				return false
			}
			if !em.writeIndicator([]byte("---"), true, false, false) {
				return false
			}
			if !em.writeIndent() {
				return false
			}
		}
		em.state = esDocumentContent
		return true
	}
	if ev.typ == eStreamEnd {
		if em.openEnded {
			if !em.writeIndicator([]byte("..."), true, false, false) {
				return false
			}
			if !em.writeIndent() {
				return false
			}
		}
		em.state = esEnd
		return true
	}
	return em.setError("expected DOCUMENT-START or STREAM-END")
}

func (em *emitter) emitDocumentContent(ev *event) bool {
	em.states = append(em.states, esDocumentEnd)
	return em.emitNode(ev, true, false, false, false)
}

func (em *emitter) emitDocumentEnd(ev *event) bool {
	if ev.typ != eDocumentEnd {
		return em.setError("expected DOCUMENT-END")
	}
	if !em.writeIndent() {
		return false
	}
	if !ev.implicit {
		if !em.writeIndicator([]byte("..."), true, false, false) {
			return false
		}
		if !em.writeIndent() {
			return false
		}
	}
	em.state = esDocumentStart
	em.tagDirectives = em.tagDirectives[:0]
	return true
}

func (em *emitter) emitFlowSequenceItem(ev *event, first bool) bool {
	if first {
		if !em.writeIndicator([]byte{'['}, true, true, false) {
			return false
		}
		if !em.increaseIndent(true, false) {
			return false
		}
		em.flowLevel++
	}
	if ev.typ == eSequenceEnd {
		em.flowLevel--
		em.popIndent()
		if em.column == 0 {
			if !em.writeIndent() {
				return false
			}
		}
		if !em.writeIndicator([]byte{']'}, false, false, false) {
			return false
		}
		em.popState()
		return true
	}
	if !first {
		if !em.writeIndicator([]byte{','}, false, false, false) {
			return false
		}
	}
	if em.column == 0 {
		if !em.writeIndent() {
			return false
		}
	}
	if em.column > em.bestWidth {
		if !em.writeIndent() {
			return false
		}
	}
	em.states = append(em.states, esFlowSequenceItem)
	return em.emitNode(ev, false, true, false, false)
}

func (em *emitter) emitFlowMappingKey(ev *event, first bool) bool {
	if first {
		if !em.writeIndicator([]byte{'{'}, true, true, false) {
			return false
		}
		if !em.increaseIndent(true, false) {
			return false
		}
		em.flowLevel++
	}
	if ev.typ == eMappingEnd {
		em.flowLevel--
		em.popIndent()
		if em.column == 0 {
			if !em.writeIndent() {
				return false
			}
		}
		if !em.writeIndicator([]byte{'}'}, false, false, false) {
			return false
		}
		em.popState()
		return true
	}
	if !first {
		if !em.writeIndicator([]byte{','}, false, false, false) {
			return false
		}
	}
	if em.column == 0 {
		if !em.writeIndent() {
			return false
		}
	}
	if em.column > em.bestWidth {
		if !em.writeIndent() {
			return false
		}
	}
	if em.checkSimpleKey() {
		em.states = append(em.states, esFlowMappingSimpleValue)
		return em.emitNode(ev, false, false, true, true)
	}
	if !em.writeIndicator([]byte{'?'}, true, false, false) {
		return false
	}
	em.states = append(em.states, esFlowMappingValue)
	return em.emitNode(ev, false, false, true, false)
}

func (em *emitter) emitFlowMappingValue(ev *event, simple bool) bool {
	if simple {
		if !em.writeIndicator([]byte{':'}, false, false, false) {
			return false
		}
	} else {
		if em.column > em.bestWidth {
			if !em.writeIndent() {
				return false
			}
		}
		if !em.writeIndicator([]byte{':'}, true, false, false) {
			return false
		}
	}
	em.states = append(em.states, esFlowMappingKey)
	return em.emitNode(ev, false, false, true, false)
}

func (em *emitter) emitBlockSequenceItem(ev *event, first bool) bool {
	if first {
		if !em.increaseIndent(false, false) {
			return false
		}
	}
	if ev.typ == eSequenceEnd {
		em.popIndent()
		em.popState()
		return true
	}
	if !em.writeIndent() {
		return false
	}
	if !em.writeIndicator([]byte{'-'}, true, false, true) {
		return false
	}
	em.states = append(em.states, esBlockSequenceItem)
	return em.emitNode(ev, false, true, false, false)
}

func (em *emitter) emitBlockMappingKey(ev *event, first bool) bool {
	if first {
		if !em.increaseIndent(false, false) {
			return false
		}
	}
	if ev.typ == eMappingEnd {
		em.popIndent()
		em.popState()
		return true
	}
	if !em.writeIndent() {
		return false
	}
	if em.checkSimpleKey() {
		em.states = append(em.states, esBlockMappingSimpleValue)
		return em.emitNode(ev, false, false, true, true)
	}
	if !em.writeIndicator([]byte{'?'}, true, false, true) {
		return false
	}
	em.states = append(em.states, esBlockMappingValue)
	return em.emitNode(ev, false, false, true, false)
}

func (em *emitter) emitBlockMappingValue(ev *event, simple bool) bool {
	if simple {
		if !em.writeIndicator([]byte{':'}, false, false, false) {
			return false
		}
	} else {
		if !em.writeIndent() {
			return false
		}
		if !em.writeIndicator([]byte{':'}, true, false, true) {
			return false
		}
	}
	em.states = append(em.states, esBlockMappingKey)
	return em.emitNode(ev, false, false, true, false)
}

func (em *emitter) emitNode(ev *event, root, sequence, mapping, simpleKey bool) bool {
	em.rootContext = root
	em.sequenceContext = sequence
	em.mappingContext = mapping
	em.simpleKeyContext = simpleKey
	switch ev.typ {
	case eAlias:
		return em.emitAlias(ev)
	case eScalar:
		return em.emitScalar(ev)
	case eSequenceStart:
		return em.emitSequenceStart(ev)
	case eMappingStart:
		return em.emitMappingStart(ev)
	}
	return em.setError("expected SCALAR, SEQUENCE-START, MAPPING-START, or ALIAS")
}

func (em *emitter) emitAlias(ev *event) bool {
	if !em.processAnchor() {
		return false
	}
	if em.simpleKeyContext {
		if !em.put(' ') {
			return false
		}
	}
	em.popState()
	return true
}

func (em *emitter) emitScalar(ev *event) bool {
	if !em.selectScalarStyle(ev) {
		return false
	}
	if !em.processAnchor() {
		return false
	}
	if !em.processTag() {
		return false
	}
	if !em.increaseIndent(true, false) {
		return false
	}
	if !em.processScalar() {
		return false
	}
	em.popIndent()
	em.popState()
	return true
}

func (em *emitter) emitSequenceStart(ev *event) bool {
	if !em.processAnchor() {
		return false
	}
	if !em.processTag() {
		return false
	}
	if em.flowLevel > 0 || ev.collectionStyle() == flowStyle || em.checkEmptySequence() {
		em.state = esFlowSequenceFirstItem
	} else {
		em.state = esBlockSequenceFirstItem
	}
	return true
}

func (em *emitter) emitMappingStart(ev *event) bool {
	if !em.processAnchor() {
		return false
	}
	if !em.processTag() {
		return false
	}
	if em.flowLevel > 0 || ev.collectionStyle() == flowStyle || em.checkEmptyMapping() {
		em.state = esFlowMappingFirstKey
	} else {
		em.state = esBlockMappingFirstKey
	}
	return true
}

func (em *emitter) checkEmptySequence() bool {
	if len(em.events)-em.eventsHead < 2 {
		return false
	}
	return em.events[em.eventsHead].typ == eSequenceStart && em.events[em.eventsHead+1].typ == eSequenceEnd
}

func (em *emitter) checkEmptyMapping() bool {
	if len(em.events)-em.eventsHead < 2 {
		return false
	}
	return em.events[em.eventsHead].typ == eMappingStart && em.events[em.eventsHead+1].typ == eMappingEnd
}

func (em *emitter) checkSimpleKey() bool {
	ev := &em.events[em.eventsHead]
	length := 0
	switch ev.typ {
	case eAlias:
		length += len(em.anchor)
	case eScalar:
		if em.scalarMultiline {
			return false
		}
		length += len(em.anchor) + len(em.tagHandle) + len(em.tagSuffix) + len(em.scalarValue)
	case eSequenceStart:
		if !em.checkEmptySequence() {
			return false
		}
		length += len(em.anchor) + len(em.tagHandle) + len(em.tagSuffix)
	case eMappingStart:
		if !em.checkEmptyMapping() {
			return false
		}
		length += len(em.anchor) + len(em.tagHandle) + len(em.tagSuffix)
	default:
		return false
	}
	return length <= 128
}

func (em *emitter) selectScalarStyle(ev *event) bool {
	noTag := len(em.tagHandle) == 0 && len(em.tagSuffix) == 0
	if noTag && !ev.implicit && !ev.quotedImplicit {
		return em.setError("neither tag nor implicit flags are specified")
	}
	style := ev.scalarStyle()
	if style == anyScalarStyle {
		style = plainScalarStyle
	}
	if em.simpleKeyContext && em.scalarMultiline {
		style = doubleQuotedScalarStyle
	}
	if style == plainScalarStyle {
		if em.flowLevel > 0 && !em.scalarFlowPlainAllowed || em.flowLevel == 0 && !em.scalarBlockPlain {
			style = singleQuotedScalarStyle
		}
		if len(em.scalarValue) == 0 && (em.flowLevel > 0 || em.simpleKeyContext) {
			style = singleQuotedScalarStyle
		}
		if noTag && !ev.implicit {
			style = singleQuotedScalarStyle
		}
	}
	if style == singleQuotedScalarStyle {
		if !em.scalarSingleAllowed {
			style = doubleQuotedScalarStyle
		}
	}
	if style == literalScalarStyle || style == foldedScalarStyle {
		if !em.scalarBlockAllowed || em.flowLevel > 0 || em.simpleKeyContext {
			style = doubleQuotedScalarStyle
		}
	}
	if noTag && !ev.quotedImplicit && style != plainScalarStyle {
		em.tagHandle = []byte{'!'}
	}
	em.scalarStyle = style
	return true
}

func (em *emitter) processAnchor() bool {
	if em.anchor == nil {
		return true
	}
	c := []byte{'&'}
	if em.anchorAlias {
		c[0] = '*'
	}
	if !em.writeIndicator(c, true, false, false) {
		return false
	}
	return em.writeAnchor(em.anchor)
}

func (em *emitter) processTag() bool {
	if len(em.tagHandle) == 0 && len(em.tagSuffix) == 0 {
		return true
	}
	if len(em.tagHandle) > 0 {
		if !em.writeTagHandle(em.tagHandle) {
			return false
		}
		if len(em.tagSuffix) > 0 {
			if !em.writeTagContent(em.tagSuffix, false) {
				return false
			}
		}
	} else {
		if !em.writeIndicator([]byte("!<"), true, false, false) {
			return false
		}
		if !em.writeTagContent(em.tagSuffix, false) {
			return false
		}
		if !em.writeIndicator([]byte{'>'}, false, false, false) {
			return false
		}
	}
	return true
}

func (em *emitter) processScalar() bool {
	switch em.scalarStyle {
	case plainScalarStyle:
		return em.writePlainScalar(em.scalarValue, !em.simpleKeyContext)
	case singleQuotedScalarStyle:
		return em.writeSingleQuotedScalar(em.scalarValue, !em.simpleKeyContext)
	case doubleQuotedScalarStyle:
		return em.writeDoubleQuotedScalar(em.scalarValue, !em.simpleKeyContext)
	case literalScalarStyle:
		return em.writeLiteralScalar(em.scalarValue)
	case foldedScalarStyle:
		return em.writeFoldedScalar(em.scalarValue)
	}
	panic("unknown scalar style")
}

func (em *emitter) analyzeAnchor(anchor []byte, alias bool) bool {
	if len(anchor) == 0 {
		problem := "anchor value must not be empty"
		if alias {
			problem = "alias value must not be empty"
		}
		return em.setError(problem)
	}
	em.anchorAlias = alias
	em.anchor = anchor
	return true
}

func (em *emitter) analyzeTag(tag []byte) bool {
	if len(tag) == 0 {
		return em.setError("tag value must not be empty")
	}
	for i := range em.tagDirectives {
		td := &em.tagDirectives[i]
		if bytes.HasPrefix(tag, td.prefix) {
			em.tagHandle = td.handle
			em.tagSuffix = tag[len(td.prefix):]
			return true
		}
	}
	em.tagSuffix = tag
	return true
}

func isSpaceAt(b []byte, i int) bool { return i < len(b) && b[i] == ' ' }
func isTabAt(b []byte, i int) bool   { return i < len(b) && b[i] == '\t' }
func isBlankAt(b []byte, i int) bool { return isSpaceAt(b, i) || isTabAt(b, i) }
func byteAt(b []byte, i int) byte {
	if i < len(b) {
		return b[i]
	}
	return 0
}
func isBreakAt(b []byte, i int) bool {
	c := byteAt(b, i)
	return c == '\r' || c == '\n' ||
		c == 0xC2 && byteAt(b, i+1) == 0x85 ||
		c == 0xE2 && byteAt(b, i+1) == 0x80 && byteAt(b, i+2) == 0xA8 ||
		c == 0xE2 && byteAt(b, i+1) == 0x80 && byteAt(b, i+2) == 0xA9
}
func isBlankZAt(b []byte, i int) bool {
	return isBlankAt(b, i) || isBreakAt(b, i) || byteAt(b, i) == 0
}
func isPrintableAt(b []byte, i int) bool {
	c := byteAt(b, i)
	c1 := byteAt(b, i+1)
	c2 := byteAt(b, i+2)
	return c == 0x0A || (c >= 0x20 && c <= 0x7E) ||
		(c == 0xC2 && c1 >= 0xA0) ||
		(c > 0xC2 && c < 0xED) ||
		(c == 0xED && c1 < 0xA0) ||
		(c == 0xEE) ||
		(c == 0xEF && !(c1 == 0xBB && c2 == 0xBF) && !(c1 == 0xBF && (c2 == 0xBE || c2 == 0xBF)))
}
func isBOMAt(b []byte, i int) bool {
	return byteAt(b, i) == 0xEF && byteAt(b, i+1) == 0xBB && byteAt(b, i+2) == 0xBF
}
func isAlphaAt(b []byte, i int) bool {
	c := byteAt(b, i)
	return c >= '0' && c <= '9' || c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c == '_' || c == '-'
}

func (em *emitter) analyzeScalar(value []byte) bool {
	var blockIndicators, flowIndicators, lineBreaks, specialCharacters, tabCharacters bool
	var leadingSpace, leadingBreak, trailingSpace, trailingBreak, breakSpace, spaceBreak bool
	var precededByWhitespace, followedByWhitespace, previousSpace, previousBreak bool

	em.scalarValue = value
	if len(value) == 0 {
		em.scalarMultiline = false
		em.scalarFlowPlainAllowed = false
		em.scalarBlockPlain = true
		em.scalarSingleAllowed = true
		em.scalarBlockAllowed = false
		return true
	}
	if len(value) >= 3 && ((value[0] == '-' && value[1] == '-' && value[2] == '-') || (value[0] == '.' && value[1] == '.' && value[2] == '.')) {
		blockIndicators = true
		flowIndicators = true
	}
	precededByWhitespace = true
	for i, w := 0, 0; i < len(value); i += w {
		w = width(value[i])
		if w == 0 {
			w = 1
		}
		followedByWhitespace = i+w >= len(value) || isBlankAt(value, i+w)
		if i == 0 {
			switch value[i] {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				flowIndicators = true
				blockIndicators = true
			case '?', ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '-':
				if followedByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		} else {
			switch value[i] {
			case ',', '?', '[', ']', '{', '}':
				flowIndicators = true
			case ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '#':
				if precededByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		}
		if value[i] == '\t' {
			tabCharacters = true
		} else if !isPrintableAt(value, i) || value[i] >= 0x80 && !em.unicode {
			specialCharacters = true
		}
		if isSpaceAt(value, i) {
			if i == 0 {
				leadingSpace = true
			}
			if i+w == len(value) {
				trailingSpace = true
			}
			if previousBreak {
				breakSpace = true
			}
			previousSpace = true
			previousBreak = false
		} else if isBreakAt(value, i) {
			lineBreaks = true
			if i == 0 {
				leadingBreak = true
			}
			if i+w == len(value) {
				trailingBreak = true
			}
			if previousSpace {
				spaceBreak = true
			}
			previousSpace = false
			previousBreak = true
		} else {
			previousSpace = false
			previousBreak = false
		}
		precededByWhitespace = isBlankZAt(value, i)
	}
	em.scalarMultiline = lineBreaks
	em.scalarFlowPlainAllowed = true
	em.scalarBlockPlain = true
	em.scalarSingleAllowed = true
	em.scalarBlockAllowed = true
	if leadingSpace || leadingBreak || trailingSpace || trailingBreak {
		em.scalarFlowPlainAllowed = false
		em.scalarBlockPlain = false
	}
	if trailingSpace {
		em.scalarBlockAllowed = false
	}
	if breakSpace {
		em.scalarFlowPlainAllowed = false
		em.scalarBlockPlain = false
		em.scalarSingleAllowed = false
	}
	if spaceBreak || tabCharacters || specialCharacters {
		em.scalarFlowPlainAllowed = false
		em.scalarBlockPlain = false
		em.scalarSingleAllowed = false
	}
	if spaceBreak || specialCharacters {
		em.scalarBlockAllowed = false
	}
	if lineBreaks {
		em.scalarFlowPlainAllowed = false
		em.scalarBlockPlain = false
	}
	if flowIndicators {
		em.scalarFlowPlainAllowed = false
	}
	if blockIndicators {
		em.scalarBlockPlain = false
	}
	return true
}

func (em *emitter) analyzeEvent(ev *event) bool {
	em.anchor = nil
	em.tagHandle = nil
	em.tagSuffix = nil
	em.scalarValue = nil
	switch ev.typ {
	case eAlias:
		if !em.analyzeAnchor(ev.anchor, true) {
			return false
		}
	case eScalar:
		if len(ev.anchor) > 0 {
			if !em.analyzeAnchor(ev.anchor, false) {
				return false
			}
		}
		if len(ev.tag) > 0 && !ev.implicit && !ev.quotedImplicit {
			if !em.analyzeTag(ev.tag) {
				return false
			}
		}
		if !em.analyzeScalar(ev.value) {
			return false
		}
	case eSequenceStart, eMappingStart:
		if len(ev.anchor) > 0 {
			if !em.analyzeAnchor(ev.anchor, false) {
				return false
			}
		}
		if len(ev.tag) > 0 && !ev.implicit {
			if !em.analyzeTag(ev.tag) {
				return false
			}
		}
	}
	return true
}

func (em *emitter) writeIndent() bool {
	indent := em.indent
	if indent < 0 {
		indent = 0
	}
	if !em.indention || em.column > indent || (em.column == indent && !em.whitespace) {
		if !em.putBreak() {
			return false
		}
	}
	for em.column < indent {
		if !em.put(' ') {
			return false
		}
	}
	em.whitespace = true
	em.spaceAbove = false
	return true
}

func (em *emitter) writeIndicator(indicator []byte, needWhitespace, isWhitespace, isIndention bool) bool {
	if needWhitespace && !em.whitespace {
		if !em.put(' ') {
			return false
		}
	}
	if !em.writeAll(indicator) {
		return false
	}
	em.whitespace = isWhitespace
	em.indention = em.indention && isIndention
	em.openEnded = false
	return true
}

func (em *emitter) writeAnchor(value []byte) bool {
	if !em.writeAll(value) {
		return false
	}
	em.whitespace = false
	em.indention = false
	return true
}

func (em *emitter) writeTagHandle(value []byte) bool {
	if !em.whitespace {
		if !em.put(' ') {
			return false
		}
	}
	if !em.writeAll(value) {
		return false
	}
	em.whitespace = false
	em.indention = false
	return true
}

func (em *emitter) writeTagContent(value []byte, needWhitespace bool) bool {
	if needWhitespace && !em.whitespace {
		if !em.put(' ') {
			return false
		}
	}
	for i := 0; i < len(value); {
		var mustWrite bool
		switch value[i] {
		case ';', '/', '?', ':', '@', '&', '=', '+', '$', ',', '_', '.', '~', '*', '\'', '(', ')', '[', ']':
			mustWrite = true
		default:
			mustWrite = isAlphaAt(value, i)
		}
		if mustWrite {
			if !em.write(value, &i) {
				return false
			}
		} else {
			w := width(value[i])
			if w == 0 {
				w = 1
			}
			for k := 0; k < w; k++ {
				octet := value[i]
				i++
				if !em.put('%') {
					return false
				}
				c := octet >> 4
				if c < 10 {
					c += '0'
				} else {
					c += 'A' - 10
				}
				if !em.put(c) {
					return false
				}
				c = octet & 0x0f
				if c < 10 {
					c += '0'
				} else {
					c += 'A' - 10
				}
				if !em.put(c) {
					return false
				}
			}
		}
	}
	em.whitespace = false
	em.indention = false
	return true
}

func (em *emitter) writePlainScalar(value []byte, allowBreaks bool) bool {
	if len(value) > 0 && !em.whitespace {
		if !em.put(' ') {
			return false
		}
	}
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if isSpaceAt(value, i) {
			if allowBreaks && !spaces && em.column > em.bestWidth && !isSpaceAt(value, i+1) {
				if !em.writeIndent() {
					return false
				}
				i += width(value[i])
			} else {
				if !em.write(value, &i) {
					return false
				}
			}
			spaces = true
		} else if isBreakAt(value, i) {
			if !breaks && value[i] == '\n' {
				if !em.putBreak() {
					return false
				}
			}
			if !em.writeBreak(value, &i) {
				return false
			}
			breaks = true
		} else {
			if breaks {
				if !em.writeIndent() {
					return false
				}
			}
			if !em.write(value, &i) {
				return false
			}
			em.indention = false
			spaces = false
			breaks = false
		}
	}
	if len(value) > 0 {
		em.whitespace = false
	}
	em.indention = false
	if em.rootContext {
		em.openEnded = true
	}
	return true
}

func (em *emitter) writeSingleQuotedScalar(value []byte, allowBreaks bool) bool {
	if !em.writeIndicator([]byte{'\''}, true, false, false) {
		return false
	}
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if isSpaceAt(value, i) {
			if allowBreaks && !spaces && em.column > em.bestWidth && i > 0 && i < len(value)-1 && !isSpaceAt(value, i+1) {
				if !em.writeIndent() {
					return false
				}
				i += width(value[i])
			} else {
				if !em.write(value, &i) {
					return false
				}
			}
			spaces = true
		} else if isBreakAt(value, i) {
			if !breaks && value[i] == '\n' {
				if !em.putBreak() {
					return false
				}
			}
			if !em.writeBreak(value, &i) {
				return false
			}
			breaks = true
		} else {
			if breaks {
				if !em.writeIndent() {
					return false
				}
			}
			if value[i] == '\'' {
				if !em.put('\'') {
					return false
				}
			}
			if !em.write(value, &i) {
				return false
			}
			em.indention = false
			spaces = false
			breaks = false
		}
	}
	if !em.writeIndicator([]byte{'\''}, false, false, false) {
		return false
	}
	em.whitespace = false
	em.indention = false
	return true
}

func (em *emitter) writeDoubleQuotedScalar(value []byte, allowBreaks bool) bool {
	spaces := false
	if !em.writeIndicator([]byte{'"'}, true, false, false) {
		return false
	}
	for i := 0; i < len(value); {
		if !isPrintableAt(value, i) || (!em.unicode && value[i] >= 0x80) ||
			isBOMAt(value, i) || isBreakAt(value, i) ||
			value[i] == '"' || value[i] == '\\' {
			octet := value[i]
			var w int
			var v rune
			switch {
			case octet&0x80 == 0x00:
				w, v = 1, rune(octet&0x7F)
			case octet&0xE0 == 0xC0:
				w, v = 2, rune(octet&0x1F)
			case octet&0xF0 == 0xE0:
				w, v = 3, rune(octet&0x0F)
			case octet&0xF8 == 0xF0:
				w, v = 4, rune(octet&0x07)
			default:
				w, v = 1, rune(octet)
			}
			for k := 1; k < w; k++ {
				octet = byteAt(value, i+k)
				v = (v << 6) + (rune(octet) & 0x3F)
			}
			i += w
			em.put('\\')
			switch v {
			case 0x00:
				em.put('0')
			case 0x07:
				em.put('a')
			case 0x08:
				em.put('b')
			case 0x09:
				em.put('t')
			case 0x0A:
				em.put('n')
			case 0x0b:
				em.put('v')
			case 0x0c:
				em.put('f')
			case 0x0d:
				em.put('r')
			case 0x1b:
				em.put('e')
			case 0x22:
				em.put('"')
			case 0x5c:
				em.put('\\')
			case 0x85:
				em.put('N')
			case 0xA0:
				em.put('_')
			case 0x2028:
				em.put('L')
			case 0x2029:
				em.put('P')
			default:
				if v <= 0xFF {
					em.put('x')
					w = 2
				} else if v <= 0xFFFF {
					em.put('u')
					w = 4
				} else {
					em.put('U')
					w = 8
				}
				for k := (w - 1) * 4; k >= 0; k -= 4 {
					digit := byte((v >> uint(k)) & 0x0F)
					if digit < 10 {
						em.put(digit + '0')
					} else {
						em.put(digit + 'A' - 10)
					}
				}
			}
			spaces = false
		} else if isSpaceAt(value, i) {
			if allowBreaks && !spaces && em.column > em.bestWidth && i != 0 && i != len(value)-1 {
				if !em.writeIndent() {
					return false
				}
				if isSpaceAt(value, i+1) {
					em.put('\\')
				}
				i += width(value[i])
			} else if !em.write(value, &i) {
				return false
			}
			spaces = true
		} else {
			if !em.write(value, &i) {
				return false
			}
			spaces = false
		}
	}
	if !em.writeIndicator([]byte{'"'}, false, false, false) {
		return false
	}
	em.whitespace = false
	em.indention = false
	return true
}

func (em *emitter) writeBlockScalarHints(value []byte) bool {
	if isSpaceAt(value, 0) || isBreakAt(value, 0) {
		hint := []byte{'0' + byte(em.bestIndent)}
		if !em.writeIndicator(hint, false, false, false) {
			return false
		}
	}
	em.openEnded = false
	var chomp byte
	if len(value) == 0 {
		chomp = '-'
	} else {
		i := len(value) - 1
		for i > 0 && value[i]&0xC0 == 0x80 {
			i--
		}
		if !isBreakAt(value, i) {
			chomp = '-'
		} else if i == 0 {
			chomp = '+'
			em.openEnded = true
		} else {
			i--
			for i > 0 && value[i]&0xC0 == 0x80 {
				i--
			}
			if isBreakAt(value, i) {
				chomp = '+'
				em.openEnded = true
			}
		}
	}
	if chomp != 0 {
		if !em.writeIndicator([]byte{chomp}, false, false, false) {
			return false
		}
	}
	return true
}

func (em *emitter) writeLiteralScalar(value []byte) bool {
	if !em.writeIndicator([]byte{'|'}, true, false, false) {
		return false
	}
	if !em.writeBlockScalarHints(value) {
		return false
	}
	em.whitespace = true
	breaks := true
	for i := 0; i < len(value); {
		if isBreakAt(value, i) {
			if !em.writeBreak(value, &i) {
				return false
			}
			breaks = true
		} else {
			if breaks {
				if !em.writeIndent() {
					return false
				}
			}
			if !em.write(value, &i) {
				return false
			}
			em.indention = false
			breaks = false
		}
	}
	return true
}

func (em *emitter) writeFoldedScalar(value []byte) bool {
	if !em.writeIndicator([]byte{'>'}, true, false, false) {
		return false
	}
	if !em.writeBlockScalarHints(value) {
		return false
	}
	em.whitespace = true
	breaks := true
	leadingSpaces := true
	for i := 0; i < len(value); {
		if isBreakAt(value, i) {
			if !breaks && !leadingSpaces && value[i] == '\n' {
				k := 0
				for isBreakAt(value, k) {
					k += width(value[k])
				}
				if !isBlankZAt(value, k) {
					if !em.putBreak() {
						return false
					}
				}
			}
			if !em.writeBreak(value, &i) {
				return false
			}
			breaks = true
		} else {
			if breaks {
				if !em.writeIndent() {
					return false
				}
				leadingSpaces = isBlankAt(value, i)
			}
			if !breaks && isSpaceAt(value, i) && !isSpaceAt(value, i+1) && em.column > em.bestWidth {
				if !em.writeIndent() {
					return false
				}
				i += width(value[i])
			} else {
				if !em.write(value, &i) {
					return false
				}
			}
			em.indention = false
			breaks = false
		}
	}
	return true
}
