{"command":"cd /workspace && cat > yaml/encode.go <<'EOF'
package yaml

import (
	"encoding/base64"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"yj/order"
)

type encoder struct {
	em       *emitter
	indent   int
	doneInit bool
}

func (e *encoder) init() {
	if e.doneInit {
		return
	}
	e.em = newEmitter(e.indent)
	e.emit(event{typ: eStreamStart})
	e.doneInit = true
}

func (e *encoder) emit(ev event) {
	if !e.em.emit(&ev) {
		panic(yamlError{e.em.err})
	}
}

func (e *encoder) marshalDoc(v interface{}) {
	e.init()
	e.emit(event{typ: eDocumentStart, implicit: true})
	e.marshal(v)
	e.emit(event{typ: eDocumentEnd, implicit: true})
}

func (e *encoder) finish() {
	e.em.openEnded = false
	e.emit(event{typ: eStreamEnd})
}

func (e *encoder) emitScalar(value, tag string, style scalarStyle) {
	implicit := tag == ""
	if !implicit {
		tag = longTag(tag)
	}
	e.emit(event{typ: eScalar, tag: []byte(tag), value: []byte(value), implicit: implicit, quotedImplicit: implicit, style: int(style)})
}

func (e *encoder) marshal(v interface{}) {
	switch v := v.(type) {
	case nil:
		e.emitScalar("null", "", plainScalarStyle)
	case *Node:
		e.node(v, "")
	case order.MapSlice:
		n, err := mapSliceNode(v)
		if err != nil {
			panic(yamlError{err})
		}
		e.node(n, "")
	case []interface{}:
		e.emit(event{typ: eSequenceStart, implicit: true, style: int(blockStyle)})
		for _, x := range v {
			e.marshal(x)
		}
		e.emit(event{typ: eSequenceEnd})
	case string:
		e.stringv(v)
	case bool:
		e.emitScalar(strconv.FormatBool(v), "", plainScalarStyle)
	case int:
		e.emitScalar(strconv.FormatInt(int64(v), 10), "", plainScalarStyle)
	case int64:
		e.emitScalar(strconv.FormatInt(v, 10), "", plainScalarStyle)
	case uint64:
		e.emitScalar(strconv.FormatUint(v, 10), "", plainScalarStyle)
	case float64:
		e.emitScalar(FormatFloat(v), "", plainScalarStyle)
	case time.Time:
		e.emitScalar(v.Format(time.RFC3339Nano), "", plainScalarStyle)
	default:
		failf("cannot marshal type: %T", v)
	}
}

// FormatFloat renders a float the way the YAML output does.
func FormatFloat(f float64) string {
	s := strconv.FormatFloat(f, 'g', -1, 64)
	switch s {
	case "+Inf":
		return ".inf"
	case "-Inf":
		return "-.inf"
	case "NaN":
		return ".nan"
	}
	allDigits := true
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			allDigits = false
			break
		}
	}
	if allDigits {
		s += ".0"
	}
	return s
}

func (e *encoder) stringv(s string) {
	var style scalarStyle
	canUsePlain := true
	tag := ""
	switch {
	case !utf8.ValidString(s):
		tag = binaryTag
		s = encodeBase64(s)
	default:
		rtag, _ := resolve("", s)
		canUsePlain = rtag == strTag && !(isBase60Float(s) || isOldBool(s))
	}
	switch {
	case strings.Contains(s, "\n"):
		style = literalScalarStyle
	case canUsePlain:
		style = plainScalarStyle
	default:
		style = doubleQuotedScalarStyle
	}
	e.emitScalar(s, tag, style)
}

func encodeBase64(s string) string {
	const lineLen = 70
	encLen := base64.StdEncoding.EncodedLen(len(s))
	lines := encLen/lineLen + 1
	buf := make([]byte, encLen*2+lines)
	in := buf[0:encLen]
	out := buf[encLen:]
	base64.StdEncoding.Encode(in, []byte(s))
	k := 0
	for i := 0; i < len(in); i += lineLen {
		j := i + lineLen
		if j > len(in) {
			j = len(in)
		}
		k += copy(out[k:], in[i:j])
		if lines > 1 {
			out[k] = '\n'
			k++
		}
	}
	return string(out[:k])
}

func (e *encoder) node(node *Node, tail string) {
	if node.Kind == 0 && node.isZero() {
		e.emitScalar("null", "", plainScalarStyle)
		return
	}
	tag := node.Tag
	stag := shortTag(tag)
	var forceQuoting bool
	if tag != "" && node.Style&TaggedStyle == 0 {
		if node.Kind == ScalarNode {
			if stag == strTag && node.Style&(SingleQuotedStyle|DoubleQuotedStyle|LiteralStyle|FoldedStyle) != 0 {
				tag = ""
			} else {
				rtag, _ := resolve("", node.Value)
				if rtag == stag {
					tag = ""
				} else if stag == strTag {
					tag = ""
					forceQuoting = true
				}
			}
		} else {
			var rtag string
			switch node.Kind {
			case MappingNode:
				rtag = mapTag
			case SequenceNode:
				rtag = seqTag
			case AliasNode:
				rtag = strTag
			}
			if rtag == stag {
				tag = ""
			}
		}
	}
	switch node.Kind {
	case DocumentNode:
		e.emit(event{typ: eDocumentStart, implicit: true})
		for _, c := range node.Content {
			e.node(c, "")
		}
		e.emit(event{typ: eDocumentEnd, implicit: true})
	case SequenceNode:
		style := blockStyle
		if node.Style&FlowStyle != 0 {
			style = flowStyle
		}
		e.emit(event{typ: eSequenceStart, anchor: []byte(node.Anchor), tag: []byte(longTag(tag)), implicit: tag == "", style: int(style)})
		for _, c := range node.Content {
			e.node(c, "")
		}
		e.emit(event{typ: eSequenceEnd})
	case MappingNode:
		style := blockStyle
		if node.Style&FlowStyle != 0 {
			style = flowStyle
		}
		e.emit(event{typ: eMappingStart, anchor: []byte(node.Anchor), tag: []byte(longTag(tag)), implicit: tag == "", style: int(style)})
		for i := 0; i+1 < len(node.Content); i += 2 {
			e.node(node.Content[i], "")
			e.node(node.Content[i+1], "")
		}
		e.emit(event{typ: eMappingEnd})
	case AliasNode:
		e.emit(event{typ: eAlias, anchor: []byte(node.Value)})
	case ScalarNode:
		value := node.Value
		if !utf8.ValidString(value) {
			if stag == binaryTag {
				failf("explicitly tagged !!binary data must be base64-encoded")
			}
			if stag != "" {
				failf("cannot marshal invalid UTF-8 data as %s", stag)
			}
			tag = binaryTag
			value = encodeBase64(value)
		}
		style := plainScalarStyle
		switch {
		case node.Style&DoubleQuotedStyle != 0:
			style = doubleQuotedScalarStyle
		case node.Style&SingleQuotedStyle != 0:
			style = singleQuotedScalarStyle
		case node.Style&LiteralStyle != 0:
			style = literalScalarStyle
		case node.Style&FoldedStyle != 0:
			style = foldedScalarStyle
		case strings.Contains(value, "\n"):
			style = literalScalarStyle
		case forceQuoting:
			style = doubleQuotedScalarStyle
		}
		implicit := tag == ""
		e.emit(event{typ: eScalar, anchor: []byte(node.Anchor), tag: []byte(longTag(tag)), value: []byte(value), implicit: implicit, quotedImplicit: implicit, style: int(style)})
	default:
		failf("cannot encode node with unknown kind %d", node.Kind)
	}
}

// nodeEncode mimics Node.Encode: the value is rendered to text and parsed back.
func nodeEncode(v interface{}) (n *Node, err error) {
	defer handleErr(&err)
	e := &encoder{indent: 4}
	e.marshalDoc(v)
	e.finish()
	doc, err := parseText(e.em.out.Bytes())
	if err != nil {
		return nil, err
	}
	return doc.Content[0], nil
}

func mapSliceNode(m order.MapSlice) (*Node, error) {
	n := &Node{Kind: MappingNode}
	for _, item := range m {
		k, err := nodeEncode(item.Key)
		if err != nil {
			return nil, err
		}
		v, err := nodeEncode(item.Val)
		if err != nil {
			return nil, err
		}
		n.Content = append(n.Content, k, v)
	}
	return n, nil
}

// Marshal renders v as a YAML document using two space indentation.
func Marshal(v interface{}) (out []byte, err error) {
	defer handleErr(&err)
	e := &encoder{indent: 2}
	e.marshalDoc(v)
	e.finish()
	return e.em.out.Bytes(), nil
}
