// errNoDocument signals an empty YAML stream; nothing is written.
var errNoDocument = errors.New("no document")

func convert(cfg *config, input []byte) ([]byte, int, string) {
	var v interface{}
	var err error
	switch cfg.from {
	case 'y':
		v, err = decodeYAML(cfg, input)
	case 'j':
		v, err = decodeJSON(cfg, input)
	case 't':
		v, err = decodeTOML(cfg, input)
	case 'c':
		v, err = decodeHCL(cfg, input)
	}
	if err == errNoDocument {
		return nil, 0, ""
	}
	if err != nil {
		return nil, 1, fmt.Sprintf("Error parsing %s: %s\n", formatNames[cfg.from], err)
	}
	if !cfg.noFloat {
		inFloat := cfg.from == 'y' || cfg.from == 't'
		outFloat := cfg.to == 'y' || cfg.to == 't'
		if inFloat && !outFloat {
			v = floatsToStrings(v)
		} else if !inFloat && outFloat {
			v = stringsToFloats(v)
		}
	}
	var out []byte
	switch cfg.to {
	case 'y':
		out, err = encodeYAML(cfg, v)
	case 'j':
		out, err = encodeJSON(cfg, v)
	case 't':
		var p *panicInfo
		out, p, err = encodeTOML(cfg, v)
		if p != nil {
			return nil, 2, p.message
		}
	case 'c':
		out, err = encodeHCL(cfg, v)
	}
	if err != nil {
		return nil, 1, fmt.Sprintf("Error writing %s: %s\n", formatNames[cfg.to], err)
	}
	return out, 0, ""
}

type panicInfo struct {
	message string
}

func floatsToStrings(v interface{}) interface{} {
	switch v := v.(type) {
	case float64:
		switch {
		case math.IsInf(v, 1):
			return "Infinity"
		case math.IsInf(v, -1):
			return "-Infinity"
		case math.IsNaN(v):
			return "NaN"
		}
		return v
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, x := range v {
			out[i] = floatsToStrings(x)
		}
		return out
	case order.MapSlice:
		out := make(order.MapSlice, len(v))
		for i, item := range v {
			out[i] = order.MapItem{Key: item.Key, Val: floatsToStrings(item.Val)}
		}
		return out
	}
	return v
}

func stringsToFloats(v interface{}) interface{} {
	switch v := v.(type) {
	case string:
		switch v {
		case "Infinity":
			return math.Inf(1)
		case "-Infinity":
			return math.Inf(-1)
		case "NaN":
			return math.NaN()
		}
		return v
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, x := range v {
			out[i] = stringsToFloats(x)
		}
		return out
	case order.MapSlice:
		out := make(order.MapSlice, len(v))
		for i, item := range v {
			out[i] = order.MapItem{Key: item.Key, Val: stringsToFloats(item.Val)}
		}
		return out
	}
	return v
}

// keyString converts a decoded YAML key into the string used in maps.
func keyString(cfg *config, k interface{}) (string, error) {
	switch k := k.(type) {
	case string:
		return k, nil
	case time.Time:
		return k.String(), nil
	}
	if !cfg.noFloat {
		k = floatsToStrings(k)
		if s, ok := k.(string); ok {
			return s, nil
		}
	}
	b, err := jsonenc.Marshal(k, jsonenc.Options{EscapeHTML: cfg.escapeHTML})
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func decodeYAML(cfg *config, input []byte) (interface{}, error) {
	doc, err := yaml.ParseFirst(input)
	if err == yaml.ErrEOF {
		return nil, errNoDocument
	}
	if err != nil {
		return nil, err
	}
	return fromNode(cfg, doc.Content[0])
}

func isMerge(n *yaml.Node) bool {
	return n.Kind == yaml.ScalarNode && n.Value == "<<" && n.Tag == "!!merge"
}

func fromNode(cfg *config, n *yaml.Node) (interface{}, error) {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil, nil
		}
		return fromNode(cfg, n.Content[0])
	case yaml.AliasNode:
		return fromNode(cfg, n.Alias)
	case yaml.ScalarNode:
		v, err := yaml.ScalarValue(n)
		if err != nil {
			return nil, fmt.Errorf("scalar decode error: %w", err)
		}
		return v, nil
	case yaml.SequenceNode:
		out := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := fromNode(cfg, c)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case yaml.MappingNode:
		out := order.MapSlice{}
		for i := 0; i+1 < len(n.Content); i += 2 {
			kn, vn := n.Content[i], n.Content[i+1]
			if isMerge(kn) {
				target := vn
				if target.Kind == yaml.AliasNode {
					target = target.Alias
				}
				if target.Kind != yaml.MappingNode {
					return nil, errors.New("map merge requires map or sequence of maps as the value")
				}
				mv, err := fromNode(cfg, vn)
				if err != nil {
					return nil, err
				}
				merged := mv.(order.MapSlice)
				keys := map[interface{}]bool{}
				for _, item := range merged {
					keys[item.Key] = true
				}
				filtered := order.MapSlice{}
				for _, item := range out {
					if !keys[item.Key] {
						filtered = append(filtered, item)
					}
				}
				out = append(filtered, merged...)
				continue
			}
			kv, err := fromNode(cfg, kn)
			if err != nil {
				return nil, err
			}
			ks, err := keyString(cfg, kv)
			if err != nil {
				return nil, err
			}
			vv, err := fromNode(cfg, vn)
			if err != nil {
				return nil, err
			}
			out = append(out, order.MapItem{Key: ks, Val: vv})
		}
		return out, nil
	}
	return nil, nil
}

func decodeJSON(cfg *config, input []byte) (interface{}, error) {
	var tmp interface{}
	if err := json.Unmarshal(input, &tmp); err != nil {
		return nil, err
	}
	return decodeYAML(cfg, input)
}

func encodeJSON(cfg *config, v interface{}) ([]byte, error) {
	b, err := jsonenc.Marshal(v, jsonenc.Options{EscapeHTML: cfg.escapeHTML, Indent: cfg.indent})
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

var errZeroValue = errors.New("reflect: call of reflect.Value.Set on zero Value")

// yamlKeys prepares map keys for YAML output.
func yamlKeys(cfg *config, v interface{}) (interface{}, error) {
	switch v := v.(type) {
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, x := range v {
			y, err := yamlKeys(cfg, x)
			if err != nil {
				return nil, err
			}
			out[i] = y
		}
		return out, nil
	case order.MapSlice:
		out := make(order.MapSlice, len(v))
		for i, item := range v {
			k := item.Key
			if cfg.keys {
				if s, ok := k.(string); ok {
					parsed, err := decodeJSON(cfg, []byte(s))
					if err == nil {
						if parsed == nil {
							return nil, errZeroValue
						}
						k = parsed
					}
				}
			}
			if !cfg.noFloat {
				k = stringsToFloats(k)
			}
			val, err := yamlKeys(cfg, item.Val)
			if err != nil {
				return nil, err
			}
			out[i] = order.MapItem{Key: k, Val: val}
		}
		return out, nil
	}
	return v, nil
}

func encodeYAML(cfg *config, v interface{}) ([]byte, error) {
	v, err := yamlKeys(cfg, v)
	if err != nil {
		return nil, err
	}
	return yaml.Marshal(v)
}
