    err = r.stderr.replace(binary.encode(), b'PROG')
    out = r.stdout.replace(binary.encode(), b'PROG')
    return (out, err, r.returncode)

def orig(flags, data, env=None):
    h = hashlib.sha1(repr((flags, env)).encode() + b'\0' + data).hexdigest()
    p = os.path.join(CACHE, h)
    if os.path.exists(p):
        with open(p, 'rb') as f:
            return pickle.load(f)
