package toml

import (
	"fmt"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// Table is an insertion ordered map produced by the parser.
type Table struct {
	Keys []string
	M    map[string]interface{}
}

func newTable() *Table { return &Table{M: map[string]interface{}{}} }

func (t *Table) get(k string) (interface{}, bool) {
	v, ok := t.M[k]
	return v, ok
}

func (t *Table) set(k string, v interface{}) {
	if _, ok := t.M[k]; !ok {
		t.Keys = append(t.Keys, k)
	}
	t.M[k] = v
}

// Key is a TOML key path.
type Key []string

func (k Key) String() string {
	ss := make([]string, len(k))
	for i := range k {
		ss[i] = k.maybeQuoted(i)
	}
	return strings.Join(ss, ".")
}

func (k Key) maybeQuoted(i int) string {
	if k[i] == "" {
		return `""`
	}
	for _, c := range k[i] {
		if !isBareKeyChar(c) {
			return `"` + dblQuotedReplacer.Replace(k[i]) + `"`
		}
	}
	return k[i]
}

func (k Key) add(piece string) Key {
	newKey := make(Key, len(k)+1)
	copy(newKey, k)
	newKey[len(k)] = piece
	return newKey
}

type tomlType int

const (
	tomlNone tomlType = iota
	tomlInteger
	tomlFloat
	tomlDatetime
	tomlString
	tomlBool
	tomlArray
	tomlHash
	tomlArrayHash
)

type keyInfo struct {
	pos      Position
	tomlType tomlType
}

type parser struct {
	lx         *lexer
	context    Key
	currentKey string
	pos        Position
	ordered    []Key
	keyInfo    map[string]keyInfo
	mapping    *Table
	implicits  map[string]struct{}
}

type bugError string

// Location zones used for local date/time values.
var (
	localOffset   = func() int { _, o := time.Now().Zone(); return o }()
	LocalDatetime = time.FixedZone("datetime-local", localOffset)
	LocalDate     = time.FixedZone("date-local", localOffset)
	LocalTime     = time.FixedZone("time-local", localOffset)
)

// Parse parses TOML text. It returns the root table and the ordered keys.
func Parse(data string) (root *Table, ordered []Key, err error) {
	defer func() {
		if r := recover(); r != nil {
			if pErr, ok := r.(ParseError); ok {
				err = pErr
				return
			}
			if b, ok := r.(bugError); ok {
				err = fmt.Errorf("%s", string(b))
				return
			}
			panic(r)
		}
	}()
	if strings.HasPrefix(data, "\xff\xfe") || strings.HasPrefix(data, "\xfe\xff") {
		data = data[2:]
	} else if strings.HasPrefix(data, "\xef\xbb\xbf") {
		data = data[3:]
	}
	ex := 6
	if len(data) < 6 {
		ex = len(data)
	}
	if i := strings.IndexRune(data[:ex], 0); i > -1 {
		return nil, nil, ParseError{
			Message:  "files cannot contain NULL bytes; probably using UTF-16; TOML files must be UTF-8",
			Position: Position{Line: 1, Start: i, Len: 1},
		}
	}
	p := &parser{
		keyInfo:   map[string]keyInfo{},
		mapping:   newTable(),
		lx:        lex(data),
		implicits: map[string]struct{}{},
	}
	for {
		it := p.next()
		if it.typ == itemEOF {
			break
		}
		p.topLevel(it)
	}
	return p.mapping, p.ordered, nil
}

func (p *parser) panicErr(it item, err error) {
	panic(ParseError{err: err, Position: it.pos, LastKey: p.current()})
}

func (p *parser) panicItemf(it item, format string, v ...interface{}) {
	panic(ParseError{Message: fmt.Sprintf(format, v...), Position: it.pos, LastKey: p.current()})
}

func (p *parser) panicf(format string, v ...interface{}) {
	panic(ParseError{Message: fmt.Sprintf(format, v...), Position: p.pos, LastKey: p.current()})
}

func (p *parser) next() item {
	it := p.lx.nextItem()
	if it.typ == itemError {
		if it.err != nil {
			panic(ParseError{Position: it.pos, LastKey: p.current(), err: it.err})
		}
		p.panicItemf(it, "%s", it.val)
	}
	return it
}

func (p *parser) nextPos() item {
	it := p.next()
	p.pos = it.pos
	return it
}

func (p *parser) bug(format string, v ...interface{}) {
	panic(bugError(fmt.Sprintf("BUG: "+format+"\n\n", v...)))
}

func (p *parser) expect(typ itemType) item {
	it := p.next()
	p.assertEqual(typ, it.typ)
	return it
}

func (p *parser) assertEqual(expected, got itemType) {
	if expected != got {
		p.bug("Expected '%d' but got '%d'.", expected, got)
	}
}

func (p *parser) topLevel(it item) {
	switch it.typ {
	case itemCommentStart:
		p.expect(itemText)
	case itemTableStart:
		name := p.nextPos()
		var key Key
		for ; name.typ != itemTableEnd && name.typ != itemEOF; name = p.next() {
			key = append(key, p.keyString(name))
		}
		p.assertEqual(itemTableEnd, name.typ)
		p.addContext(key, false)
		p.setType("", tomlHash, it.pos)
		p.ordered = append(p.ordered, key)
	case itemArrayTableStart:
		name := p.nextPos()
		var key Key
		for ; name.typ != itemArrayTableEnd && name.typ != itemEOF; name = p.next() {
			key = append(key, p.keyString(name))
		}
		p.assertEqual(itemArrayTableEnd, name.typ)
		p.addContext(key, true)
		p.setType("", tomlArrayHash, it.pos)
		p.ordered = append(p.ordered, key)
	case itemKeyStart:
		outerContext := p.context
		k := p.nextPos()
		var key Key
		for ; k.typ != itemKeyEnd && k.typ != itemEOF; k = p.next() {
			key = append(key, p.keyString(k))
		}
		p.assertEqual(itemKeyEnd, k.typ)
		p.currentKey = key[len(key)-1]
		context := key[:len(key)-1]
		for i := range context {
			p.addImplicitContext(append(p.context, context[i:i+1]...))
		}
		p.ordered = append(p.ordered, p.context.add(p.currentKey))
		vItem := p.next()
		val, typ := p.value(vItem, false)
		p.set(p.currentKey, val, typ, vItem.pos)
		p.context = outerContext
		p.currentKey = ""
	default:
		p.bug("Unexpected type at top level: %d", it.typ)
	}
}

func (p *parser) keyString(it item) string {
	switch it.typ {
	case itemText:
		return it.val
	case itemString, itemMultilineString, itemRawString, itemRawMultilineString:
		s, _ := p.value(it, false)
		return s.(string)
	default:
		p.bug("Unexpected key type: %d", it.typ)
	}
	panic("unreachable")
}

var datetimeRepl = strings.NewReplacer("z", "Z", "t", "T", " ", "T")

func (p *parser) value(it item, parentIsArray bool) (interface{}, tomlType) {
	switch it.typ {
	case itemString:
		return p.replaceEscapes(it, it.val), tomlString
	case itemMultilineString:
		return p.replaceEscapes(it, stripFirstNewline(p.stripEscapedNewlines(it.val))), tomlString
	case itemRawString:
		return it.val, tomlString
	case itemRawMultilineString:
		return stripFirstNewline(it.val), tomlString
	case itemInteger:
		return p.valueInteger(it)
	case itemFloat:
		return p.valueFloat(it)
	case itemBool:
		switch it.val {
		case "true":
			return true, tomlBool
		case "false":
			return false, tomlBool
		default:
			p.bug("Expected boolean value, but got '%s'.", it.val)
		}
	case itemDatetime:
		return p.valueDatetime(it)
	case itemArray:
		return p.valueArray(it)
	case itemInlineTableStart:
		return p.valueInlineTable(it, parentIsArray)
	default:
		p.bug("Unexpected value type: %d", it.typ)
	}
	panic("unreachable")
}

func (p *parser) valueInteger(it item) (interface{}, tomlType) {
	if !numUnderscoresOK(it.val) {
		p.panicItemf(it, "Invalid integer %q: underscores must be surrounded by digits", it.val)
	}
	if numHasLeadingZero(it.val) {
		p.panicItemf(it, "Invalid integer %q: cannot have leading zeroes", it.val)
	}
	num, err := strconv.ParseInt(it.val, 0, 64)
	if err != nil {
		if e, ok := err.(*strconv.NumError); ok && e.Err == strconv.ErrRange {
			p.panicErr(it, errParseRange{i: it.val, size: "int64"})
		} else {
			p.bug("Expected integer value, but got '%s'.", it.val)
		}
	}
	return num, tomlInteger
}

func (p *parser) valueFloat(it item) (interface{}, tomlType) {
	parts := strings.FieldsFunc(it.val, func(r rune) bool {
		switch r {
		case '.', 'e', 'E':
			return true
		}
		return false
	})
	for _, part := range parts {
		if !numUnderscoresOK(part) {
			p.panicItemf(it, "Invalid float %q: underscores must be surrounded by digits", it.val)
		}
	}
	if len(parts) > 0 && numHasLeadingZero(parts[0]) {
		p.panicItemf(it, "Invalid float %q: cannot have leading zeroes", it.val)
	}
	if !numPeriodsOK(it.val) {
		p.panicItemf(it, "Invalid float %q: '.' must be followed by one or more digits", it.val)
	}
	val := strings.Replace(it.val, "_", "", -1)
	if val == "+nan" || val == "-nan" {
		val = "nan"
	}
	num, err := strconv.ParseFloat(val, 64)
	if err != nil {
		if e, ok := err.(*strconv.NumError); ok && e.Err == strconv.ErrRange {
			p.panicErr(it, errParseRange{i: it.val, size: "float64"})
		} else {
			p.panicItemf(it, "Invalid float value: %q", it.val)
		}
	}
	return num, tomlFloat
}

var dtTypes = []struct {
	fmt  string
	zone *time.Location
}{
	{time.RFC3339Nano, time.Local},
	{"2006-01-02T15:04:05.999999999", LocalDatetime},
	{"2006-01-02", LocalDate},
	{"15:04:05.999999999", LocalTime},
}

func (p *parser) valueDatetime(it item) (interface{}, tomlType) {
	it.val = datetimeRepl.Replace(it.val)
	var (
		t   time.Time
		ok  bool
		err error
	)
	for _, dt := range dtTypes {
		t, err = time.ParseInLocation(dt.fmt, it.val, dt.zone)
		if err == nil {
			ok = true
			break
		}
	}
	if !ok {
		p.panicItemf(it, "Invalid TOML Datetime: %q.", it.val)
	}
	return t, tomlDatetime
}

func (p *parser) valueArray(it item) (interface{}, tomlType) {
	p.setType(p.currentKey, tomlArray, it.pos)
	array := []interface{}{}
	for it = p.next(); it.typ != itemArrayEnd; it = p.next() {
		if it.typ == itemCommentStart {
			p.expect(itemText)
			continue
		}
		val, _ := p.value(it, true)
		array = append(array, val)
	}
	return array, tomlArray
}

func (p *parser) valueInlineTable(it item, parentIsArray bool) (interface{}, tomlType) {
	var (
		hash         = newTable()
		outerContext = p.context
		outerKey     = p.currentKey
	)
	p.context = append(p.context, p.currentKey)
	prevContext := p.context
	p.currentKey = ""
	p.addImplicit(p.context)
	p.addContext(p.context, parentIsArray)
	for it := p.next(); it.typ != itemInlineTableEnd; it = p.next() {
		if it.typ == itemCommentStart {
			p.expect(itemText)
			continue
		}
		k := p.nextPos()
		var key Key
		for ; k.typ != itemKeyEnd && k.typ != itemEOF; k = p.next() {
			key = append(key, p.keyString(k))
		}
		p.assertEqual(itemKeyEnd, k.typ)
		p.currentKey = key[len(key)-1]
		context := key[:len(key)-1]
		for i := range context {
			p.addImplicitContext(append(p.context, context[i:i+1]...))
		}
		p.ordered = append(p.ordered, p.context.add(p.currentKey))
		val, typ := p.value(p.next(), false)
		p.set(p.currentKey, val, typ, it.pos)
		hash.set(p.currentKey, val)
		p.context = prevContext
	}
	p.context = outerContext
	p.currentKey = outerKey
	return hash, tomlHash
}

func numHasLeadingZero(s string) bool {
	if len(s) > 1 && s[0] == '0' && !(s[1] == 'b' || s[1] == 'o' || s[1] == 'x') {
		return true
	}
	if len(s) > 2 && (s[0] == '-' || s[0] == '+') && s[1] == '0' {
		return true
	}
	return false
}

func numUnderscoresOK(s string) bool {
	switch s {
	case "nan", "+nan", "-nan", "inf", "-inf", "+inf":
		return true
	}
	accept := false
	for _, r := range s {
		if r == '_' {
			if !accept {
				return false
			}
		}
		accept = isHexadecimal(r)
	}
	return accept
}

func numPeriodsOK(s string) bool {
	period := false
	for _, r := range s {
		if period && !isDigit(r) {
			return false
		}
		period = r == '.'
	}
	return !period
}

func (p *parser) addContext(key Key, array bool) {
	var ok bool
	hashContext := p.mapping
	keyContext := make(Key, 0)
	for _, k := range key[0 : len(key)-1] {
		_, ok = hashContext.get(k)
		keyContext = append(keyContext, k)
		if !ok {
			p.addImplicit(keyContext)
			hashContext.set(k, newTable())
		}
		v, _ := hashContext.get(k)
		switch t := v.(type) {
		case []*Table:
			hashContext = t[len(t)-1]
		case *Table:
			hashContext = t
		default:
			p.panicf("Key '%s' was already created as a hash.", keyContext)
		}
	}
	p.context = keyContext
	if array {
		k := key[len(key)-1]
		if _, ok := hashContext.get(k); !ok {
			hashContext.set(k, make([]*Table, 0, 4))
		}
		v, _ := hashContext.get(k)
		if hash, ok := v.([]*Table); ok {
			hashContext.set(k, append(hash, newTable()))
		} else {
			p.panicf("Key '%s' was already created and cannot be used as an array.", key)
		}
	} else {
		p.setValue(key[len(key)-1], newTable())
	}
	p.context = append(p.context, key[len(key)-1])
}

func (p *parser) set(key string, val interface{}, typ tomlType, pos Position) {
	p.setValue(key, val)
	p.setType(key, typ, pos)
}

func (p *parser) setValue(key string, value interface{}) {
	var (
		tmpHash    interface{}
		ok         bool
		hash       = p.mapping
		keyContext Key
	)
	for _, k := range p.context {
		keyContext = append(keyContext, k)
		if tmpHash, ok = hash.get(k); !ok {
			p.bug("Context for key '%s' has not been established.", keyContext)
		}
		switch t := tmpHash.(type) {
		case []*Table:
			hash = t[len(t)-1]
		case *Table:
			hash = t
		default:
			p.panicf("Key '%s' has already been defined.", keyContext)
		}
	}
	keyContext = append(keyContext, key)
	if _, ok := hash.get(key); ok {
		if p.isArray(keyContext) {
			p.removeImplicit(keyContext)
			hash.set(key, value)
			return
		}
		if p.isImplicit(keyContext) {
			p.removeImplicit(keyContext)
			return
		}
		p.panicf("Key '%s' has already been defined.", keyContext)
	}
	hash.set(key, value)
}

func (p *parser) setType(key string, typ tomlType, pos Position) {
	keyContext := make(Key, 0, len(p.context)+1)
	keyContext = append(keyContext, p.context...)
	if len(key) > 0 {
		keyContext = append(keyContext, key)
	}
	if len(keyContext) == 0 {
		keyContext = Key{""}
	}
	p.keyInfo[keyContext.String()] = keyInfo{tomlType: typ, pos: pos}
}

func (p *parser) addImplicit(key Key)        { p.implicits[key.String()] = struct{}{} }
func (p *parser) removeImplicit(key Key)     { delete(p.implicits, key.String()) }
func (p *parser) isImplicit(key Key) bool    { _, ok := p.implicits[key.String()]; return ok }
func (p *parser) isArray(key Key) bool       { return p.keyInfo[key.String()].tomlType == tomlArray }
func (p *parser) addImplicitContext(key Key) { p.addImplicit(key); p.addContext(key, false) }

func (p *parser) current() string {
	if len(p.currentKey) == 0 {
		return p.context.String()
	}
	if len(p.context) == 0 {
		return p.currentKey
	}
	return fmt.Sprintf("%s.%s", p.context, p.currentKey)
}

func stripFirstNewline(s string) string {
	if len(s) > 0 && s[0] == '\n' {
		return s[1:]
	}
	if len(s) > 1 && s[0] == '\r' && s[1] == '\n' {
		return s[2:]
	}
	return s
}

func (p *parser) stripEscapedNewlines(s string) string {
	var b strings.Builder
	var i int
	for {
		ix := strings.Index(s[i:], `\`)
		if ix < 0 {
			b.WriteString(s)
			return b.String()
		}
		i += ix
		if len(s) > i+1 && s[i+1] == '\\' {
			i += 2
			continue
		}
		j := i + 1
	whitespaceLoop:
		for ; j < len(s); j++ {
			switch s[j] {
			case ' ', '\t', '\r', '\n':
			default:
				break whitespaceLoop
			}
		}
		if j == i+1 {
			i++
			continue
		}
		if !strings.Contains(s[i:j], "\n") {
			i++
			continue
		}
		b.WriteString(s[:i])
		s = s[j:]
		i = 0
	}
}

func (p *parser) replaceEscapes(it item, str string) string {
	replaced := make([]rune, 0, len(str))
	s := []byte(str)
	r := 0
	for r < len(s) {
		if s[r] != '\\' {
			c, size := utf8.DecodeRune(s[r:])
			r += size
			replaced = append(replaced, c)
			continue
		}
		r++
		if r >= len(s) {
			p.bug("Escape sequence at end of string.")
			return ""
		}
		switch s[r] {
		default:
			p.bug("Expected valid escape code after \\, but got %q.", s[r])
		case ' ', '\t':
			p.panicItemf(it, "invalid escape: '\\%c'", s[r])
		case 'b':
			replaced = append(replaced, rune(0x0008))
			r++
		case 't':
			replaced = append(replaced, rune(0x0009))
			r++
		case 'n':
			replaced = append(replaced, rune(0x000A))
			r++
		case 'f':
			replaced = append(replaced, rune(0x000C))
			r++
		case 'r':
			replaced = append(replaced, rune(0x000D))
			r++
		case '"':
			replaced = append(replaced, rune(0x0022))
			r++
		case '\\':
			replaced = append(replaced, rune(0x005C))
			r++
		case 'u':
			escaped := p.asciiEscapeToUnicode(it, s[r+1:r+5])
			replaced = append(replaced, escaped)
			r += 5
		case 'U':
			escaped := p.asciiEscapeToUnicode(it, s[r+1:r+9])
			replaced = append(replaced, escaped)
			r += 9
		}
	}
	return string(replaced)
}

func (p *parser) asciiEscapeToUnicode(it item, bs []byte) rune {
	s := string(bs)
	hex, err := strconv.ParseUint(strings.ToLower(s), 16, 32)
	if err != nil {
