package main

import (
	"fmt"

	"yj/order"
	"yj/toml"
)

func tomlToValue(v interface{}) interface{} {
	switch v := v.(type) {
	case *toml.Table:
		out := make(order.MapSlice, 0, len(v.Keys))
		for _, k := range v.Keys {
			out = append(out, order.MapItem{Key: k, Val: tomlToValue(v.M[k])})
		}
		return out
	case []*toml.Table:
		out := make([]interface{}, len(v))
		for i, t := range v {
			out[i] = tomlToValue(t)
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, x := range v {
			out[i] = tomlToValue(x)
		}
		return out
	}
	return v
}

// lookupPath reports the first key that cannot be found along path.
func lookupPath(v interface{}, path []string) (string, bool) {
	if len(path) == 0 {
		return "", true
	}
	switch v := v.(type) {
	case *toml.Table:
		next, ok := v.M[path[0]]
		if !ok {
			return path[0], false
