package hcl

import (
	"fmt"
	"strconv"
	"strings"
)

// Pos is a position in the source.
type Pos struct {
	Offset int
	Line   int
	Column int
}

// IsValid reports whether the position is valid.
func (p Pos) IsValid() bool { return p.Line > 0 }

func (p Pos) String() string {
	s := ""
	if p.IsValid() {
		s = fmt.Sprintf("%d:%d", p.Line, p.Column)
	}
	if s == "" {
		s = "-"
	}
	return s
}

// TokenType is an HCL token type.
type TokenType int

const (
	ILLEGAL TokenType = iota
	EOF
	COMMENT
	identifierBeg
	IDENT
	literalBeg
	NUMBER
	FLOAT
	BOOL
	STRING
	HEREDOC
	literalEnd
	identifierEnd
	operatorBeg
	LBRACK
	LBRACE
	COMMA
	PERIOD
	RBRACK
	RBRACE
	ASSIGN
	ADD
	SUB
	operatorEnd
)

var tokenNames = map[TokenType]string{
	ILLEGAL: "ILLEGAL",
	EOF:     "EOF",
	COMMENT: "COMMENT",
	IDENT:   "IDENT",
	NUMBER:  "NUMBER",
	FLOAT:   "FLOAT",
	BOOL:    "BOOL",
	STRING:  "STRING",
	LBRACK:  "LBRACK",
	LBRACE:  "LBRACE",
	COMMA:   "COMMA",
	PERIOD:  "PERIOD",
	HEREDOC: "HEREDOC",
	RBRACK:  "RBRACK",
	RBRACE:  "RBRACE",
	ASSIGN:  "ASSIGN",
	ADD:     "ADD",
	SUB:     "SUB",
}

func (t TokenType) String() string {
	if s, ok := tokenNames[t]; ok {
		return s
	}
	return "token(" + strconv.Itoa(int(t)) + ")"
}

// Token is a lexical token.
type Token struct {
	Type TokenType
	Pos  Pos
	Text string
	JSON bool
}

func (t Token) String() string {
	return fmt.Sprintf("%s %s %s", t.Pos.String(), t.Type.String(), t.Text)
}

// Value returns the Go value of a literal token.
func (t Token) Value() interface{} {
	switch t.Type {
	case BOOL:
		if t.Text == "true" {
			return true
		} else if t.Text == "false" {
			return false
		}
		panic("unknown bool value: " + t.Text)
	case FLOAT:
		v, err := strconv.ParseFloat(t.Text, 64)
		if err != nil {
			panic(err)
		}
		return v
	case NUMBER:
		v, err := strconv.ParseInt(t.Text, 0, 64)
		if err != nil {
			panic(err)
		}
		return v
	case IDENT:
		return t.Text
	case HEREDOC:
		return unindentHeredoc(t.Text)
	case STRING:
		f := Unquote
		if t.JSON {
			f = strconv.Unquote
		}
		if t.Text == "" {
			return ""
		}
		v, err := f(t.Text)
		if err != nil {
			panic(fmt.Sprintf("unquote %s err: %s", t.Text, err))
		}
		return v
	default:
		panic(fmt.Sprintf("unimplemented Value for type: %s", t.Type))
	}
}

func unindentHeredoc(heredoc string) string {
	idx := strings.IndexByte(heredoc, '\n')
	if idx == -1 {
		panic("heredoc doesn't contain newline")
	}
	unindent := heredoc[2] == '-'
	if !unindent {
		return heredoc[idx+1 : len(heredoc)-idx+1]
	}
	lines := strings.Split(heredoc[idx+1:len(heredoc)-idx+2], "\n")
	whitespacePrefix := lines[len(lines)-1]
	isIndented := true
	for _, v := range lines {
		if strings.HasPrefix(v, whitespacePrefix) {
			continue
		}
		isIndented = false
		break
	}
	if !isIndented {
		return strings.TrimRight(heredoc[idx+1:len(heredoc)-idx+1], " \t")
	}
	unindentedLines := make([]string, len(lines))
	for k, v := range lines {
		if k == len(lines)-1 {
			unindentedLines[k] = ""
			break
		}
		unindentedLines[k] = strings.TrimPrefix(v, whitespacePrefix)
	}
	return strings.Join(unindentedLines, "\n")
}

// Node is an AST node.
type Node interface {
	Pos() Pos
}

// File is the root of a parsed document.
type File struct {
	Node *ObjectList
}

// ObjectList is a list of object items.
type ObjectList struct {
	Items []*ObjectItem
}

func (o *ObjectList) Add(item *ObjectItem) { o.Items = append(o.Items, item) }

func (o *ObjectList) Pos() Pos {
	if len(o.Items) == 0 {
		return Pos{}
	}
	return o.Items[0].Pos()
}

// Filter returns the items whose keys begin with the given prefix, with the
// prefix stripped.
func (o *ObjectList) Filter(keys ...string) *ObjectList {
	var result ObjectList
	for _, item := range o.Items {
		if len(item.Keys) < len(keys) {
			continue
		}
		match := true
		for i, key := range item.Keys[:len(keys)] {
			k := key.Token.Value().(string)
			if k != keys[i] {
				match = false
				break
			}
		}
		if !match {
			continue
		}
		newItem := *item
		newItem.Keys = newItem.Keys[len(keys):]
		result.Add(&newItem)
	}
	return &result
}

// ObjectItem is a key/value item.
type ObjectItem struct {
	Keys   []*ObjectKey
	Assign Pos
	Val    Node
}

func (o *ObjectItem) Pos() Pos {
	if len(o.Keys) == 0 {
		return Pos{}
	}
	return o.Keys[0].Pos()
}

// ObjectKey is a key of an item.
type ObjectKey struct {
	Token Token
}

func (o *ObjectKey) Pos() Pos { return o.Token.Pos }

// LiteralType is a literal value.
type LiteralType struct {
	Token Token
}

func (l *LiteralType) Pos() Pos { return l.Token.Pos }

// ListType is a list value.
type ListType struct {
	Lbrack Pos
	Rbrack Pos
	List   []Node
}

func (l *ListType) Pos() Pos   { return l.Lbrack }
func (l *ListType) Add(n Node) { l.List = append(l.List, n) }

// ObjectType is an object value.
type ObjectType struct {
	Lbrace Pos
	Rbrace Pos
	List   *ObjectList
}

func (o *ObjectType) Pos() Pos { return o.Lbrace }

// PosError is an error with a position.
type PosError struct {
	Pos Pos
	Err error
}

func (e *PosError) Error() string {
	return fmt.Sprintf("At %s: %s", e.Pos, e.Err)
}
