package hcl

import (
	"bytes"
	"fmt"
	"regexp"
	"unicode"
	"unicode/utf8"
)

const eof = rune(0)

type scanner struct {
	buf *bytes.Reader
	src []byte

	srcPos  Pos
	prevPos Pos

	lastCharLen int
	lastLineLen int

	tokStart int
	tokEnd   int

	errorFn func(pos Pos, msg string)

	tokPos Pos
}

func newScanner(src []byte) *scanner {
	s := &scanner{buf: bytes.NewReader(src), src: src}
	s.srcPos.Line = 1
	return s
}

func (s *scanner) next() rune {
	ch, size, err := s.buf.ReadRune()
	if err != nil {
		s.srcPos.Column++
		s.srcPos.Offset += size
		s.lastCharLen = size
		return eof
	}
	s.prevPos = s.srcPos
	s.srcPos.Column++
	s.lastCharLen = size
	s.srcPos.Offset += size
	if ch == utf8.RuneError && size == 1 {
		s.err("illegal UTF-8 encoding")
		return ch
	}
	if ch == '\n' {
		s.srcPos.Line++
		s.lastLineLen = s.srcPos.Column
		s.srcPos.Column = 0
	}
	if ch == '\x00' {
		s.err("unexpected null character (0x00)")
		return eof
	}
	if ch == '\uE123' {
		s.err("unicode code point U+E123 reserved for internal use")
		return utf8.RuneError
	}
	return ch
}

func (s *scanner) unread() {
	if err := s.buf.UnreadRune(); err != nil {
		panic(err)
	}
	s.srcPos = s.prevPos
}

func (s *scanner) peek() rune {
	peek, _, err := s.buf.ReadRune()
	if err != nil {
		return eof
	}
	s.buf.UnreadRune()
	return peek
}

func (s *scanner) Scan() Token {
	ch := s.next()
	for isWhitespace(ch) {
		ch = s.next()
	}
	var tok TokenType
	s.tokStart = s.srcPos.Offset - s.lastCharLen
	s.tokPos.Offset = s.srcPos.Offset - s.lastCharLen
	if s.srcPos.Column > 0 {
		s.tokPos.Line = s.srcPos.Line
		s.tokPos.Column = s.srcPos.Column
	} else {
		s.tokPos.Line = s.srcPos.Line - 1
		s.tokPos.Column = s.lastLineLen
	}
	switch {
	case isLetter(ch):
		tok = IDENT
		lit := s.scanIdentifier()
		if lit == "true" || lit == "false" {
			tok = BOOL
		}
	case isDecimal(ch):
		tok = s.scanNumber(ch)
	default:
		switch ch {
		case eof:
			tok = EOF
		case '"':
			tok = STRING
			s.scanString()
		case '#', '/':
			tok = COMMENT
			s.scanComment(ch)
		case '.':
			tok = PERIOD
			ch = s.peek()
			if isDecimal(ch) {
				tok = FLOAT
				ch = s.scanMantissa(ch)
				ch = s.scanExponent(ch)
			}
		case '<':
			tok = HEREDOC
			s.scanHeredoc()
		case '[':
			tok = LBRACK
		case ']':
			tok = RBRACK
		case '{':
			tok = LBRACE
		case '}':
			tok = RBRACE
		case ',':
			tok = COMMA
		case '=':
			tok = ASSIGN
		case '+':
			tok = ADD
		case '-':
			if isDecimal(s.peek()) {
				ch := s.next()
				tok = s.scanNumber(ch)
			} else {
				tok = SUB
			}
		default:
			s.err("illegal char")
		}
	}
	s.tokEnd = s.srcPos.Offset
	var tokenText string
	if s.tokStart >= 0 && s.tokStart <= s.tokEnd && s.tokEnd <= len(s.src) {
		tokenText = string(s.src[s.tokStart:s.tokEnd])
	}
	s.tokStart = s.tokEnd
	return Token{Type: tok, Pos: s.tokPos, Text: tokenText}
}

func (s *scanner) scanComment(ch rune) {
	if ch == '#' || (ch == '/' && s.peek() != '*') {
		if ch == '/' && s.peek() != '/' {
			s.err("expected '/' for comment")
			return
		}
		ch = s.next()
		for ch != '\n' && ch >= 0 && ch != eof {
			ch = s.next()
		}
		if ch != eof && ch >= 0 {
			s.unread()
		}
		return
	}
	if ch == '/' {
		s.next()
		ch = s.next()
	}
	for {
		if ch < 0 || ch == eof {
			s.err("comment not terminated")
			break
		}
		ch0 := ch
		ch = s.next()
		if ch0 == '*' && ch == '/' {
			break
		}
	}
}

func (s *scanner) scanNumber(ch rune) TokenType {
	if ch == '0' {
		ch = s.next()
		if ch == 'x' || ch == 'X' {
			ch = s.next()
			found := false
			for isHexadecimal(ch) {
				ch = s.next()
				found = true
			}
			if !found {
				s.err("illegal hexadecimal number")
			}
			if ch != eof {
				s.unread()
			}
			return NUMBER
		}
		illegalOctal := false
		for isDecimal(ch) {
			ch = s.next()
			if ch == '8' || ch == '9' {
				illegalOctal = true
			}
		}
		if ch == 'e' || ch == 'E' {
			ch = s.scanExponent(ch)
			return FLOAT
		}
		if ch == '.' {
			ch = s.scanFraction(ch)
			if ch == 'e' || ch == 'E' {
				ch = s.next()
				ch = s.scanExponent(ch)
			}
			return FLOAT
		}
		if illegalOctal {
			s.err("illegal octal number")
		}
		if ch != eof {
			s.unread()
		}
		return NUMBER
	}
	s.scanMantissa(ch)
	ch = s.next()
	if ch == 'e' || ch == 'E' {
		ch = s.scanExponent(ch)
		return FLOAT
	}
	if ch == '.' {
		ch = s.scanFraction(ch)
		if ch == 'e' || ch == 'E' {
			ch = s.next()
			ch = s.scanExponent(ch)
		}
		return FLOAT
	}
	if ch != eof {
		s.unread()
	}
	return NUMBER
}

func (s *scanner) scanMantissa(ch rune) rune {
	scanned := false
	for isDecimal(ch) {
		ch = s.next()
		scanned = true
	}
	if scanned && ch != eof {
		s.unread()
	}
	return ch
}

func (s *scanner) scanFraction(ch rune) rune {
	if ch == '.' {
		ch = s.peek()
		ch = s.scanMantissa(ch)
	}
	return ch
}

func (s *scanner) scanExponent(ch rune) rune {
	if ch == 'e' || ch == 'E' {
		ch = s.next()
		if ch == '-' || ch == '+' {
			ch = s.next()
		}
		ch = s.scanMantissa(ch)
	}
	return ch
}

func (s *scanner) scanHeredoc() {
	if s.next() != '<' {
		s.err("heredoc expected second '<', didn't see it")
		return
	}
	offs := s.srcPos.Offset
	ch := s.next()
	if ch == '-' {
		ch = s.next()
	}
	for isLetter(ch) || isDigit(ch) {
		ch = s.next()
	}
	if ch == eof {
		s.err("heredoc not terminated")
		return
	}
	if ch == '\r' {
		if s.peek() == '\n' {
			ch = s.next()
		}
	}
	if ch != '\n' {
		s.err("invalid characters in heredoc anchor")
		return
	}
	identBytes := s.src[offs : s.srcPos.Offset-s.lastCharLen]
	if len(identBytes) == 0 || (len(identBytes) == 1 && identBytes[0] == '-') {
		s.err("zero-length heredoc anchor")
		return
	}
	var identRegexp *regexp.Regexp
	if identBytes[0] == '-' {
		identRegexp = regexp.MustCompile(fmt.Sprintf(`^[[:space:]]*%s\r*\z`, identBytes[1:]))
	} else {
		identRegexp = regexp.MustCompile(fmt.Sprintf(`^[[:space:]]*%s\r*\z`, identBytes))
	}
	lineStart := s.srcPos.Offset
	for {
		ch := s.next()
		if ch == '\n' {
			lineBytesLen := s.srcPos.Offset - s.lastCharLen - lineStart
			if lineBytesLen >= len(identBytes) && identRegexp.Match(s.src[lineStart:s.srcPos.Offset-s.lastCharLen]) {
				break
			}
			lineStart = s.srcPos.Offset
		}
		if ch == eof {
			s.err("heredoc not terminated")
			return
		}
	}
}

func (s *scanner) scanString() {
	braces := 0
	for {
		ch := s.next()
		if (ch == '\n' && braces == 0) || ch < 0 || ch == eof {
			s.err("literal not terminated")
			return
		}
		if ch == '"' && braces == 0 {
			break
		}
		if braces == 0 && ch == '$' && s.peek() == '{' {
			braces++
			s.next()
		} else if braces > 0 && ch == '{' {
			braces++
		}
		if braces > 0 && ch == '}' {
			braces--
		}
		if ch == '\\' {
			s.scanEscape()
		}
	}
}

func (s *scanner) scanEscape() rune {
	ch := s.next()
	switch ch {
	case 'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', '"':
	case '0', '1', '2', '3', '4', '5', '6', '7':
		ch = s.scanDigits(ch, 8, 3)
	case 'x':
		ch = s.scanDigits(s.next(), 16, 2)
	case 'u':
		ch = s.scanDigits(s.next(), 16, 4)
	case 'U':
		ch = s.scanDigits(s.next(), 16, 8)
	default:
		s.err("illegal char escape")
	}
	return ch
}

func (s *scanner) scanDigits(ch rune, base, n int) rune {
	start := n
	for n > 0 && digitVal(ch) < base {
		ch = s.next()
		if ch == eof {
			break
		}
		n--
	}
	if n > 0 {
		s.err("illegal char escape")
	}
	if n != start && ch != eof {
		s.unread()
	}
	return ch
}

func (s *scanner) scanIdentifier() string {
	offs := s.srcPos.Offset - s.lastCharLen
	ch := s.next()
	for isLetter(ch) || isDigit(ch) || ch == '-' || ch == '.' {
		ch = s.next()
	}
	if ch != eof {
		s.unread()
	}
	return string(s.src[offs:s.srcPos.Offset])
}

func (s *scanner) recentPosition() (pos Pos) {
	pos.Offset = s.srcPos.Offset - s.lastCharLen
	switch {
	case s.srcPos.Column > 0:
		pos.Line = s.srcPos.Line
		pos.Column = s.srcPos.Column
	case s.lastLineLen > 0:
		pos.Line = s.srcPos.Line - 1
		pos.Column = s.lastLineLen
	default:
		pos.Line = 1
		pos.Column = 1
	}
	return
}

func (s *scanner) err(msg string) {
	pos := s.recentPosition()
	if s.errorFn != nil {
		s.errorFn(pos, msg)
	}
}

func isLetter(ch rune) bool {
	return 'a' <= ch && ch <= 'z' || 'A' <= ch && ch <= 'Z' || ch == '_' || ch >= 0x80 && unicode.IsLetter(ch)
}

func isDigit(ch rune) bool {
	return '0' <= ch && ch <= '9' || ch >= 0x80 && unicode.IsDigit(ch)
}

func isDecimal(ch rune) bool { return '0' <= ch && ch <= '9' }

func isHexadecimal(ch rune) bool {
	return '0' <= ch && ch <= '9' || 'a' <= ch && ch <= 'f' || 'A' <= ch && ch <= 'F'
}

func isWhitespace(ch rune) bool {
	return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r'
}

func digitVal(ch rune) int {
	switch {
	case '0' <= ch && ch <= '9':
		return int(ch - '0')
	case 'a' <= ch && ch <= 'f':
		return int(ch - 'a' + 10)
	case 'A' <= ch && ch <= 'F':
		return int(ch - 'A' + 10)
	}
	return 16
}
