}

func isJSONMode(v []byte) bool {
	offset := 0
	for {
		r, w := utf8.DecodeRune(v[offset:])
		offset += w
		if unicode.IsSpace(r) {
			continue
		}
		return r == '{'
	}
}

func parseHCL(src []byte) (*File, error) {
	src = bytes.Replace(src, []byte("\r\n"), []byte("\n"), -1)
	p := &hclParser{sc: newScanner(src)}
	f := &File{}
	var err, scerr error
	p.sc.errorFn = func(pos Pos, msg string) {
		scerr = &PosError{Pos: pos, Err: errors.New(msg)}
	}
	f.Node, err = p.objectList(false)
	if scerr != nil {
		return nil, scerr
	}
	if err != nil {
		return nil, err
	}
	return f, nil
}

func (p *hclParser) objectList(obj bool) (*ObjectList, error) {
	node := &ObjectList{}
	for {
		if obj {
			tok := p.scan()
			p.unscan()
			if tok.Type == RBRACE {
				break
			}
		}
		n, err := p.objectItem()
		if err == errEofToken {
			break
		}
		if err != nil {
			return node, err
		}
		node.Add(n)
		tok := p.scan()
		if tok.Type != COMMA {
			p.unscan()
		}
	}
	return node, nil
}

func (p *hclParser) objectItem() (*ObjectItem, error) {
	keys, err := p.objectKey()
	if len(keys) > 0 && err == errEofToken {
		err = nil
	}
	if len(keys) > 0 && err != nil && p.tok.Type == RBRACE {
		err = nil
		p.tok.Type = EOF
	}
	if err != nil {
		return nil, err
	}
	o := &ObjectItem{Keys: keys}
	switch p.tok.Type {
	case ASSIGN:
		o.Assign = p.tok.Pos
		o.Val, err = p.object()
		if err != nil {
			return nil, err
		}
	case LBRACE:
		o.Val, err = p.objectType()
		if err != nil {
			return nil, err
		}
	default:
		keyStr := make([]string, 0, len(keys))
		for _, k := range keys {
			keyStr = append(keyStr, k.Token.Text)
		}
		return nil, &PosError{
			Pos: p.tok.Pos,
			Err: fmt.Errorf("key '%s' expected start of object ('{') or assignment ('=')", strings.Join(keyStr, " ")),
		}
	}
	p.scan()
	p.unscan()
	return o, nil
}

func (p *hclParser) objectKey() ([]*ObjectKey, error) {
	keyCount := 0
	keys := make([]*ObjectKey, 0)
	for {
		tok := p.scan()
		switch tok.Type {
		case EOF:
			return keys, errEofToken
		case ASSIGN:
			if keyCount > 1 {
				return nil, &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("nested object expected: LBRACE got: %s", p.tok.Type)}
			}
			if keyCount == 0 {
				return nil, &PosError{Pos: p.tok.Pos, Err: errors.New("no object keys found!")}
			}
			return keys, nil
		case LBRACE:
			var err error
			if len(keys) == 0 {
				err = &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("expected: IDENT | STRING got: %s", p.tok.Type)}
			}
			return keys, err
		case IDENT, STRING:
			keyCount++
			keys = append(keys, &ObjectKey{Token: p.tok})
		case ILLEGAL:
			return keys, &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("illegal character")}
		default:
			return keys, &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("expected: IDENT | STRING | ASSIGN | LBRACE got: %s", p.tok.Type)}
		}
	}
}

func (p *hclParser) object() (Node, error) {
	tok := p.scan()
	switch tok.Type {
	case NUMBER, FLOAT, BOOL, STRING, HEREDOC:
		return p.literalType()
	case LBRACE:
		return p.objectType()
	case LBRACK:
		return p.listType()
	case COMMENT:
	case EOF:
		return nil, errEofToken
	}
	return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("Unknown token: %+v", tok)}
}

func (p *hclParser) objectType() (*ObjectType, error) {
	o := &ObjectType{Lbrace: p.tok.Pos}
	l, err := p.objectList(true)
	if err != nil && p.tok.Type != RBRACE {
		return nil, err
	}
	if tok := p.scan(); tok.Type != RBRACE {
		return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("object expected closing RBRACE got: %s", tok.Type)}
	}
	o.List = l
	o.Rbrace = p.tok.Pos
	return o, nil
}

func (p *hclParser) listType() (*ListType, error) {
	l := &ListType{Lbrack: p.tok.Pos}
	needComma := false
	for {
		tok := p.scan()
		if needComma {
			switch tok.Type {
			case COMMA, RBRACK:
			default:
				return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("error parsing list, expected comma or list end, got: %s", tok.Type)}
			}
		}
		switch tok.Type {
		case BOOL, NUMBER, FLOAT, STRING, HEREDOC:
			node, err := p.literalType()
			if err != nil {
				return nil, err
			}
			l.Add(node)
			needComma = true
		case COMMA:
			p.scan()
			p.unscan()
			needComma = false
			continue
		case LBRACE:
			node, err := p.objectType()
			if err != nil {
				return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("error while trying to parse object within list: %s", err)}
			}
			l.Add(node)
			needComma = true
		case LBRACK:
			node, err := p.listType()
			if err != nil {
				return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("error while trying to parse list within list: %s", err)}
			}
			l.Add(node)
		case RBRACK:
			l.Rbrack = p.tok.Pos
			return l, nil
		default:
			return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("unexpected token while parsing list: %s", tok.Type)}
		}
	}
}

func (p *hclParser) literalType() (*LiteralType, error) {
	return &LiteralType{Token: p.tok}, nil
}

func (p *hclParser) scan() Token {
	if p.n != 0 {
		p.n = 0
		return p.tok
	}
	p.tok = p.sc.Scan()
	for p.tok.Type == COMMENT {
		p.tok = p.sc.Scan()
	}
	return p.tok
}

func (p *hclParser) unscan() { p.n = 1 }
