				err = &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("expected: IDENT | STRING got: %s", p.tok.Type)}
			}
			return keys, err
		case IDENT, STRING:
			keyCount++
			keys = append(keys, &ObjectKey{Token: p.tok})
		case ILLEGAL:
			return keys, &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("illegal character")}
		default:
			return keys, &PosError{Pos: p.tok.Pos, Err: fmt.Errorf("expected: IDENT | STRING | ASSIGN | LBRACE got: %s", p.tok.Type)}
		}
	}
}

func (p *hclParser) object() (Node, error) {
	tok := p.scan()
	switch tok.Type {
	case NUMBER, FLOAT, BOOL, STRING, HEREDOC:
		return p.literalType()
	case LBRACE:
		return p.objectType()
	case LBRACK:
		return p.listType()
	case COMMENT:
	case EOF:
		return nil, errEofToken
	}
	return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("Unknown token: %+v", tok)}
}

func (p *hclParser) objectType() (*ObjectType, error) {
	o := &ObjectType{Lbrace: p.tok.Pos}
	l, err := p.objectList(true)
	if err != nil && p.tok.Type != RBRACE {
		return nil, err
	}
	if tok := p.scan(); tok.Type != RBRACE {
		return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("object expected closing RBRACE got: %s", tok.Type)}
	}
	o.List = l
	o.Rbrace = p.tok.Pos
	return o, nil
}

func (p *hclParser) listType() (*ListType, error) {
	l := &ListType{Lbrack: p.tok.Pos}
	needComma := false
	for {
		tok := p.scan()
		if needComma {
			switch tok.Type {
			case COMMA, RBRACK:
			default:
				return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("error parsing list, expected comma or list end, got: %s", tok.Type)}
			}
		}
		switch tok.Type {
		case BOOL, NUMBER, FLOAT, STRING, HEREDOC:
			node, err := p.literalType()
			if err != nil {
				return nil, err
			}
			l.Add(node)
			needComma = true
		case COMMA:
			p.scan()
			p.unscan()
			needComma = false
			continue
		case LBRACE:
			node, err := p.objectType()
			if err != nil {
				return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("error while trying to parse object within list: %s", err)}
			}
			l.Add(node)
			needComma = true
		case LBRACK:
			node, err := p.listType()
			if err != nil {
				return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("error while trying to parse list within list: %s", err)}
			}
			l.Add(node)
		case RBRACK:
			l.Rbrack = p.tok.Pos
			return l, nil
		default:
			return nil, &PosError{Pos: tok.Pos, Err: fmt.Errorf("unexpected token while parsing list: %s", tok.Type)}
		}
	}
}

func (p *hclParser) literalType() (*LiteralType, error) {
	return &LiteralType{Token: p.tok}, nil
}

func (p *hclParser) scan() Token {
	if p.n != 0 {
		p.n = 0
		return p.tok
	}
	p.tok = p.sc.Scan()
	for p.tok.Type == COMMENT {
		p.tok = p.sc.Scan()
	}
	return p.tok
}

func (p *hclParser) unscan() { p.n = 1 }
