type jsonScanner struct {
	buf *bytes.Reader
	src []byte

	srcPos  Pos
	prevPos Pos

	lastCharLen int
	lastLineLen int

	tokStart int
	tokEnd   int

	errorFn func(pos Pos, msg string)

	tokPos Pos
}

func newJSONScanner(src []byte) *jsonScanner {
	s := &jsonScanner{buf: bytes.NewReader(src), src: src}
	s.srcPos.Line = 1
	return s
}

func (s *jsonScanner) next() rune {
	ch, size, err := s.buf.ReadRune()
	if err != nil {
		s.srcPos.Column++
		s.srcPos.Offset += size
		s.lastCharLen = size
		return eof
	}
	if ch == utf8.RuneError && size == 1 {
		s.srcPos.Column++
		s.srcPos.Offset += size
		s.lastCharLen = size
		s.err("illegal UTF-8 encoding")
		return ch
	}
	s.prevPos = s.srcPos
	s.srcPos.Column++
	s.lastCharLen = size
	s.srcPos.Offset += size
	if ch == '\n' {
		s.srcPos.Line++
		s.lastLineLen = s.srcPos.Column
		s.srcPos.Column = 0
	}
	return ch
}

func (s *jsonScanner) unread() {
	if err := s.buf.UnreadRune(); err != nil {
		panic(err)
	}
	s.srcPos = s.prevPos
}

func (s *jsonScanner) peek() rune {
	peek, _, err := s.buf.ReadRune()
	if err != nil {
		return eof
	}
	s.buf.UnreadRune()
	return peek
}

func (s *jsonScanner) Scan() jsonToken {
	ch := s.next()
	for isWhitespace(ch) {
		ch = s.next()
	}
	var tok jsonTokenType
	s.tokStart = s.srcPos.Offset - s.lastCharLen
	s.tokPos.Offset = s.srcPos.Offset - s.lastCharLen
	if s.srcPos.Column > 0 {
		s.tokPos.Line = s.srcPos.Line
		s.tokPos.Column = s.srcPos.Column
	} else {
		s.tokPos.Line = s.srcPos.Line - 1
		s.tokPos.Column = s.lastLineLen
	}
	switch {
	case isLetter(ch):
		lit := s.scanIdentifier()
		if lit == "true" || lit == "false" {
			tok = jBOOL
		} else if lit == "null" {
			tok = jNULL
		} else {
			s.err("illegal char")
		}
	case isDecimal(ch):
		tok = s.scanNumber(ch)
	default:
		switch ch {
		case eof:
			tok = jEOF
		case '"':
			tok = jSTRING
			s.scanString()
		case '.':
			tok = jPERIOD
			ch = s.peek()
			if isDecimal(ch) {
				tok = jFLOAT
				ch = s.scanMantissa(ch)
				ch = s.scanExponent(ch)
			}
		case '[':
			tok = jLBRACK
		case ']':
			tok = jRBRACK
		case '{':
			tok = jLBRACE
		case '}':
			tok = jRBRACE
		case ',':
			tok = jCOMMA
		case ':':
			tok = jCOLON
		case '-':
			if isDecimal(s.peek()) {
				ch := s.next()
				tok = s.scanNumber(ch)
			} else {
				s.err("illegal char")
			}
		default:
			s.err("illegal char: " + string(ch))
		}
	}
	s.tokEnd = s.srcPos.Offset
	var tokenText string
	if s.tokStart >= 0 && s.tokStart <= s.tokEnd && s.tokEnd <= len(s.src) {
		tokenText = string(s.src[s.tokStart:s.tokEnd])
	}
	s.tokStart = s.tokEnd
	return jsonToken{Type: tok, Pos: s.tokPos, Text: tokenText}
}

func (s *jsonScanner) scanNumber(ch rune) jsonTokenType {
	zero := ch == '0'
	pos := s.srcPos
	s.scanMantissa(ch)
	ch = s.next()
	if ch == 'e' || ch == 'E' {
		ch = s.scanExponent(ch)
		return jFLOAT
	}
	if ch == '.' {
		ch = s.scanFraction(ch)
		if ch == 'e' || ch == 'E' {
			ch = s.next()
			ch = s.scanExponent(ch)
		}
		return jFLOAT
	}
	if ch != eof {
		s.unread()
	}
	if zero && pos != s.srcPos {
		s.err("numbers cannot start with 0")
	}
	return jNUMBER
}

func (s *jsonScanner) scanMantissa(ch rune) rune {
	scanned := false
	for isDecimal(ch) {
		ch = s.next()
		scanned = true
	}
	if scanned && ch != eof {
		s.unread()
	}
	return ch
}

func (s *jsonScanner) scanFraction(ch rune) rune {
	if ch == '.' {
		ch = s.peek()
		ch = s.scanMantissa(ch)
	}
	return ch
}

func (s *jsonScanner) scanExponent(ch rune) rune {
	if ch == 'e' || ch == 'E' {
		ch = s.next()
		if ch == '-' || ch == '+' {
			ch = s.next()
		}
		ch = s.scanMantissa(ch)
	}
	return ch
}

func (s *jsonScanner) scanString() {
	braces := 0
	for {
		ch := s.next()
		if ch == '\n' || ch < 0 || ch == eof {
			s.err("literal not terminated")
			return
		}
		if ch == '"' {
			break
		}
		if braces == 0 && ch == '$' && s.peek() == '{' {
			braces++
			s.next()
		} else if braces > 0 && ch == '{' {
			braces++
		}
		if braces > 0 && ch == '}' {
			braces--
		}
		if ch == '\\' {
			s.scanEscape()
		}
	}
}

func (s *jsonScanner) scanEscape() rune {
	ch := s.next()
	switch ch {
	case 'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', '"', '/':
	case '0', '1', '2', '3', '4', '5', '6', '7':
		ch = s.scanDigits(ch, 8, 3)
	case 'x':
		ch = s.scanDigits(s.next(), 16, 2)
	case 'u':
		ch = s.scanDigits(s.next(), 16, 4)
	case 'U':
		ch = s.scanDigits(s.next(), 16, 8)
	default:
		s.err("illegal char escape")
	}
	return ch
}

func (s *jsonScanner) scanDigits(ch rune, base, n int) rune {
	for n > 0 && digitVal(ch) < base {
		ch = s.next()
		n--
	}
	if n > 0 {
		s.err("illegal char escape")
	}
	s.unread()
	return ch
}

func (s *jsonScanner) scanIdentifier() string {
	offs := s.srcPos.Offset - s.lastCharLen
	ch := s.next()
	for isLetter(ch) || isDigit(ch) || ch == '-' {
		ch = s.next()
	}
	if ch != eof {
		s.unread()
	}
	return string(s.src[offs:s.srcPos.Offset])
}

func (s *jsonScanner) recentPosition() (pos Pos) {
	pos.Offset = s.srcPos.Offset - s.lastCharLen
	switch {
	case s.srcPos.Column > 0:
		pos.Line = s.srcPos.Line
		pos.Column = s.srcPos.Column
	case s.lastLineLen > 0:
		pos.Line = s.srcPos.Line - 1
		pos.Column = s.lastLineLen
	default:
		pos.Line = 1
		pos.Column = 1
	}
	return
}

func (s *jsonScanner) err(msg string) {
	pos := s.recentPosition()
	if s.errorFn != nil {
		s.errorFn(pos, msg)
	}
}

var _ = unicode.IsSpace

type jsonParser struct {
	sc  *jsonScanner
	tok jsonToken
	n   int
}

// ParseJSON parses the JSON flavour of HCL.
func ParseJSON(src []byte) (*File, error) {
	p := &jsonParser{sc: newJSONScanner(src)}
	f := &File{}
	var scerr error
	p.sc.errorFn = func(pos Pos, msg string) {
		scerr = fmt.Errorf("%s: %s", pos, msg)
	}
	object, err := p.object()
	if scerr != nil {
		return nil, scerr
	}
	if err != nil {
		return nil, err
	}
	f.Node = object.List
	flattenObjects(f.Node)
	return f, nil
}

func (p *jsonParser) objectList() (*ObjectList, error) {
	node := &ObjectList{}
	for {
		n, err := p.objectItem()
		if err == errEofToken {
			break
		}
		if err != nil {
			return node, err
		}
		node.Add(n)
		if tok := p.scan(); tok.Type != jCOMMA {
			break
		}
	}
	return node, nil
}

func (p *jsonParser) objectItem() (*ObjectItem, error) {
	keys, err := p.objectKey()
	if err != nil {
		return nil, err
	}
	o := &ObjectItem{Keys: keys}
	switch p.tok.Type {
	case jCOLON:
		o.Assign = p.tok.Pos
		o.Val, err = p.objectValue()
		if err != nil {
			return nil, err
		}
	}
	return o, nil
}

func (p *jsonParser) objectKey() ([]*ObjectKey, error) {
	keyCount := 0
	keys := make([]*ObjectKey, 0)
	for {
		tok := p.scan()
		switch tok.Type {
		case jEOF:
			return nil, errEofToken
		case jSTRING:
			keyCount++
			keys = append(keys, &ObjectKey{Token: p.tok.hclToken()})
		case jCOLON:
			if keyCount == 0 {
				return nil, fmt.Errorf("expected: STRING got: %s", p.tok.Type)
			}
			return keys, nil
		case jILLEGAL:
			return nil, errors.New("illegal")
		default:
			return nil, fmt.Errorf("expected: STRING got: %s", p.tok.Type)
		}
	}
}

func (p *jsonParser) objectValue() (Node, error) {
	tok := p.scan()
	switch tok.Type {
	case jNUMBER, jFLOAT, jBOOL, jNULL, jSTRING:
		return p.literalType()
	case jLBRACE:
		return p.objectType()
	case jLBRACK:
		return p.listType()
	case jEOF:
		return nil, errEofToken
	}
	return nil, fmt.Errorf("Expected object value, got unknown token: %+v", tok)
}

func (p *jsonParser) object() (*ObjectType, error) {
	tok := p.scan()
	switch tok.Type {
	case jLBRACE:
		return p.objectType()
	case jEOF:
		return nil, errEofToken
	}
	return nil, fmt.Errorf("Expected object, got unknown token: %+v", tok)
}

func (p *jsonParser) objectType() (*ObjectType, error) {
	o := &ObjectType{}
	l, err := p.objectList()
	if err != nil && p.tok.Type != jRBRACE {
		return nil, err
	}
	o.List = l
	return o, nil
}

func (p *jsonParser) listType() (*ListType, error) {
	l := &ListType{}
	for {
		tok := p.scan()
		switch tok.Type {
		case jNUMBER, jFLOAT, jSTRING:
			node, err := p.literalType()
			if err != nil {
				return nil, err
			}
			l.Add(node)
		case jCOMMA:
			continue
		case jLBRACE:
			node, err := p.objectType()
			if err != nil {
				return nil, err
			}
			l.Add(node)
		case jBOOL:
		case jLBRACK:
		case jRBRACK:
			return l, nil
		default:
			return nil, fmt.Errorf("unexpected token while parsing list: %s", tok.Type)
		}
	}
}

func (p *jsonParser) literalType() (*LiteralType, error) {
	return &LiteralType{Token: p.tok.hclToken()}, nil
}

func (p *jsonParser) scan() jsonToken {
	if p.n != 0 {
		p.n = 0
		return p.tok
	}
	p.tok = p.sc.Scan()
	return p.tok
}

func flattenObjects(node Node) {
	walk(node, func(n Node) (Node, bool) {
		list, ok := n.(*ObjectList)
		if !ok {
			return n, true
		}
		items := make([]*ObjectItem, 0, len(list.Items))
		frontier := make([]*ObjectItem, len(list.Items))
		copy(frontier, list.Items)
		for len(frontier) > 0 {
			n := len(frontier)
			item := frontier[n-1]
			frontier = frontier[:n-1]
			switch v := item.Val.(type) {
			case *ObjectType:
				items, frontier = flattenObjectType(v, item, items, frontier)
			case *ListType:
				items, frontier = flattenListType(v, item, items, frontier)
			default:
				items = append(items, item)
			}
		}
		for i := len(items)/2 - 1; i >= 0; i-- {
			opp := len(items) - 1 - i
			items[i], items[opp] = items[opp], items[i]
		}
		list.Items = items
		return n, true
	})
}

func flattenListType(ot *ListType, item *ObjectItem, items []*ObjectItem, frontier []*ObjectItem) ([]*ObjectItem, []*ObjectItem) {
	if len(ot.List) == 0 {
		items = append(items, item)
		return items, frontier
	}
	for _, subitem := range ot.List {
		if _, ok := subitem.(*ObjectType); !ok {
			items = append(items, item)
			return items, frontier
		}
	}
	for _, elem := range ot.List {
		frontier = append(frontier, &ObjectItem{
			Keys:   item.Keys,
			Assign: item.Assign,
			Val:    elem,
		})
	}
	return items, frontier
}

func flattenObjectType(ot *ObjectType, item *ObjectItem, items []*ObjectItem, frontier []*ObjectItem) ([]*ObjectItem, []*ObjectItem) {
	if ot.List.Items == nil {
		items = append(items, item)
		return items, frontier
	}
	for _, subitem := range ot.List.Items {
		if _, ok := subitem.Val.(*ObjectType); !ok {
			items = append(items, item)
			return items, frontier
		}
	}
	for _, subitem := range ot.List.Items {
		keys := make([]*ObjectKey, len(item.Keys)+len(subitem.Keys))
		copy(keys, item.Keys)
		copy(keys[len(item.Keys):], subitem.Keys)
		frontier = append(frontier, &ObjectItem{
			Keys:   keys,
			Assign: item.Assign,
			Val:    subitem.Val,
		})
	}
	return items, frontier
}

type walkFunc func(Node) (Node, bool)

func walk(node Node, fn walkFunc) Node {
	rewritten, ok := fn(node)
	if !ok {
		return rewritten
	}
	switch n := node.(type) {
	case *File:
		n.Node = walk(n.Node, fn).(*ObjectList)
	case *ObjectList:
		for i, item := range n.Items {
			n.Items[i] = walk(item, fn).(*ObjectItem)
		}
	case *ObjectKey:
	case *ObjectItem:
		for i, k := range n.Keys {
			n.Keys[i] = walk(k, fn).(*ObjectKey)
		}
		if n.Val != nil {
			n.Val = walk(n.Val, fn)
		}
	case *LiteralType:
	case *ListType:
		for i, l := range n.List {
			n.List[i] = walk(l, fn)
		}
	case *ObjectType:
		n.List = walk(n.List, fn).(*ObjectList)
	}
	return rewritten
}
