		return p.output(t.Node)
	case *ObjectList:
		for index := 0; index < len(t.Items); index++ {
			buf.Write(p.output(t.Items[index]))
			if index != len(t.Items)-1 {
				buf.WriteByte(newline)
				buf.WriteByte(newline)
			}
		}
	case *ObjectItem:
		buf.Write(p.objectItem(t))
	case *LiteralType:
		buf.Write([]byte(t.Token.Text))
	case *ListType:
		buf.Write(p.list(t))
	case *ObjectType:
		buf.Write(p.objectType(t))
	}
	return buf.Bytes()
}

func (p *printer) objectItem(o *ObjectItem) []byte {
	var buf bytes.Buffer
	for i, k := range o.Keys {
		buf.WriteString(k.Token.Text)
		buf.WriteByte(blank)
		if o.Assign.IsValid() && i == len(o.Keys)-1 && len(o.Keys) == 1 {
			buf.WriteString("=")
			buf.WriteByte(blank)
		}
	}
	buf.Write(p.output(o.Val))
	return buf.Bytes()
}

func lines(txt string) int {
	endline := 1
	for i := 0; i < len(txt); i++ {
		if txt[i] == '\n' {
			endline++
		}
	}
	return endline
}

func (p *printer) objectType(o *ObjectType) []byte {
	var buf bytes.Buffer
	buf.WriteString("{")
	index := 0
	newlinePrinted := false
	for {
		if index == len(o.List.Items) {
			break
		}
		if !newlinePrinted {
			buf.WriteByte(newline)
			newlinePrinted = true
		}
		var aligned []*ObjectItem
		for _, item := range o.List.Items[index:] {
			if _, ok := item.Val.(*ListType); ok {
				break
			}
			cur := lines(string(p.objectItem(item)))
			if cur > 2 {
				break
			}
			curPos := item.Pos()
			nextPos := Pos{}
			if index != len(o.List.Items)-1 {
				nextPos = o.List.Items[index+1].Pos()
			}
			prevPos := Pos{}
			if index != 0 {
				prevPos = o.List.Items[index-1].Pos()
			}
			if curPos.Line+1 == nextPos.Line {
				aligned = append(aligned, item)
				index++
				continue
			}
			if curPos.Line-1 == prevPos.Line {
				aligned = append(aligned, item)
				index++
				if curPos.Line+1 != nextPos.Line {
					break
				}
				continue
			}
			break
		}
		if index != len(aligned) {
			buf.WriteByte(newline)
		}
		if len(aligned) >= 1 {
			buf.Write(p.indent(p.alignedItems(aligned)))
		} else {
			buf.Write(p.indent(p.objectItem(o.List.Items[index])))
			index++
		}
		buf.WriteByte(newline)
	}
	buf.WriteString("}")
	return buf.Bytes()
}

func (p *printer) alignedItems(items []*ObjectItem) []byte {
	var buf bytes.Buffer
	var longestKeyLen int
	for _, item := range items {
		key := len(item.Keys[0].Token.Text)
		if key > longestKeyLen {
			longestKeyLen = key
		}
	}
	for i, item := range items {
		for i, k := range item.Keys {
			keyLen := len(k.Token.Text)
			buf.WriteString(k.Token.Text)
			for i := 0; i < longestKeyLen-keyLen+1; i++ {
				buf.WriteByte(blank)
			}
			if i == len(item.Keys)-1 && len(item.Keys) == 1 {
				buf.WriteString("=")
				buf.WriteByte(blank)
			}
		}
		buf.Write(p.output(item.Val))
		if i != len(items)-1 {
			buf.WriteByte(newline)
		}
	}
	return buf.Bytes()
}

func (p *printer) list(l *ListType) []byte {
	if p.isSingleLineList(l) {
		return p.singleLineList(l)
	}
	var buf bytes.Buffer
	buf.WriteString("[")
	buf.WriteByte(newline)
	for _, item := range l.List {
		val := p.output(item)
		buf.Write(p.indent(val))
		if lit, ok := item.(*LiteralType); ok && lit.Token.Type == HEREDOC {
			buf.WriteByte(newline)
			buf.Write(p.indent([]byte(",")))
		} else {
			buf.WriteString(",")
		}
		buf.WriteByte(newline)
	}
	buf.WriteString("]")
	return buf.Bytes()
}

func (p *printer) isSingleLineList(l *ListType) bool {
	for _, item := range l.List {
		if item.Pos().Line != l.Lbrack.Line {
			return false
		}
		lit, ok := item.(*LiteralType)
		if !ok {
			return false
		}
		if lit.Token.Type == HEREDOC && len(l.List) != 1 {
			return false
		}
	}
	return true
}

func (p *printer) singleLineList(l *ListType) []byte {
	var buf bytes.Buffer
	buf.WriteString("[")
	for i, item := range l.List {
		if i != 0 {
			buf.WriteString(", ")
		}
		buf.Write(p.output(item))
		if lit, ok := item.(*LiteralType); ok && lit.Token.Type == HEREDOC {
			buf.WriteByte(newline)
		}
	}
	buf.WriteString("]")
	return buf.Bytes()
}

func (p *printer) indent(buf []byte) []byte {
	prefix := bytes.Repeat([]byte{blank}, p.spacesWidth)
	var res []byte
	bol := true
	for _, c := range buf {
		if bol && c != '\n' {
			res = append(res, prefix...)
		}
		res = append(res, c)
		bol = c == '\n'
	}
	return res
}
