func decodeHCLList(list *hcl.ObjectList) (order.MapSlice, error) {
	out := order.MapSlice{}
	done := map[string]bool{}
	for _, item := range list.Items {
		if len(item.Keys) == 0 {
			return nil, fmt.Errorf("empty key at line %d", item.Pos().Line)
		}
		key := item.Keys[0].Token.Value().(string)
		if done[key] {
