func decodeHCLValue(n hcl.Node, inList bool) (interface{}, error) {
	switch n := n.(type) {
	case *hcl.LiteralType:
		switch n.Token.Type {
		case hcl.NUMBER:
			v, err := strconv.ParseInt(n.Token.Text, 0, 0)
			if err != nil {
				return nil, err
			}
			return int(v), nil
		case hcl.FLOAT:
			v, err := strconv.ParseFloat(n.Token.Text, 64)
			if err != nil {
				return nil, err
			}
			return v, nil
		case hcl.BOOL:
			return n.Token.Value(), nil
		case hcl.STRING, hcl.HEREDOC:
			return n.Token.Value(), nil
		}
		return nil, &hcl.PosError{Pos: n.Pos(), Err: fmt.Errorf("cannot decode into interface: %T", n)}
	case *hcl.ListType:
		out := make([]interface{}, 0, len(n.List))
		for _, e := range n.List {
			v, err := decodeHCLValue(e, true)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case *hcl.ObjectType:
		m, err := decodeHCLList(n.List)
		if err != nil {
			return nil, err
		}
		if inList {
			return m, nil
		}
		return []interface{}{m}, nil
	}
	return nil, fmt.Errorf("cannot decode into interface: %T", n)
}

func hclAdd(m order.MapSlice, key string, val interface{}) (order.MapSlice, error) {
	idx := -1
	for i := range m {
		if m[i].Key == key {
			idx = i
			break
		}
	}
	newSlice, newIsSlice := val.([]interface{})
	if idx < 0 {
		if newIsSlice {
			if len(newSlice) == 0 {
				return m, nil
			}
			cp := make([]interface{}, len(newSlice))
			copy(cp, newSlice)
			return append(m, order.MapItem{Key: key, Val: cp}), nil
		}
		return append(m, order.MapItem{Key: key, Val: val}), nil
	}
	existing := m[idx].Val
	if es, ok := existing.([]interface{}); ok {
		if !newIsSlice {
			return nil, fmt.Errorf("cannot set '%#v' over '%#v", val, existing)
		}
		m[idx].Val = append(es, newSlice...)
		return m, nil
	}
	if newIsSlice {
		if len(newSlice) > 0 {
			return nil, fmt.Errorf("cannot append '%#v' to '%#v", newSlice[0], existing)
		}
		return m, nil
	}
	m[idx].Val = val
	return m, nil
}

func encodeHCL(cfg *config, v interface{}) ([]byte, error) {
	b, err := jsonenc.Marshal(v, jsonenc.Options{})
	if err != nil {
		return nil, err
	}
	f, err := hcl.ParseJSON(b)
	if err != nil {
		return nil, err
	}
