// Package order provides an ordered map representation shared by all formats.
package order

import (
	"bytes"
	"encoding/json"
	"fmt"
)

// MapItem is a single key/value pair of an ordered map.
type MapItem struct {
	Key, Val interface{}
}

// MapSlice is an ordered map.
type MapSlice []MapItem

// MarshalJSON writes the map preserving key order.
func (m MapSlice) MarshalJSON() ([]byte, error) {
	buf := &bytes.Buffer{}
	buf.WriteByte('{')
	for i, item := range m {
		if i != 0 {
			buf.WriteByte(',')
		}
		fmt.Fprintf(buf, "%q:", item.Key)
		enc := json.NewEncoder(buf)
		enc.SetEscapeHTML(false)
		if err := enc.Encode(item.Val); err != nil {
			return nil, err
		}
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}
