// Package jsonenc writes ordered values as JSON text.
package jsonenc

import (
	"bytes"
	"encoding/json"
	"math"

	"yj/order"
)

// Options control the JSON output.
type Options struct {
	EscapeHTML bool
	Indent     bool
}

// clampFloats replaces values JSON cannot represent.
func clampFloats(v interface{}) interface{} {
	switch v := v.(type) {
	case float64:
		switch {
		case math.IsInf(v, 1):
			return math.MaxFloat64
		case math.IsInf(v, -1):
			return -math.MaxFloat64
		case math.IsNaN(v):
			return nil
		}
		return v
	case []interface{}:
		out := make([]interface{}, len(v))
		for i, x := range v {
			out[i] = clampFloats(x)
		}
		return out
	case order.MapSlice:
		out := make(order.MapSlice, len(v))
		for i, item := range v {
			out[i] = order.MapItem{Key: item.Key, Val: clampFloats(item.Val)}
		}
		return out
	}
	return v
}

// Encode renders v as JSON followed by a newline.
func Encode(v interface{}, opts Options) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(opts.EscapeHTML)
	if opts.Indent {
		enc.SetIndent("", "  ")
	}
	if err := enc.Encode(clampFloats(v)); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// Marshal renders v as JSON without a trailing newline.
func Marshal(v interface{}, opts Options) ([]byte, error) {
	b, err := Encode(v, opts)
	if err != nil {
		return nil, err
	}
	return bytes.TrimSuffix(b, []byte("\n")), nil
}
