// Package jsonenc writes ordered values as JSON text.
//
// The output mirrors encoding/json with an ordered map type that implements
// json.Marshaler by quoting its keys with %q and encoding values without
// HTML escaping.
package jsonenc

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"strconv"
	"time"
	"unicode/utf8"

	"yj/order"
)

// Options control the JSON output.
type Options struct {
	EscapeHTML bool
	Indent     bool
}

type marshalerError struct {
	typ string
	err error
}

func (e *marshalerError) Error() string {
	return "json: error calling MarshalJSON for type " + e.typ + ": " + e.err.Error()
}

func clampFloat(f float64) (float64, bool) {
	switch {
	case math.IsInf(f, 1):
		return math.MaxFloat64, true
	case math.IsInf(f, -1):
		return -math.MaxFloat64, true
	case math.IsNaN(f):
		return 0, false
	}
	return f, true
}

func appendValue(dst []byte, v interface{}, escapeHTML bool) ([]byte, error) {
	switch v := v.(type) {
	case nil:
		return append(dst, "null"...), nil
	case bool:
		return strconv.AppendBool(dst, v), nil
	case string:
		return appendString(dst, v, escapeHTML), nil
	case int:
		return strconv.AppendInt(dst, int64(v), 10), nil
	case int64:
		return strconv.AppendInt(dst, v, 10), nil
	case uint64:
		return strconv.AppendUint(dst, v, 10), nil
	case float64:
		f, ok := clampFloat(v)
		if !ok {
			return append(dst, "null"...), nil
		}
		return appendFloat(dst, f), nil
	case time.Time:
		if y := v.Year(); y < 0 || y >= 10000 {
			return nil, &marshalerError{"time.Time", errors.New("Time.MarshalJSON: year outside of range [0,9999]")}
		}
		dst = append(dst, '"')
		dst = v.AppendFormat(dst, time.RFC3339Nano)
		return append(dst, '"'), nil
	case []interface{}:
		dst = append(dst, '[')
		for i, x := range v {
			if i > 0 {
				dst = append(dst, ',')
			}
			var err error
			dst, err = appendValue(dst, x, escapeHTML)
			if err != nil {
				return nil, err
			}
		}
		return append(dst, ']'), nil
	case order.MapSlice:
		b, err := marshalMapSlice(v)
		if err != nil {
			return nil, &marshalerError{"order.MapSlice", err}
		}
		var buf bytes.Buffer
		if err := json.Compact(&buf, b); err != nil {
			return nil, &marshalerError{"order.MapSlice", err}
		}
		out := buf.Bytes()
		if escapeHTML {
			var esc bytes.Buffer
			json.HTMLEscape(&esc, out)
			out = esc.Bytes()
		}
		return append(dst, out...), nil
	}
	return nil, fmt.Errorf("json: unsupported type: %T", v)
}

// marshalMapSlice mirrors the ordered map's MarshalJSON method.
func marshalMapSlice(m order.MapSlice) ([]byte, error) {
	buf := []byte{'{'}
	for i, item := range m {
		if i != 0 {
			buf = append(buf, ',')
		}
		buf = append(buf, fmt.Sprintf("%q:", item.Key)...)
